const std::wstring APP_TITLE = L"Last War-Finder";
// ===== Fix 253: UI language = Windows display language, pill words = game language (English fallback) =====
// Order of the 16 columns: en de fr ru ko th ja pt es tr zh(Traditional) it ar vi id pl (same as the game tables).
static const char* const LWF_LANGS[16] = { "en", "de", "fr", "ru", "ko", "th", "ja", "pt", "es", "tr", "zh", "it", "ar", "vi", "id", "pl" };
static int g_uiLangForce = -1;     // --lang xx (tests)
static int g_gameLangForce = -1;   // --gamelang xx (tests)
static std::atomic<int> g_gameLangIdx{ 0 };   // pill language: English until the game language is detected
static int LwfLangIndexW(const wchar_t* c) {
    if (!c || !c[0] || !c[1]) return -1;
    for (int i = 0; i < 16; ++i) if (towlower(c[0]) == (wchar_t)LWF_LANGS[i][0] && towlower(c[1]) == (wchar_t)LWF_LANGS[i][1] && (c[2] == 0 || c[2] == L'-' || c[2] == L'_')) return i;
    return -1;
}
static int LwfLangIndexA(const char* c) {
    if (!c) return -1;
    wchar_t w[4] = {};
    for (int i = 0; i < 3 && c[i]; ++i) w[i] = (wchar_t)(unsigned char)c[i];
    return LwfLangIndexW(w);
}
static int UiLang() {
    if (g_uiLangForce >= 0) return g_uiLangForce;
    static int s = -1;
    if (s < 0) {
        int r = 0;
        wchar_t ln[LOCALE_NAME_MAX_LENGTH] = {};
        if (LCIDToLocaleName(MAKELCID(GetUserDefaultUILanguage(), SORT_DEFAULT), ln, LOCALE_NAME_MAX_LENGTH, 0) > 0) { const int i = LwfLangIndexW(ln); if (i >= 0) r = i; }
        s = r;
    }
    return s;
}
// Fix 256: game language from the game's own settings (Unity PlayerPrefs "Setting.USER_LANGUAGE_LOCALE_h...", binary "de\0"), read every
// 2 s from the UI timer (one registry read) -> pill words follow a language switch in the game at once. Log texts are not affected.
static std::atomic<int> g_gameLangPrefs{ -1 };
static const wchar_t* GAME_PREFS_PATH = L"Software\\FunFly\\Last War-Survival Game";
static int GameLangFromPrefs() {
    static std::wstring s_name;
    static ULONGLONG s_enumT = 0;
    HKEY k = nullptr;
    if (RegOpenKeyExW(HKEY_CURRENT_USER, GAME_PREFS_PATH, 0, KEY_READ, &k) != ERROR_SUCCESS) return -1;
    BYTE buf[40] = {}; DWORD type = 0, n = sizeof(buf) - 2;
    LSTATUS st = s_name.empty() ? ERROR_FILE_NOT_FOUND : RegQueryValueExW(k, s_name.c_str(), nullptr, &type, buf, &n);
    if (st != ERROR_SUCCESS && (s_enumT == 0 || GetTickCount64() - s_enumT >= 60000)) {   // value name (hash suffix) looked up once, retried at most every 60 s
        s_enumT = std::max<ULONGLONG>(1, GetTickCount64());
        s_name.clear();
        static const wchar_t P[] = L"Setting.USER_LANGUAGE_LOCALE_h";
        for (DWORD i = 0; i < 20000; ++i) {
            wchar_t nm[160]; DWORD nl = 160;
            const LSTATUS e = RegEnumValueW(k, i, nm, &nl, nullptr, nullptr, nullptr, nullptr);
            if (e == ERROR_NO_MORE_ITEMS) break;
            if (e == ERROR_SUCCESS && wcsncmp(nm, P, (sizeof(P) / sizeof(P[0])) - 1) == 0) { s_name = nm; break; }
        }
        n = sizeof(buf) - 2; type = 0;
        st = s_name.empty() ? ERROR_FILE_NOT_FOUND : RegQueryValueExW(k, s_name.c_str(), nullptr, &type, buf, &n);
    }
    RegCloseKey(k);
    if (st != ERROR_SUCCESS || n == 0) return -1;
    wchar_t c[8] = {};
    if (type == REG_BINARY) { for (DWORD i = 0; i < n && i < 7 && buf[i]; ++i) c[i] = (wchar_t)buf[i]; }
    else if (type == REG_SZ) { const wchar_t* w = (const wchar_t*)buf; for (int i = 0; i < 7 && (DWORD)(i * 2) < n && w[i]; ++i) c[i] = w[i]; }
    else return -1;
    if (towlower(c[0]) == L'i' && towlower(c[1]) == L'n' && (c[2] == 0 || c[2] == L'-' || c[2] == L'_')) { c[0] = L'i'; c[1] = L'd'; }   // old code for Indonesian
    return LwfLangIndexW(c);
}
static int PillLang() { return g_gameLangForce >= 0 ? g_gameLangForce : (g_gameLangPrefs.load() >= 0 ? g_gameLangPrefs.load() : g_gameLangIdx.load()); }
static std::atomic<bool> g_gameLangIdxSet{ false };   // Fix 257: the language probe has found the game language
static void LwfSetGameLang(const std::string& code) { const int i = LwfLangIndexA(code.c_str()); if (i >= 0) { g_gameLangIdx = i; g_gameLangIdxSet = true; } }
// Fix 257: language of the GAME for log rows and bubbles (forced, game settings, probe); -1 = not known yet (nothing is re-rendered)
static int LogGameLang() { return g_gameLangForce >= 0 ? g_gameLangForce : (g_gameLangPrefs.load() >= 0 ? g_gameLangPrefs.load() : (g_gameLangIdxSet.load() ? g_gameLangIdx.load() : -1)); }
static std::wstring LogWordToLang(const std::wstring& w, int lang);   // Fix 257 (defined below LUCKY_LANG_PATTERNS)
static std::wstring LogZoneToLang(const std::wstring& z, int lang);
static std::wstring LogWordGameLang(const std::wstring& w) { const int l = LogGameLang(); return l >= 0 ? LogWordToLang(w, l) : w; }
static void LogRelang(int lang);
static void BubbleRelang();
static void SeenStoreSave();
static void LwfParseLangArgs() {
    int argc = 0;
    if (LPWSTR* av = CommandLineToArgvW(GetCommandLineW(), &argc)) {
        for (int i = 1; i + 1 < argc; ++i) {
            if (wcscmp(av[i], L"--lang") == 0) g_uiLangForce = LwfLangIndexW(av[i + 1]);
            else if (wcscmp(av[i], L"--gamelang") == 0) g_gameLangForce = LwfLangIndexW(av[i + 1]);
        }
        LocalFree(av);
    }
}
