static int LogDayKey(const wchar_t* p) {   // "JJJJ-MM-TT" -> JJJJMMTT (ungültig -> 0)
    int v = 0;
    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) { if (p[i] != L'-') return 0; continue; }
        if (p[i] < L'0' || p[i] > L'9') return 0;
        v = v * 10 + (p[i] - L'0');
    }
    return v;
}
