static LONG LogHiddenEnd(LONG p) {   // Fix 214: Ende des ausgeblendeten Bereichs, in dem p liegt; p, wenn sichtbar
    auto it = std::upper_bound(g_logHid.begin(), g_logHid.end(), p, [](LONG v, const std::pair<LONG, LONG>& r) { return v < r.first; });
    if (it == g_logHid.begin()) return p;
    --it;
    return p < it->second ? it->second : p;
}
static bool LogHiddenAt(LONG p) { return LogHiddenEnd(p) > p; }
static LONG LogSkipHidden(LONG p) {   // Fix 214: erste sichtbare Stelle ab p
    if (p < 0) return p;
    for (LONG e = LogHiddenEnd(p); e > p; e = LogHiddenEnd(p)) p = e;
    return p;
}
static void LogHidReset() { g_logHid.clear(); g_logHidDirty.clear(); g_logHidFrom = LOG_HID_NONE; }   // Fix 214: neuer bzw. leerer Inhalt
static void LogHidDirty(LONG a, LONG b) { if (!g_logHid.empty()) g_logHidDirty.push_back({ a, b }); }
static void LogHidUnsure(LONG at) { if (!g_logHid.empty()) g_logHidFrom = std::min(g_logHidFrom, std::max<LONG>(0, at)); }
// Fix 214: aus LuckyLogShift (Text ab at um delta verschoben). Vorübergehende Verschiebungen um 1 << 29 (LogMoveTailTo / LogFixDigTime)
// betreffen nur die gerade bewegte Zeile -> hier nicht mitgeführt (LogFixDigTime meldet den unsicheren Bereich mit LogHidUnsure).
static void LogHidShift(LONG at, LONG delta) {
    if (g_logHid.empty()) return;   // nichts ausgeblendet -> eingefügter Text kann nichts erben
    if (at >= (1 << 28) || delta >= (1 << 28) || delta <= -(1 << 28)) return;
    auto mv = [&](LONG& v, bool end) { if (end ? v > at : v >= at) v = std::max<LONG>(0, v + delta); };
    for (auto& r : g_logHid) { mv(r.first, false); mv(r.second, true); }
    for (auto& r : g_logHidDirty) { mv(r.first, false); mv(r.second, true); }
    if (g_logHidFrom != LOG_HID_NONE && g_logHidFrom >= at) g_logHidFrom = std::max<LONG>(0, g_logHidFrom + delta);
    g_logHid.erase(std::remove_if(g_logHid.begin(), g_logHid.end(), [](const std::pair<LONG, LONG>& r) { return r.second <= r.first; }), g_logHid.end());
    const LONG a = delta > 0 ? at : std::max<LONG>(0, at + delta);
    g_logHidDirty.push_back({ a, delta > 0 ? at + delta : a });
}
static void LogHidTrim(LONG cut) {   // Fix 214: vorne cut Zeichen gelöscht (vor LuckyLogShift(cut, -cut))
    auto trim = [cut](std::vector<std::pair<LONG, LONG>>& v) {
        v.erase(std::remove_if(v.begin(), v.end(), [cut](const std::pair<LONG, LONG>& r) { return r.second < cut || (r.second == cut && r.first < cut); }), v.end());
        for (auto& r : v) r.first = std::max(r.first, cut);
    };
    trim(g_logHid);
    trim(g_logHidDirty);
    if (g_logHidFrom != LOG_HID_NONE && g_logHidFrom < cut) g_logHidFrom = cut;
}
