static int F377Elevated(DWORD* rid) {             // FIX377: 1 elevated, 0 not, -1 unknown; rid = integrity RID (0x2000 medium, 0x3000 high)
    if (rid) *rid = 0;
    HANDLE tk = nullptr; if (!OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &tk)) return -1;
    TOKEN_ELEVATION te{}; DWORD n = 0; int r = -1;
    if (GetTokenInformation(tk, TokenElevation, &te, sizeof(te), &n)) r = te.TokenIsElevated ? 1 : 0;
    alignas(8) BYTE buf[96] = {};
    if (rid && GetTokenInformation(tk, TokenIntegrityLevel, buf, sizeof(buf), &n)) {
        PSID sid = ((TOKEN_MANDATORY_LABEL*)buf)->Label.Sid;
        if (sid && IsValidSid(sid)) *rid = *GetSidSubAuthority(sid, (DWORD)(*GetSidSubAuthorityCount(sid) - 1));
    }
    CloseHandle(tk); return r;
}
