// FIX378: scan phase timings, targeted slot hunt for new unpaired dig JSON (same matching code, non-full pass), slot region diagnostics
static inline long long F378Q() { LARGE_INTEGER q; QueryPerformanceCounter(&q); return q.QuadPart; }
static long long g_f378Acc[8] = {};               // QPC ticks: 0 prep 1 read 2 zws 3 text 4 json 5 posttime 6 lucky 7 finish
static unsigned long long g_f378Bytes = 0;        // bytes read this pass
#define F378_MARK(i) { const long long n378 = F378Q(); g_f378Acc[i] += n378 - q378; q378 = n378; }
static std::unordered_map<uintptr_t, SIZE_T> g_f378Last;          // regions of the last full scan (base -> size)
static std::vector<std::pair<uintptr_t, SIZE_T>> g_f378Cur;      // regions of the running full scan
static int g_f378HuntPasses = 0;                  // remaining hunt passes
static bool g_f378HuntPass = false;               // this pass scans extra hunt regions
static unsigned g_f378HuntNew = 0, g_f378HuntNear = 0; static unsigned long long g_f378HuntBytes = 0;
static unsigned g_f378SlotLogs = 0;
static std::unordered_set<uintptr_t> g_f379HotStart;   // FIX379: hot regions at pass start
static bool g_f379HuntNow = false;                     // FIX379: new dig JSON in this non-full pass -> extend this pass
static bool g_f379Dirty = false;                       // FIX379: new slot or JSON this pass -> try pairing mid-pass
static unsigned g_f379HuntRest = 0;                    // FIX379: other regions added by an all-region hunt
static constexpr unsigned long long F378_HUNT_CAP = 256ULL * 1024 * 1024;   // max extra bytes per hunt pass
static constexpr long long F378_NEAR = 64LL * 1024 * 1024;                   // +-64 MB around a pending JSON
static const char* F378RegionState(uintptr_t base, SIZE_T size) {
    if (g_f378Last.empty()) return "nofull";
    auto it = g_f378Last.find(base);
    if (it == g_f378Last.end()) return "new";
    return it->second == size ? "same" : "resized";
}
// add non-hot readable regions: new/resized since the last full scan, or near a pending dig JSON; nearest first, capped
static bool F378AddHunt(HANDLE hp, LPCVOID start, LPCVOID end, std::vector<LPCVOID>& regs, bool all = false) {   // FIX379: all = every other readable region too, no cap
    g_f378HuntNew = g_f378HuntNear = 0; g_f378HuntBytes = 0; g_f379HuntRest = 0;
    std::unordered_set<uintptr_t> have379; for (LPCVOID r : regs) have379.insert((uintptr_t)r);
    const ULONGLONG now = GetTickCount64();
    std::vector<uintptr_t> jsonAt;
    for (auto& kv : g_pendingMsgs) if (kv.second.f378Hunt && kv.second.f378Addr && now - kv.second.firstTick < 120000ULL) jsonAt.push_back(kv.second.f378Addr);
    struct C { long long pri; uintptr_t base; SIZE_T size; bool isNew; };
    std::vector<C> cand;
    MEMORY_BASIC_INFORMATION m;
    LPCVOID a = start;
    while (a < end) {
        if (VirtualQueryEx(hp, a, &m, sizeof(m)) == 0) break;
        const uintptr_t b = (uintptr_t)m.BaseAddress;
        if (m.State == MEM_COMMIT && m.Type == MEM_PRIVATE && (m.Protect & 0xFF) == PAGE_READWRITE && !(m.Protect & PAGE_GUARD) &&
            m.RegionSize > 0 && !g_hotRegions.count(b) && !have379.count(b)) {
            const char* st = F378RegionState(b, m.RegionSize);
            const bool isNew = (st[0] == 'n' && st[1] == 'e') || st[0] == 'r';
            long long dist = 1LL << 50;
            for (uintptr_t j : jsonAt) {
                long long d = 0;
                if (j < b) d = (long long)(b - j); else if (j >= b + m.RegionSize) d = (long long)(j - (b + m.RegionSize));
                if (d < dist) dist = d;
            }
            const bool isNear = dist <= F378_NEAR;
            if (isNew || isNear) cand.push_back({ (isNew ? 0LL : (1LL << 52)) + dist, b, m.RegionSize, isNew });
            else if (all) cand.push_back({ (1LL << 60) + (long long)(b >> 12), b, m.RegionSize, false });
        }
        a = (LPCVOID)(b + m.RegionSize);
    }
    std::sort(cand.begin(), cand.end(), [](const C& x, const C& y) { return x.pri < y.pri; });
    for (const C& c : cand) {
        if (!all && g_f378HuntBytes + c.size > F378_HUNT_CAP) continue;
        g_f378HuntBytes += c.size;
        regs.push_back((LPCVOID)c.base);
        if (c.isNew) ++g_f378HuntNew; else if (c.pri < (1LL << 60)) ++g_f378HuntNear; else ++g_f379HuntRest;
    }
    return g_f378HuntNew + g_f378HuntNear + g_f379HuntRest > 0;
}
