// ===== FIX364: auto-collect a clicked dig once it is finished (data side; worker + Lua install see FIX364 block before wWinMain) =====
// FIX318 REPORT notes every reported dig (sid, X, Y, treasureId, post uuid); CnJump only queues the clicked coordinate (cheap).
struct Dig364 { int sid = 0, x = 0, y = 0; unsigned long long tid = 0, uuid = 0; ULONGLONG ms = 0; long long ep516 = 0; };
static std::mutex g_mx364;
static std::vector<Dig364> g_digs364;                 // recent reported digs, max 500 / 24 h
static std::vector<Dig364> g_savedDigs518;            // FIX518: saved digs for passive manual-claim coordinate lookup only (never alters click/F364Worker)
static std::vector<std::pair<int, int>> g_clk364;     // clicked coordinates (CnJump) for the worker
static std::atomic<ULONGLONG> g_clickMs364{ 0 };
static std::atomic<bool> g_seen364{ false };          // a dig was reported -> worker installs the Lua side ahead of time
static HANDLE g_ev364 = nullptr;
static void F364Start();                              // FIX364: defined before wWinMain
static void F364Note(int sid, int x, int y, unsigned long long tid, unsigned long long uuid) {
    try {
        const ULONGLONG now = GetTickCount64();
        {
            std::lock_guard<std::mutex> lk(g_mx364);
            for (auto it = g_digs364.begin(); it != g_digs364.end();) { if (it->uuid == uuid || now - it->ms > 86400000ull) it = g_digs364.erase(it); else ++it; }
            if (g_digs364.size() >= 500) g_digs364.erase(g_digs364.begin());
            Dig364 d; d.sid = sid; d.x = x; d.y = y; d.tid = tid; d.uuid = uuid; d.ms = now; d.ep516 = (long long)time(nullptr); g_digs364.push_back(d);
        }
        g_seen364 = true;
        F364Start();
        if (g_ev364) SetEvent(g_ev364);
    } catch (...) {}
}
static void F364OnJump(int x, int y) {   // UI thread: queue + event only, the jump itself is not delayed
    try {
        { std::lock_guard<std::mutex> lk(g_mx364); if (g_clk364.size() < 64) g_clk364.emplace_back(x, y); }
        g_clickMs364 = GetTickCount64();
        F364Start();
        if (g_ev364) SetEvent(g_ev364);
    } catch (...) {}
}
// ===== FIX367 (UI thread): dig / drone rows collected by the Finder in this session -> green check right of the pin,
// counters "collected/total". Key = (sid << 48) | (X << 24) | Y from the row text "[... \u200E#sid X:x Y:y]". Session only
// (not saved: SAVE/LOAD format unchanged) -> loaded rows show the open circle; an older row with the same sid/X/Y turns green too.
static std::unordered_map<long long, int> g_done367;   // key -> kind (0 dig, 1 drone)
static long long F367Key(int sid, int x, int y) { return ((long long)(sid & 0xFFFF) << 48) | ((long long)(x & 0xFFFFFF) << 24) | (long long)(y & 0xFFFFFF); }
static int F367Dig(std::wstring_view s, size_t& p) { int v = 0, n = 0; while (p < s.size() && s[p] >= L'0' && s[p] <= L'9' && n < 9) { v = v * 10 + (int)(s[p] - L'0'); ++p; ++n; } return n ? v : -1; }
static long long F367RowKey(std::wstring_view ln) {   // -1 = no dig / drone coordinate in this row
    const size_t hp = ln.rfind(L"\u200E#"); if (hp == std::wstring_view::npos) return -1;
    size_t p = hp + 2; const int sid = F367Dig(ln, p); if (sid < 0) return -1;
    const size_t xp = ln.find(L" X:", p); if (xp == std::wstring_view::npos) return -1;
    p = xp + 3; const int x = F367Dig(ln, p); if (x < 0) return -1;
    const size_t yp = ln.find(L" Y:", p); if (yp == std::wstring_view::npos) return -1;
    p = yp + 3; const int y = F367Dig(ln, p); if (y < 0) return -1;
    return F367Key(sid, x, y);
}
static bool F367RowDone(std::wstring_view ln) { if (g_done367.empty()) return false; const long long k = F367RowKey(ln); return k >= 0 && g_done367.count(k) != 0; }
static void F367DrawRing(HWND hwnd, HDC dc, HDC mem, int x, int y, LONG idx, LONG total);   // FIX367: defined after DrawClaimChecks
