// ---- Text (DirectWrite) ----
struct BubbleTextEngine {
    bool tried = false;
    IDWriteFactory* dw = nullptr;
    IDWriteFontCollection* coll = nullptr;   // eingebettete Schrift (nullptr = Systemschriften)
    std::wstring family = L"Segoe UI";
    wchar_t locale[LOCALE_NAME_MAX_LENGTH] = L"en-us";
    float capR = 0.70f, xR = 0.52f;
    IDWriteFactory5* f5 = nullptr; IDWriteInMemoryFontFileLoader* ld = nullptr; ULONGLONG lastUse = 0;   // Fix 252: zum Freigeben im Leerlauf
};
static BubbleTextEngine g_bubbleTe;
static bool g_bubbleTeIsolated = false;   // Fix 255: nur der Testlauf misst damit den alten Weg (Fix 252)
static BubbleTextEngine& BubbleText() {
    BubbleTextEngine& e = g_bubbleTe;
    e.lastUse = GetTickCount64();
    if (e.tried) return e;
    e.tried = true;
    if (!GetUserDefaultLocaleName(e.locale, LOCALE_NAME_MAX_LENGTH)) wcscpy_s(e.locale, L"en-us");
    // Fix 255: die Engine wird nur noch einmal geladen und bleibt (kein Freigeben/Neuladen vor jeder Blase mehr) -> geteilte Fabrik
    // (nutzt den System-Schriftcache mit, weniger eigener Speicher als die isolierte Fabrik aus Fix 252)
    DWriteCreateFactory(g_bubbleTeIsolated ? DWRITE_FACTORY_TYPE_ISOLATED : DWRITE_FACTORY_TYPE_SHARED, __uuidof(IDWriteFactory), reinterpret_cast<IUnknown**>(&e.dw));
    IDWriteFactory5* f5 = nullptr;
    if (e.dw && SUCCEEDED(e.dw->QueryInterface(__uuidof(IDWriteFactory5), (void**)&f5)) && f5) {
        IDWriteInMemoryFontFileLoader* ld = nullptr;
        IDWriteFontSetBuilder1* sb = nullptr;
        if (SUCCEEDED(f5->CreateInMemoryFontFileLoader(&ld)) && ld && SUCCEEDED(f5->RegisterFontFileLoader(ld)) &&
            SUCCEEDED(f5->CreateFontSetBuilder(&sb)) && sb) {
            int added = 0;
            for (int id : { IDR_FONT_BUBBLE_REG, IDR_FONT_BUBBLE_SEMI }) {
                HRSRC hr = FindResourceW(nullptr, MAKEINTRESOURCEW(id), RT_RCDATA);
                HGLOBAL hg = hr ? LoadResource(nullptr, hr) : nullptr;
                const void* data = hg ? LockResource(hg) : nullptr;
                const DWORD size = hr ? SizeofResource(nullptr, hr) : 0;
                IDWriteFontFile* ff = nullptr;
                if (data && size && SUCCEEDED(ld->CreateInMemoryFontFileReference(f5, data, size, nullptr, &ff)) && ff) {
                    if (SUCCEEDED(sb->AddFontFile(ff))) ++added;
                    ff->Release();
                }
            }
            IDWriteFontSet* fs = nullptr;
            IDWriteFontCollection1* c1 = nullptr;
            if (added && SUCCEEDED(sb->CreateFontSet(&fs)) && fs && SUCCEEDED(f5->CreateFontCollectionFromFontSet(fs, &c1)) && c1) {
                UINT32 idx = 0; BOOL exists = FALSE;
                if (SUCCEEDED(c1->FindFamilyName(L"Plus Jakarta Sans", &idx, &exists)) && exists) { e.coll = c1; e.family = L"Plus Jakarta Sans"; c1 = nullptr; }
            }
            if (c1) c1->Release();
            if (fs) fs->Release();
        }
        if (sb) sb->Release();
        e.f5 = f5; e.ld = ld;   // Fix 252: Loader und Fabrik merken (werden im Leerlauf freigegeben)
    }
    if (e.dw) {   // Versal- und x-Hoehe der Schrift: Text optisch exakt mittig auf Punkt/Icon
        IDWriteFontCollection* col = e.coll;
        if (!col) e.dw->GetSystemFontCollection(&col);
        UINT32 i = 0; BOOL ex = FALSE;
        IDWriteFontFamily* fam = nullptr;
        IDWriteFont* f = nullptr;
        if (col && SUCCEEDED(col->FindFamilyName(e.family.c_str(), &i, &ex)) && ex && SUCCEEDED(col->GetFontFamily(i, &fam)) && fam &&
            SUCCEEDED(fam->GetFirstMatchingFont(DWRITE_FONT_WEIGHT_SEMI_BOLD, DWRITE_FONT_STRETCH_NORMAL, DWRITE_FONT_STYLE_NORMAL, &f)) && f) {
            DWRITE_FONT_METRICS m = {};
            f->GetMetrics(&m);
            if (m.designUnitsPerEm) { e.capR = (float)m.capHeight / m.designUnitsPerEm; e.xR = (float)m.xHeight / m.designUnitsPerEm; }
        }
        if (f) f->Release();
        if (fam) fam->Release();
        if (col && col != e.coll) col->Release();
    }
    return e;
}
// Fix 255: Textformate je (Groesse, Gewicht) einmal anlegen und behalten (statt je Messung/Bild ein neues Format)
struct BubbleTf { float em; DWRITE_FONT_WEIGHT wt; IDWriteTextFormat* tf; };
static std::vector<BubbleTf> g_bubbleTf;
static void BubbleTfClear() { for (auto& x : g_bubbleTf) if (x.tf) x.tf->Release(); g_bubbleTf.clear(); }
#ifdef LWF_HARNESS
static void BubbleTextRelease() {   // nur Testlauf: alten Weg (Freigeben + Neuladen) nachmessen
    BubbleTextEngine& e = g_bubbleTe;
    if (!e.tried) return;
    BubbleTfClear();
    if (e.coll) e.coll->Release();
    if (e.f5 && e.ld) e.f5->UnregisterFontFileLoader(e.ld);
    if (e.ld) e.ld->Release();
    if (e.f5) e.f5->Release();
    if (e.dw) e.dw->Release();
    e.coll = nullptr; e.ld = nullptr; e.f5 = nullptr; e.dw = nullptr;
    e.family = L"Segoe UI";
    e.tried = false;
}
#endif
static IDWriteTextFormat* BubbleFormat(float em, DWRITE_FONT_WEIGHT wt) {
    BubbleTextEngine& e = BubbleText();
    if (!e.dw || em <= 0.0f) return nullptr;
    for (auto& x : g_bubbleTf) if (x.wt == wt && std::fabs(x.em - em) < 0.001f) return x.tf;
    IDWriteTextFormat* tf = nullptr;
    if (FAILED(e.dw->CreateTextFormat(e.family.c_str(), e.coll, wt, DWRITE_FONT_STYLE_NORMAL, DWRITE_FONT_STRETCH_NORMAL, em, e.locale, &tf)) || !tf) return nullptr;
    tf->SetWordWrapping(DWRITE_WORD_WRAPPING_NO_WRAP);
    IDWriteInlineObject* sign = nullptr;
    if (SUCCEEDED(e.dw->CreateEllipsisTrimmingSign(tf, &sign)) && sign) {
        DWRITE_TRIMMING tr = { DWRITE_TRIMMING_GRANULARITY_CHARACTER, 0, 0 };
        tf->SetTrimming(&tr, sign);
        sign->Release();
    }
    if (g_bubbleTf.size() >= 32) { if (g_bubbleTf.front().tf) g_bubbleTf.front().tf->Release(); g_bubbleTf.erase(g_bubbleTf.begin()); }
    g_bubbleTf.push_back({ em, wt, tf });
    return tf;
}
static IDWriteTextLayout* BubbleMakeLayout(const std::wstring& s, float em, DWRITE_FONT_WEIGHT wt, float maxW) {
    BubbleTextEngine& e = BubbleText();
    if (!e.dw || s.empty() || em <= 0.0f) return nullptr;
    IDWriteTextFormat* tf = BubbleFormat(em, wt);
    if (!tf) return nullptr;
    IDWriteTextLayout* lay = nullptr;
    if (FAILED(e.dw->CreateTextLayout(s.c_str(), (UINT32)s.size(), tf, std::max(1.0f, maxW), 4.0f * em + 100.0f, &lay))) lay = nullptr;
    return lay;
}
static float BubbleTextW(const std::wstring& s, float em, DWRITE_FONT_WEIGHT wt) {
    if (s.empty()) return 0.0f;
    if (IDWriteTextLayout* l = BubbleMakeLayout(s, em, wt, 100000.0f)) {
        DWRITE_TEXT_METRICS m = {};
        l->GetMetrics(&m);
        l->Release();
        return m.widthIncludingTrailingWhitespace;
    }
    float w = 0.0f;   // ohne DirectWrite: GDI+ (Segoe UI)
    if (MainGdipReady()) {
        HDC dc = GetDC(nullptr);
        if (dc) {
            Gdiplus::Graphics g(dc);
            Gdiplus::Font f(L"Segoe UI", em, wt >= DWRITE_FONT_WEIGHT_SEMI_BOLD ? Gdiplus::FontStyleBold : Gdiplus::FontStyleRegular, Gdiplus::UnitPixel);
            Gdiplus::RectF r;
            g.MeasureString(s.c_str(), -1, &f, Gdiplus::PointF(0, 0), Gdiplus::StringFormat::GenericTypographic(), &r);
            w = r.Width;
            ReleaseDC(nullptr, dc);
        }
    }
    return w > 0.0f ? w : (float)s.size() * em * 0.55f;
}
