// Fix 116: Dig-Zeile ("[hh:mm:ss]: <Dig-Text>\u200E [<Ort>]")? endIdx = Position des Zeilenendes ('\r') hinter "]"
static bool DigLogLineEnd(HWND hwnd, LONG idx, LONG total, LONG& endIdx, bool* drone = nullptr) {
    wchar_t buf[257] = {};
    const LONG e = std::min<LONG>(total, idx + 256);
    if (e <= idx) return false;
    TEXTRANGEW tr = { { idx, e }, buf };
    const LONG got = (LONG)SendMessageW(hwnd, EM_GETTEXTRANGE, 0, (LPARAM)&tr);
    if (got <= 0 || buf[0] != L'[') return false;
    LONG k = 0;
    while (k < got && k < 256 && buf[k] != L'\r' && buf[k] != L'\n') ++k;
    if (k >= got || k < 6 || buf[k - 1] != L']') return false;
    std::wstring_view line(buf, (size_t)k);
    if (line.find(L"]: ") == std::wstring_view::npos || line.find(L"\u200E [") == std::wstring_view::npos) return false;
    endIdx = idx + k;
    if (drone) *drone = line.find(L"\u200E\u200E [") != std::wstring_view::npos;   // Fix 120: Drohnen-Zeile (doppelte LRM-Marke)
    return true;
}
// Fix 251: dezente, transparente Karte hinter jedem Log-Eintrag (Kategorie-Farbe, sehr geringe Deckkraft, feiner Rand wie die Chips).
// Wird nach Text/Chips einmal je Malvorgang per Maximum ueber den Ausschnitt gelegt: hellt nur den dunklen Grund auf, Text und Chips
// bleiben unveraendert, mehrfaches Malen stapelt nichts (kein Flackern, kein Aufsummieren). Der Clip-Bereich wird beachtet.
struct LogRowCard { int left, top, right, bottom; COLORREF col; };
static void LogRowCardsApply(HDC dc, const RECT& rc, const std::vector<LogRowCard>& cards) {
    if (cards.empty()) return;
    RECT box = {};
    if (GetClipBox(dc, &box) <= NULLREGION) return;
    RECT u = { INT_MAX, INT_MAX, INT_MIN, INT_MIN };
    for (const auto& c : cards) {
        u.left = std::min<LONG>(u.left, c.left); u.top = std::min<LONG>(u.top, c.top);
        u.right = std::max<LONG>(u.right, c.right); u.bottom = std::max<LONG>(u.bottom, c.bottom);
    }
    if (!IntersectRect(&box, &box, &u) || !IntersectRect(&box, &box, &rc)) return;
    const int bw = box.right - box.left, bh = box.bottom - box.top;
    if (bw <= 0 || bh <= 0 || (size_t)bw * (size_t)bh > 16000000u) return;
    BITMAPINFO bi = {};
    bi.bmiHeader.biSize = sizeof(bi.bmiHeader); bi.bmiHeader.biWidth = bw; bi.bmiHeader.biHeight = -bh;
    bi.bmiHeader.biPlanes = 1; bi.bmiHeader.biBitCount = 32; bi.bmiHeader.biCompression = BI_RGB;
    void* pv = nullptr;
    HDC mem = CreateCompatibleDC(dc);
    HBITMAP bmp = mem ? CreateDIBSection(dc, &bi, DIB_RGB_COLORS, &pv, nullptr, 0) : nullptr;
    if (!mem || !bmp || !pv) { if (bmp) DeleteObject(bmp); if (mem) DeleteDC(mem); return; }
    HGDIOBJ ob = SelectObject(mem, bmp);
    BitBlt(mem, 0, 0, bw, bh, dc, box.left, box.top, SRCCOPY);
    GdiFlush();
    BYTE* px = static_cast<BYTE*>(pv);
    const float rad = std::max(3.0f, (float)g_chipS * 0.30f);
    const int gapV = std::max(1, UIS(1));   // kleiner senkrechter Abstand zwischen den Karten
    for (const auto& c : cards) {
        const float L = (float)c.left, T = (float)(c.top + gapV), Rr = (float)c.right, B = (float)(c.bottom - gapV);
        if (Rr - L < 4.0f || B - T < 4.0f) continue;
        const float cx = (L + Rr) * 0.5f, cy = (T + B) * 0.5f, hw = (Rr - L) * 0.5f, hh = (B - T) * 0.5f;
        const float rr = std::min(rad, std::min(hw, hh));
        const float fR = GetRValue(c.col) * 0.075f, fG = GetGValue(c.col) * 0.075f, fB = GetBValue(c.col) * 0.075f;   // Flaeche
        const float eR = GetRValue(c.col) * 0.25f, eG = GetGValue(c.col) * 0.25f, eB = GetBValue(c.col) * 0.25f;      // Rand
        const int y0 = std::max<int>(box.top, (int)T), y1 = std::min<int>(box.bottom, (int)std::ceil(B));
        const int x0 = std::max<int>(box.left, (int)L), x1 = std::min<int>(box.right, (int)std::ceil(Rr));
        for (int y = y0; y < y1; ++y) {
            const float qy = std::fabs((float)y + 0.5f - cy) - (hh - rr);
            BYTE* row = px + (size_t)(y - box.top) * (size_t)bw * 4;
            for (int x = x0; x < x1; ++x) {
                const float qx = std::fabs((float)x + 0.5f - cx) - (hw - rr);
                const float dd = (qx > 0.0f && qy > 0.0f) ? std::sqrt(qx * qx + qy * qy) - rr : std::max(qx, qy) - rr;
                if (dd >= 0.5f) continue;
                const float fc = std::min(1.0f, 0.5f - dd);
                const float ec = std::max(0.0f, 1.0f - std::fabs(dd + 0.5f));
                BYTE* p = row + (size_t)(x - box.left) * 4;
                const int vb = (int)(std::max(fB * fc, eB * ec) + 0.5f), vg = (int)(std::max(fG * fc, eG * ec) + 0.5f), vr = (int)(std::max(fR * fc, eR * ec) + 0.5f);
                if (p[0] < vb) p[0] = (BYTE)vb;
                if (p[1] < vg) p[1] = (BYTE)vg;
                if (p[2] < vr) p[2] = (BYTE)vr;
            }
        }
    }
    BitBlt(dc, box.left, box.top, bw, bh, mem, 0, 0, SRCCOPY);
    SelectObject(mem, ob);
    DeleteObject(bmp);
    DeleteDC(mem);
}
