// Daten eines Funds für die Übergabe an den UI-Thread
struct DigInfo {
    bool silent = false;   // Fix 222
    int server = 0;
    std::wstring x;
    std::wstring y;
    // Log-Zeile schreiben (Logging war beim Fund an) und Uhrzeit des Funds
    bool log = false;
    std::wstring timeStr; std::wstring dateStr;   // Fix 183: dateStr
    // Gefundener Dig-Text in der Spielsprache (z. B. "Testflugstörung")
    std::wstring digText;
    // Warzone-Wort in der Spielsprache inkl. evtl. Leerzeichen vor "#" (z. B. "Kriegszone ", Arabisch leer)
    std::wstring zoneText;
    bool hasZoneText = false;
    bool drone = false;   // Fix 120: Testflugdrohne (Dig-Art 'F') statt Schatz
    F377T f377; long long f377Posted = 0;   // FIX377: worker timings + PostMessage time
};

// Fix 188: echte Postzeit nachgereicht -> Uhrzeit der schon geschriebenen Dig-Zeile korrigieren (WM_DIGTIMEFIX)
struct DigTimeFix { std::wstring oldDate, oldHms, newDate, newHms, xs, ys; int sid = 0; bool drone = false; std::string uuid; };   // Fix 189: uuid = Geschenk-Zeile
static LONG LogSortedTarget(const std::wstring& date, const std::wstring& hms, std::wstring& sepDate);   // Fix 184
static void LogMoveTailTo(LONG a, LONG t, const std::wstring& sepDate);                                 // Fix 184
// Schreibt die Fund-Zeile (Dig-Text in der Spielsprache) ins Log (nur im UI-Thread aufrufen)
static void WriteDigLogLine(const DigInfo& d) {
    if (!g_hRichEdit) return;
    LogKeepView kv = LogKeepBegin();   // Fix 244: unten -> mitlaufen, hochgescrollt -> nichts bewegt sich
    TrimLogIfNeeded();
    LogKeepTrimmed(kv);
    std::wstring sortSep;   // Fix 184: Einfuegestelle nach Spielzeit (-1 = unten anhaengen)
    const LONG sortAt = LogSortedTarget(d.dateStr, d.timeStr, sortSep);
    if (sortAt < 0) LogWriteDateSepIfNeeded(d.dateStr, d.timeStr);   // Fix 178/183
    const LONG sortFrom = LogTextLenNow();
    ApplyPinIndent();
    AppendColoredText(L"[", LOG_TIME_COLOR);   // Fix 114: Uhrzeit samt Klammern und Doppelpunkt grau
    AppendColoredText(d.timeStr, LOG_TIME_COLOR);
    AppendColoredText(L"]: ", LOG_TIME_COLOR);
    {   // Fix 31: Zeilenanfang "[" für das Aufleuchten nach Klick auf die Benachrichtigung
        CHARRANGE cr = { 0, 0 };
        SendMessageW(g_hRichEdit, EM_EXGETSEL, 0, (LPARAM)&cr);
        LogGlowNoteLine(cr.cpMax - 4 - (LONG)d.timeStr.size(), d.timeStr, false, std::string());
    }
    // U+200E (Links-nach-rechts-Marke) nach Dig-Text und Warzone-Wort: arabischer Text zieht sonst "[#." in seine Leserichtung
    // Fix 120: Drohne lila, Fallback "Test Flight Failure", Marke "\u200E\u200E [" (DigLogLineEnd erkennt daran die Drohnen-Zeile)
    if (d.drone) AppendColoredText((d.digText.empty() ? std::wstring(L"Test Flight Failure") : d.digText) + L"\u200E\u200E ", DRONE_COLOR);
    else AppendColoredText((d.digText.empty() ? std::wstring(L"DIG FOUND !") : d.digText) + L"\u200E ", RGB(0, 255, 0));
    AppendColoredText(L"[" + (d.hasZoneText ? d.zoneText : std::wstring(L"Warzone ")) + L"\u200E#", RGB(255, 255, 255), false, true);
    AppendColoredText(std::to_wstring(d.server), RGB(255, 255, 255), false, true);
    AppendColoredText(L" X:", RGB(255, 255, 255), false, true);
    AppendColoredText(d.x, RGB(255, 255, 255), false, true);
    AppendColoredText(L" Y:", RGB(255, 255, 255), false, true);
    AppendColoredText(d.y, RGB(255, 255, 255), false, true);
    AppendColoredText(L"]", RGB(255, 255, 255), false, true);
    AppendColoredText(L"\r\n", RGB(255, 255, 255));
    if (sortAt >= 0) LogMoveTailTo(sortFrom, sortAt, sortSep);   // Fix 184: Zeile an ihre Spielzeit verschieben
    LogFilterApply(false);   // Fix 200: TODAY -> frühere Tage weiter ausblenden
    LogKeepEnd(kv, sortAt);   // Fix 244 (statt immer SB_BOTTOM)
    if (g_pinIcon) InvalidateRect(g_hRichEdit, nullptr, FALSE);  // Nadeln neu malen
}

// Meldet einen Fund an den UI-Thread: dort werden Log-Zeile (Dig-Text, wenn Logging an ist),
// Blase und Tray-Hinweis erzeugt (WM_DIGFOUND). Das RichEdit wird nur noch im UI-Thread angefasst.
void AddDigLog(const std::wstring& timeStr, int server, const std::wstring& x, const std::wstring& y, const std::wstring& digText, const std::wstring& zoneText, bool hasZoneText, bool drone) {
    HWND hwnd = g_hWnd;
    if (hwnd && IsWindow(hwnd)) {
        auto info = std::make_unique<DigInfo>();
        info->silent = t_reportSilent;   // Fix 222
        info->server = server;
        info->x = x;
        info->y = y;
        info->log = g_loggingEnabled.load();
        LogSplitStamp(timeStr, info->timeStr, info->dateStr);   // Fix 183
        info->digText = digText;
        info->zoneText = zoneText;
        info->hasZoneText = hasZoneText;
        info->drone = drone;   // Fix 120
        info->f377 = t_f377; info->f377Posted = F377Ms();   // FIX377
        // Nur bei erfolgreichem Posten gehört der Speicher dem UI-Thread, sonst wird er hier freigegeben
        if (PostMessageW(hwnd, WM_DIGFOUND, 0, (LPARAM)info.get()))
            info.release();
    }
}

// FIX377: one latency line per reported dig/drone (UI thread, after bubble + toast)
static void F377DigLine(const DigInfo& d, long long ui, long long bub, long long toast) {
    const F377T& f = d.f377;
    if (!f.uuid && !f.rep) return;
    std::string xs, ys; for (wchar_t c : d.x) xs += (char)c; for (wchar_t c : d.y) ys += (char)c;
    char b[1024];
    snprintf(b, sizeof(b), " FIX377 dig uuid=%llu kind=%s sid=%d X:%s Y:%s post=%s json=%s slot=%s pair=%s report=%s posted=%s ui=%s bubble=%s toast=%s | post->found=%s found->report=%s report->ui=%s ui->bubble=%s ui->toast=%s ms (silent=%d log=%d pass=%llu full=%d)",
        f.uuid, d.drone ? "drone" : "dig", d.server, xs.c_str(), ys.c_str(), F377Hms(f.post).c_str(), F377Hms(f.json).c_str(), F377Hms(f.slot).c_str(), F377Hms(f.pair).c_str(),
        F377Hms(f.rep).c_str(), F377Hms(d.f377Posted).c_str(), F377Hms(ui).c_str(), F377Hms(bub).c_str(), F377Hms(toast).c_str(),
        F377D(f.post, f.json).c_str(), F377D(f.json, f.rep).c_str(), F377D(f.rep, ui).c_str(), F377D(ui, bub).c_str(), F377D(ui, toast).c_str(),
        d.silent ? 1 : 0, d.log ? 1 : 0, f.pass, f.full ? 1 : 0);
    AllyLog299(Clk339() + b);
}
// ===== Lucky Gift (Glücksgeschenk) melden - nur Blase + Log, kein Discord, kein Dig-Zähler =====
// Fix 188: Worker -> UI: Dig-Zeile mit Zeit oldStamp bekommt die echte Postzeit newStamp
static void DigTimeFixPost(const std::string& oldStamp, const std::string& newStamp, int sid, const std::wstring& xs, const std::wstring& ys, bool drone) {
    HWND hwnd = g_hWnd;
    if (!hwnd || !IsWindow(hwnd)) return;
    auto f = std::make_unique<DigTimeFix>();
    LogSplitStamp(std::wstring(oldStamp.begin(), oldStamp.end()), f->oldHms, f->oldDate);
    LogSplitStamp(std::wstring(newStamp.begin(), newStamp.end()), f->newHms, f->newDate);
    f->sid = sid; f->xs = xs; f->ys = ys; f->drone = drone;
    if (PostMessageW(hwnd, WM_DIGTIMEFIX, 0, (LPARAM)f.get())) f.release();
}
// Fix 189: Worker -> UI: Geschenk-Zeile (Lucky/Ei/Feuerwerk, per uuid gemerkt) bekommt die fruehere echte Postzeit
static void GiftTimeFixPost(const std::string& uuid, const std::string& oldStamp, const std::string& newStamp) {
    HWND hwnd = g_hWnd;
    if (!hwnd || !IsWindow(hwnd) || uuid.empty()) return;
    auto f = std::make_unique<DigTimeFix>();
    LogSplitStamp(std::wstring(oldStamp.begin(), oldStamp.end()), f->oldHms, f->oldDate);
    LogSplitStamp(std::wstring(newStamp.begin(), newStamp.end()), f->newHms, f->newDate);
    f->uuid = uuid;
    if (PostMessageW(hwnd, WM_DIGTIMEFIX, 0, (LPARAM)f.get())) f.release();
}
