static std::wstring Toast358Png(int kind) {   // same icon resources as the balloon icons -> PNG once (toast logo)
    static std::wstring cache[5]; static bool tried[5] = {};
    if (kind < 0 || kind > 4) kind = 0;
    if (tried[kind]) return cache[kind];
    tried[kind] = true;
    const std::wstring dir = Toast358Dir();
    if (dir.empty()) return std::wstring();
    const std::wstring path = dir + L"\\kind" + std::to_wstring(kind) + L".png";
    HICON ic = (HICON)LoadImageW(GetModuleHandleW(nullptr), MAKEINTRESOURCEW(kind == 4 ? IDI_TEST_DRONE : kind == 3 ? IDI_GOLDEN_EGG : (kind == 2 ? IDI_FIREWORK : (kind == 1 ? IDI_LUCKY_GIFT : DigIconId()))), IMAGE_ICON, 96, 96, LR_DEFAULTCOLOR);
    if (!ic && kind == 4) ic = (HICON)LoadImageW(GetModuleHandleW(nullptr), MAKEINTRESOURCEW(DigIconId()), IMAGE_ICON, 96, 96, LR_DEFAULTCOLOR);
    if (!ic) { AllyLog299(Clk339() + " FIX358b icon png kind=" + std::to_string(kind) + " FAIL (no icon)"); return std::wstring(); }
    bool ok = false;
    IWICImagingFactory* fac = nullptr; IWICBitmap* bmp = nullptr; IWICStream* st = nullptr; IWICBitmapEncoder* enc = nullptr; IWICBitmapFrameEncode* fr = nullptr; IPropertyBag2* pb = nullptr;
    if (SUCCEEDED(CoCreateInstance(CLSID_WICImagingFactory, nullptr, CLSCTX_INPROC_SERVER, IID_PPV_ARGS(&fac)))
        && SUCCEEDED(fac->CreateBitmapFromHICON(ic, &bmp)) && SUCCEEDED(fac->CreateStream(&st))
        && SUCCEEDED(st->InitializeFromFilename(path.c_str(), GENERIC_WRITE)) && SUCCEEDED(fac->CreateEncoder(GUID_ContainerFormatPng, nullptr, &enc))
        && SUCCEEDED(enc->Initialize(st, WICBitmapEncoderNoCache)) && SUCCEEDED(enc->CreateNewFrame(&fr, &pb)) && SUCCEEDED(fr->Initialize(pb))) {
        UINT w = 0, h = 0; bmp->GetSize(&w, &h);
        WICPixelFormatGUID pf = GUID_WICPixelFormat32bppBGRA;
        ok = SUCCEEDED(fr->SetSize(w, h)) && SUCCEEDED(fr->SetPixelFormat(&pf)) && SUCCEEDED(fr->WriteSource(bmp, nullptr)) && SUCCEEDED(fr->Commit()) && SUCCEEDED(enc->Commit());
    }
    if (pb) pb->Release();
    if (fr) fr->Release();
    if (enc) enc->Release();
    if (st) st->Release();
    if (bmp) bmp->Release();
    if (fac) fac->Release();
    DestroyIcon(ic);
    if (ok) cache[kind] = path;
    AllyLog299(Clk339() + " FIX358b icon png kind=" + std::to_string(kind) + (ok ? " ok " : " FAIL ") + Toast358U8(path));
    return cache[kind];
}
