// Fix 214: RTF ohne "ausgeblendet": Steuerwörter \v / \v0 entfernen (\\v im Text ist ein maskierter Backslash + v und bleibt).
// Das Leerzeichen dahinter bleibt nur, wenn es ein vorangehendes Steuerwort abschließt. Ergebnis = RTF desselben Logs ohne Ausblendung.
static bool LogRtfEndsWithWord(const std::string& o) {
    size_t k = o.size();
    while (k > 0 && o[k - 1] >= '0' && o[k - 1] <= '9') --k;
    if (k > 0 && o[k - 1] == '-') --k;
    const size_t letters = k;
    while (k > 0 && ((o[k - 1] >= 'a' && o[k - 1] <= 'z') || (o[k - 1] >= 'A' && o[k - 1] <= 'Z'))) --k;
    if (k == letters || k == 0 || o[k - 1] != '\\') return false;
    size_t bs = 0;
    while (k > 0 && o[k - 1] == '\\') { ++bs; --k; }
    return (bs % 2) == 1;
}
static std::string LogRtfNoHidden(const std::string& r) {
    std::string o;
    o.reserve(r.size());
    for (size_t i = 0; i < r.size(); ) {
        if (r[i] == '\\' && i + 1 < r.size()) {
            const char c = r[i + 1];
            const bool letterNext = i + 2 < r.size() && ((r[i + 2] >= 'a' && r[i + 2] <= 'z') || (r[i + 2] >= 'A' && r[i + 2] <= 'Z'));
            if (c == 'v' && !letterNext) {
                size_t j = i + 2;
                if (j < r.size() && r[j] == '-') ++j;
                while (j < r.size() && r[j] >= '0' && r[j] <= '9') ++j;
                if (j < r.size() && r[j] == ' ' && !LogRtfEndsWithWord(o)) ++j;
                i = j;
                continue;
            }
            o += r[i];
            o += c;
            i += 2;
            continue;
        }
        o += r[i++];
    }
    return o;
}
// Fix 249: kompakte Eintraege fuer die gespeicherten uuids ("SEE2"): Art (1 Byte), Merker (1 Byte),
// Zahl (8 Bytes, wenn != 0), uuid als 32 Kleinbuchstaben-Hex gepackt in 16 Bytes, sonst Laenge + Text.
static const uint32_t SEEN_MAGIC2 = 0x32454553u;   // "SEE2" (alt: "SEEN" = 0x5345454E, wird weiter gelesen)
static int SeenHexVal(char c) { return (c >= '0' && c <= '9') ? c - '0' : ((c >= 'a' && c <= 'f') ? c - 'a' + 10 : -1); }
static void SeenPutRec(std::string& b, const SeenRec& r) {
    bool hex = r.s.size() == 32;
    for (size_t i = 0; hex && i < 32; ++i) hex = SeenHexVal(r.s[i]) >= 0;
    const unsigned char fl = (unsigned char)((r.n ? 1 : 0) | (hex ? 2 : (r.s.empty() ? 0 : 4)));
    b += r.kind;
    b += (char)fl;
    if (fl & 1) b.append((const char*)&r.n, 8);
    if (fl & 2) {
        char p[16];
        for (int i = 0; i < 16; ++i) p[i] = (char)((SeenHexVal(r.s[2 * i]) << 4) | SeenHexVal(r.s[2 * i + 1]));
        b.append(p, 16);
    }
    else if (fl & 4) LsPutStr(b, r.s);
}
static bool SeenGetRec(LsReader& rs, SeenRec& r) {
    const size_t sz = rs.b.size();
    if (!rs.ok || rs.p + 2 > sz) { rs.ok = false; return false; }
    r.kind = rs.b[rs.p];
    const unsigned char fl = (unsigned char)rs.b[rs.p + 1];
    rs.p += 2;
    r.n = 0;
    r.s.clear();
    if (fl & 1) { if (rs.p + 8 > sz) { rs.ok = false; return false; } memcpy(&r.n, rs.b.data() + rs.p, 8); rs.p += 8; }
    if (fl & 2) {
        if (rs.p + 16 > sz) { rs.ok = false; return false; }
        static const char hx[] = "0123456789abcdef";
        r.s.resize(32);
        for (int i = 0; i < 16; ++i) { const unsigned char v = (unsigned char)rs.b[rs.p + i]; r.s[2 * i] = hx[v >> 4]; r.s[2 * i + 1] = hx[v & 15]; }
        rs.p += 16;
    }
    else if (fl & 4) r.s = rs.Str();
    return rs.ok;
}
static bool LogSaveToRegistry() {
    if (!g_hRichEdit) return false;
    std::string rtf;
    EDITSTREAM es = { (DWORD_PTR)&rtf, 0, LogStreamOutCb };
    SendMessageW(g_hRichEdit, EM_STREAMOUT, SF_RTF, (LPARAM)&es);
    if (!g_logHid.empty()) rtf = LogRtfNoHidden(rtf);   // Fix 200/214: SAVE speichert immer alles sichtbar (ohne das Log umzuformatieren)
    std::string cnt;
    LsPutU32(cnt, LOGSAVE_MAGIC);
    const int vals[8] = { g_digCount, g_droneCount, g_luckyCount, g_fireworkCount, g_eggCount, g_luckyClaimed, g_eggClaimed, g_fireworkClaimed };
    for (int v : vals) LsPutU32(cnt, (uint32_t)v);
    std::string lines;
    LsPutU32(lines, (uint32_t)g_luckyCountLines.size());
    for (const auto& c : g_luckyCountLines) {
        std::string u = c.uuid;
        while (!u.empty() && u[0] == '~') u.erase(0, 1);
        LsPutStr(lines, u);
        LsPutU32(lines, (uint32_t)c.lineStart); LsPutU32(lines, (uint32_t)c.countPos);
        LsPutWStr(lines, c.text); LsPutWStr(lines, c.prev);
        LsPutU32(lines, (uint32_t)c.n); LsPutU32(lines, (uint32_t)c.total);
        LsPutU32(lines, (c.egg ? 1u : 0u) | (c.stale ? 2u : 0u) | (c.fw ? 4u : 0u) | (UiGiftMine(c.uuid) ? 8u : 0u));
    }
    HKEY k = nullptr;
    bool ok = RegCreateKeyExW(HKEY_CURRENT_USER, LOGSAVE_REG_PATH, 0, nullptr, 0, KEY_READ | KEY_WRITE, nullptr, &k, nullptr) == ERROR_SUCCESS;
    if (ok) {
        const DWORD zero = 0, one = 1;
        RegSetValueExW(k, L"valid", 0, REG_DWORD, (const BYTE*)&zero, sizeof(zero));   // erst gültig, wenn alles geschrieben ist
        std::string seen;   // Fix 182: bekannte uuids; Fix 249: kompakt, ein Puffer, nur bei Aenderung neu schreiben
        unsigned long long seenGen = 0;
        bool seenChanged = true;
        {
            std::lock_guard<std::mutex> lk(g_seenPersistMx);
            seenGen = g_seenPersistGen;
            seenChanged = seenGen != g_seenSavedGen;
            if (seenChanged) {
                seen.reserve(8 + g_seenPersist.size() * 18);
                LsPutU32(seen, SEEN_MAGIC2);
                LsPutU32(seen, (uint32_t)g_seenPersist.size());
                for (const auto& r : g_seenPersist) SeenPutRec(seen, r);
            }
        }
        { const std::string pb381 = F381Blob(); if (!pb381.empty()) LogSaveWriteBlob(k, L"profile", pb381); else if (kRst430 && g_rst430) LogSaveDelBlob431(k, L"profile"); }   /* FIX430/431 */   // FIX381: profile data + avatar/frame
        if (kFix516AllCollect) { const std::string db516 = F516Blob(); if (!db516.empty()) LogSaveWriteBlob(k, L"digdone", db516); }
        ok = LogSaveWriteBlob(k, L"log", rtf) && LogSaveWriteBlob(k, L"counts", cnt) && LogSaveWriteBlob(k, L"lines", lines) && (!seenChanged || LogSaveWriteBlob(k, L"seen", seen));
        if (ok) RegSetValueExW(k, L"valid", 0, REG_DWORD, (const BYTE*)&one, sizeof(one));
        if (ok && seenChanged) { std::lock_guard<std::mutex> lk(g_seenPersistMx); g_seenSavedGen = seenGen; }
        RegCloseKey(k);
    }
    if (ok) g_logAutoSig = LogAutoSigNow();
    return ok;
}
// Fix 181: "auto save" im Launcher angehakt -> Log still speichern (beim Schliessen, BACK und jede Minute bei Aenderung)
static void LogAutoSave(bool onlyIfChanged) {
    SeenStoreSave();   // Fix 257: seen lists always, also without auto save
    if (!g_saveChecked || !g_hRichEdit) return;
    if (onlyIfChanged && LogAutoSigNow() == g_logAutoSig) return;
    LogSaveToRegistry();
}
// ===== Fix 257: seen lists stored on their own ("seenx", always - also without auto save) =====
// Written from the UI thread (every 2 s when changed, auto save, BACK, close); read once at start BEFORE the search thread
// runs, so an app restart never reports a find still in the game chat again. RESET empties the list -> stored empty too.
static bool g_seenStoreReady = false;
static unsigned long long g_seenStoreGen = ~0ULL;
static void SeenStoreSave() {
    if (!g_seenStoreReady) return;
    std::string seen; unsigned long long gen = 0;
    {
        std::lock_guard<std::mutex> lk(g_seenPersistMx);
        gen = g_seenPersistGen;
        if (gen == g_seenStoreGen) return;
        seen.reserve(8 + g_seenPersist.size() * 18);
        LsPutU32(seen, SEEN_MAGIC2);
        LsPutU32(seen, (uint32_t)g_seenPersist.size());
        for (const auto& r : g_seenPersist) SeenPutRec(seen, r);
    }
    HKEY k = nullptr;
    if (RegCreateKeyExW(HKEY_CURRENT_USER, LOGSAVE_REG_PATH, 0, nullptr, 0, KEY_READ | KEY_WRITE, nullptr, &k, nullptr) != ERROR_SUCCESS) return;
    const bool ok = LogSaveWriteBlob(k, L"seenx", seen);
    RegCloseKey(k);
    if (ok) g_seenStoreGen = gen;
}
static void SeenStoreLoad() {
    std::string blob;
    HKEY k = nullptr;
    if (RegOpenKeyExW(HKEY_CURRENT_USER, LOGSAVE_REG_PATH, 0, KEY_READ, &k) == ERROR_SUCCESS) { if (!LogSaveReadBlob(k, L"seenx", blob)) blob.clear(); RegCloseKey(k); }
    std::vector<SeenRec> recs;
    if (blob.size() >= 8) {
        LsReader rs(blob);
        if (rs.U32() == SEEN_MAGIC2) {
            const uint32_t n = rs.U32();
            for (uint32_t i = 0; i < n && rs.ok && i < (uint32_t)SEEN_PERSIST_CAP; ++i) { SeenRec r; SeenGetRec(rs, r); if (rs.ok) recs.push_back(std::move(r)); }
        }
    }
    std::lock_guard<std::mutex> lk(g_seenPersistMx);
    if (!recs.empty()) {
        g_seenImport.insert(g_seenImport.end(), recs.begin(), recs.end());
        SeenPersistMergeLocked(recs);
        g_seenXferPending = true;
    }
    g_seenStoreReady = true;
}
// Fix 317: auto save OFF + log completely empty -> START begins fresh: forget all seen lists (memory + stored "seenx").
// Cause (user 17:09): Fix 257 stores "seenx" ALWAYS and SeenStoreLoad loaded it at every app start, also with auto save off
// and an empty log -> finds still in the game chat were never reported. Separate from RESET (MainLogReset untouched);
// SAVE/LOAD and auto save ON keep the old behaviour.
// Fix 319: also with auto save ON: empty log (after RESET / auto load of an empty save) = nothing to protect -> fresh too.
static bool SeenFreshIfEmpty317() {
    if (!g_hRichEdit || GetWindowTextLengthW(g_hRichEdit) != 0) return false;
    std::lock_guard<std::mutex> lk(g_seenPersistMx);
    g_seenLoaded.clear();
    g_seenImport.clear();
    g_seenPersist.clear();
    ++g_seenPersistGen;   // next SeenStoreSave writes the empty list over the old "seenx"
    g_seenForgetAll = true;   // search thread forgets this run too
    g_seenXferPending = true;
    g_seenStoreReady = true;
    return true;
}
