static void LogMoveTo(int x, int y, int w, int h) {
    if (!g_hRichEdit) return;
    if (g_mainSizing && !kRsz451) return;   // FIX451: off (composited drag instead); FIX447: during live drag keep RichEdit geometry unchanged (no per-move WM_SIZE/flash); MainSizeEnd applies final size once
    // Fix 254: the log does not paint while it is moved/resized (WM_SETREDRAW FALSE); the size change is part of the
    // WM_SIZE batch and the log paints once afterwards (LogRedrawResume, full invalidate -> no stale strips, Fix 238).
    // Fix 237 stays: outside of a drag the log first gets 1 px less, then the real size (fresh height for the scrollbar).
    // Fix 250 stays: during a drag only one step.
    if (!g_logRedrawOff && !g_mainSizing) { SendMessageW(g_hRichEdit, WM_SETREDRAW, FALSE, 0); g_logRedrawOff = true; }
    if (!g_mainSizing && h > 1) SetWindowPos(g_hRichEdit, nullptr, x, y, w, h - 1, SWP_NOZORDER | SWP_NOACTIVATE | SWP_NOCOPYBITS);
    g_logKeepBits445 = g_mainSizing; MainPlace(g_hRichEdit, x, y, w, h); g_logKeepBits445 = false;   // FIX445
    if (!g_mainDefer) LogRedrawResume();
}
// Fix 176: Hoehe selbst aendern (oberer/unterer Rand), auch wenn dort ein Kind-Fenster liegt; Breite bleibt fest
static int g_mainSizeEdge = 0;   // Bits: 1 = oben, 2 = unten, 4 = links, 8 = rechts (Fix 243: auch Breite und Ecken)
static POINT g_mainSizeStart = {};
static RECT g_mainSizeRect = {};
static int MainEdgeAt(POINT s) {
    if (kFix467NoManual) return 0;   // FIX467: no manual resize -> no edge hit, no drag start, no size cursor
    if (!g_hWnd || !IsWindowVisible(g_hWnd) || IsIconic(g_hWnd)) return 0;
    RECT r; if (!GetWindowRect(g_hWnd, &r)) return 0;
    if (s.x < r.left || s.x >= r.right || s.y < r.top || s.y >= r.bottom) return 0;
    int e = 0;
    if (s.y >= r.bottom - UIS(9)) e |= 2;   // Fix 179: breiterer Greifbereich
    else if (s.y < r.top + UIS(6)) e |= 1;
    if (s.x >= r.right - UIS(6)) e |= 8;   // Fix 243: linker/rechter Rand
    else if (s.x < r.left + UIS(6)) e |= 4;
    const int cz = UIS(14);   // Fix 243: Ecken etwas groesser greifbar
    if ((e & 12) && !(e & 3)) { if (s.y >= r.bottom - cz) e |= 2; else if (s.y < r.top + cz) e |= 1; }
    if ((e & 3) && !(e & 12)) { if (s.x >= r.right - cz) e |= 8; else if (s.x < r.left + cz) e |= 4; }
    return e;
}
static LPCWSTR MainEdgeCursor(int e) {   // Fix 243
    const bool v = (e & 3) != 0, h = (e & 12) != 0;
    if (v && h) return (((e & 1) != 0) == ((e & 4) != 0)) ? IDC_SIZENWSE : IDC_SIZENESW;
    return h ? IDC_SIZEWE : IDC_SIZENS;
}
