    if (g_clip464) { g_clip464 = false; SetWindowLongPtrW(g_hWnd, GWL_STYLE, GetWindowLongPtrW(g_hWnd, GWL_STYLE) | WS_CLIPCHILDREN); }   // FIX464: WS_CLIPCHILDREN back before the final repaint
