    if (g_comp451) { g_comp451 = false; SetWindowLongPtrW(g_hWnd, GWL_EXSTYLE, GetWindowLongPtrW(g_hWnd, GWL_EXSTYLE) & ~(LONG_PTR)WS_EX_COMPOSITED); }   // FIX451
