    RedrawWindow(g_hWnd, nullptr, nullptr, RDW_INVALIDATE | RDW_ERASE | RDW_ALLCHILDREN | RDW_UPDATENOW | (kFix457End ? RDW_FRAME : 0u));   // FIX457: + RDW_FRAME
