static bool MainSizeFilter(const MSG& m) {
    if (!g_hWnd || !m.hwnd || (m.hwnd != g_hWnd && !IsChild(g_hWnd, m.hwnd))) return false;
    switch (m.message) {
    case WM_MOUSEMOVE: case WM_NCMOUSEMOVE:
        if (g_mainSizing && !kFix467NoManual) {   /* FIX467: live drag path off */
            { MSG nx; if (PeekMessageW(&nx, nullptr, WM_MOUSEMOVE, WM_MOUSEMOVE, PM_NOREMOVE)) return true; }   // Fix 177: nur die neueste Position anwenden
            const int dx = m.pt.x - g_mainSizeStart.x, dy = m.pt.y - g_mainSizeStart.y;
            const RECT r0 = g_mainSizeRect;
            const int h0 = r0.bottom - r0.top, w0 = r0.right - r0.left;
            const int maxH = GetSystemMetrics(SM_CYVIRTUALSCREEN), maxW = GetSystemMetrics(SM_CXVIRTUALSCREEN);
            const int minW = std::min<int>(maxW, g_mainMinW > 0 ? g_mainMinW : w0);   // Fix 242/243: nie schmaler als die Standardbreite
            int L = r0.left, T = r0.top, R = r0.right, B = r0.bottom;
            const int minH414 = (kWinMin414 && kHgt413) ? std::max<int>(MAIN_MIN_H, F380Height()) : MAIN_MIN_H;
            if (g_mainSizeEdge & 2) B = T + std::max<int>(minH414, std::min<int>(maxH, h0 + dy));
            else if (g_mainSizeEdge & 1) T = B - std::max<int>(minH414, std::min<int>(maxH, h0 - dy));
            if (g_mainSizeEdge & 8) R = L + std::max<int>(minW, std::min<int>(maxW, w0 + dx));   // Fix 243
            else if (g_mainSizeEdge & 4) L = R - std::max<int>(minW, std::min<int>(maxW, w0 - dx));
            if (g_mainSizeEdge & 12) g_mainUserW = R - L;   // Fix 243: LayoutCounters behaelt diese Breite
            UINT fl = SWP_NOZORDER | SWP_NOACTIVATE;
            if (kFix464NoRedraw && g_mainSizing) fl |= SWP_NOREDRAW;   // FIX464: no system present of the discarded frame; WM_SIZE does the one coordinated RedrawWindow
            if (L == r0.left && T == r0.top) fl |= SWP_NOMOVE;
            { RECT cw; if (!(kNoCopy454 && g_mainSizing) && !(kFix462TopBits && g_mainSizing) /* FIX462 */ && GetWindowRect(g_hWnd, &cw) && (L != cw.left || R - L != cw.right - cw.left)) fl |= SWP_NOCOPYBITS; }   /* FIX454: no NOCOPYBITS on the main window during the live drag (log kept, no full log erase/repaint per width step) */   // Fix 245: bei Breitenaenderung keine alten Pixel umkopieren (Geister-Pills)
            if (kRec452) Rec452Step(L, T, R - L, B - T, fl, 0);   // FIX452 recorder (log-only)
            RECT old459 = {}; const bool h459 = kFix459Desk && GetWindowRect(g_hWnd, &old459);   // FIX459
            SetWindowPos(g_hWnd, nullptr, L, T, R - L, B - T, fl);
            if (h459) Fix459InvalScreen(old459);   // FIX459: screen strip the window just left -> repainted by whatever is there (no ghost trail)
            if (!(kFix463Once && g_mainSizing)) RedrawWindow(g_hWnd, nullptr, nullptr, RDW_UPDATENOW | RDW_ALLCHILDREN);   /* FIX463: WM_SIZE already painted this step */   // Fix 177: sofort malen statt erst, wenn die Maus stillsteht
            if (kRec452) Rec452Step(L, T, R - L, B - T, fl, 1);   // FIX452 recorder (log-only)
            SetCursor(LoadCursorW(nullptr, MainEdgeCursor(g_mainSizeEdge)));
            return true;
        }
        if (const int e = MainEdgeAt(m.pt)) SetCursor(LoadCursorW(nullptr, MainEdgeCursor(e)));
        return false;
    case WM_LBUTTONDOWN: case WM_NCLBUTTONDOWN: case WM_LBUTTONDBLCLK: case WM_NCLBUTTONDBLCLK: {   // Fix 179: schneller 2. Klick kam als Doppelklick an und wurde ignoriert
        const int e = MainEdgeAt(m.pt);
        if (!e) return false;
        g_mainSizing = true; g_sizing457 = true; if (g_hRichEdit) GetClientRect(g_hRichEdit, &g_logFrz461); else SetRectEmpty(&g_logFrz461);   /* FIX461 */ g_mainSizeEdge = e; g_mainSizeStart = m.pt;
        if (kFix465Comp) { const LONG_PTR ex465 = GetWindowLongPtrW(g_hWnd, GWL_EXSTYLE); g_comp465 = false; if (!(ex465 & WS_EX_COMPOSITED)) { SetWindowLongPtrW(g_hWnd, GWL_EXSTYLE, ex465 | WS_EX_COMPOSITED); g_comp465 = true; } }   // FIX465: whole window in one off-screen pass while dragging (log via cache)
        if (kFix464NoClip) { const LONG_PTR st464 = GetWindowLongPtrW(g_hWnd, GWL_STYLE); g_clip464 = (st464 & WS_CLIPCHILDREN) != 0; if (g_clip464) SetWindowLongPtrW(g_hWnd, GWL_STYLE, st464 & ~(LONG_PTR)WS_CLIPCHILDREN); }   // FIX464: parent fill also covers vacated child pixels during the drag
        if (kRec452) Rec452Begin(e);   // FIX452 recorder (log-only)
        if (kRsz451 && !kNoComp452) { const LONG_PTR ex = GetWindowLongPtrW(g_hWnd, GWL_EXSTYLE); if (!(ex & WS_EX_COMPOSITED)) { SetWindowLongPtrW(g_hWnd, GWL_EXSTYLE, ex | WS_EX_COMPOSITED); g_comp451 = true; } }   // FIX451: whole window + log painted in one off-screen pass while dragging
        GetWindowRect(g_hWnd, &g_mainSizeRect);
        Snap455Begin();   // FIX455: snapshot + hide log for the drag
        SetCapture(g_hWnd);
        SetCursor(LoadCursorW(nullptr, MainEdgeCursor(e)));
        return true;
    }
    case WM_LBUTTONUP: case WM_NCLBUTTONUP:
        if (g_mainSizing) { g_mainSizing = false; ReleaseCapture(); MainSizeEnd(); return true; }   // Fix 250
        return false;
    }
    return false;
}
// Fix 254: WM_SIZE duration (QPC). With LWF_SIZE_TIMING set, the numbers go to %TEMP%\lwf_size_timing.txt.
static double g_sizeMsSum[2] = {}, g_sizeMsMax[2] = {}, g_sizePart[4] = {};
static double g_paintPart[8] = {};
static bool g_inSizeRedraw = false;
struct PartT { double* d; LARGE_INTEGER q; PartT(double* p) : d(p) { QueryPerformanceCounter(&q); } ~PartT() { if (!g_inSizeRedraw) return; LARGE_INTEGER b, fq; QueryPerformanceCounter(&b); QueryPerformanceFrequency(&fq); *d += (double)(b.QuadPart - q.QuadPart) * 1000.0 / (double)fq.QuadPart; } };
static double SzMs(const LARGE_INTEGER& a) { LARGE_INTEGER b, fq; QueryPerformanceCounter(&b); QueryPerformanceFrequency(&fq); return (double)(b.QuadPart - a.QuadPart) * 1000.0 / (double)fq.QuadPart; }
static unsigned g_sizeN[2] = {};
static void MainSizeStat(const LARGE_INTEGER& t0) {
    LARGE_INTEGER t1, fq;
    QueryPerformanceCounter(&t1); QueryPerformanceFrequency(&fq);
    const double ms = (double)(t1.QuadPart - t0.QuadPart) * 1000.0 / (double)fq.QuadPart;
    const int k = g_mainSizing ? 1 : 0;
    g_sizeMsSum[k] += ms; g_sizeN[k]++; if (ms > g_sizeMsMax[k]) g_sizeMsMax[k] = ms;
    static int s_env = -1;
    if (s_env < 0) s_env = GetEnvironmentVariableW(L"LWF_SIZE_TIMING", nullptr, 0) > 0 ? 1 : 0;
    if (!s_env) return;
    wchar_t p[MAX_PATH] = {};
    if (!GetTempPathW(MAX_PATH, p)) return;
    std::wstring path = std::wstring(p) + L"lwf_size_timing.txt";
    FILE* f = nullptr;
    if (_wfopen_s(&f, path.c_str(), L"w") != 0 || !f) return;
    fprintf(f, "paint (sum ms): main %.1f drawitem %.1f logview %.1f counters %.1f buttons %.1f pills %.1f\n", g_paintPart[0], g_paintPart[1], g_paintPart[2], g_paintPart[3], g_paintPart[4], g_paintPart[5]);
    fprintf(f, "parts (sum ms): layout %.1f end %.1f logresume %.1f redraw %.1f\n", g_sizePart[0], g_sizePart[1], g_sizePart[2], g_sizePart[3]);
    fprintf(f, "WM_SIZE programmatic: n=%u avg=%.3f ms max=%.3f ms\nWM_SIZE drag: n=%u avg=%.3f ms max=%.3f ms\n",
        g_sizeN[0], g_sizeN[0] ? g_sizeMsSum[0] / g_sizeN[0] : 0.0, g_sizeMsMax[0],
        g_sizeN[1], g_sizeN[1] ? g_sizeMsSum[1] / g_sizeN[1] : 0.0, g_sizeMsMax[1]);
    fclose(f);
}
// ===== Fix 358/358b: one click dispatcher for every Windows notification (WinRT toast activation or balloon click), UI thread =====
static void Toast358Click(unsigned seq, bool winrt, HWND hwnd) {
    static const char* const TK[5] = { "dig", "lucky", "firework", "egg", "drone" };
    const char* src = winrt ? "WinRT toast" : "tray balloon";
    if (!kToastSame358) {   // old behaviour (globals of the last notification)
        AllyLog299(Clk339() + " FIX358 toast click #" + std::to_string(seq) + " src=" + src + " path=old (kToastSame358 off)");
        const long long nxy = g_toastXY;
        if (nxy >= 0) { CnJump((int)(nxy >> 24), (int)(nxy & 0xFFFFFF)); return; }
        if (!g_toastChatUuid.empty()) { CnChat293(g_toastChatKind, -1, std::wstring(), g_toastChatUuid); return; }
        BringMainWindowToFront(hwnd); KeepMainWindowOnScreen(hwnd); return;
    }
    const Toast358* e = nullptr;
    for (auto it = g_toasts358.rbegin(); it != g_toasts358.rend(); ++it) if (it->seq == seq) { e = &*it; break; }
    if (!e) {
        AllyLog299(Clk339() + " FIX358 toast click #" + std::to_string(seq) + " src=" + src + " target unknown (older than the last 64 notifications) -> result: main window to front");
        BringMainWindowToFront(hwnd); KeepMainWindowOnScreen(hwnd); return;
    }
    const std::string pre = Clk339() + " FIX358 toast click #" + std::to_string(seq) + " src=" + src + " kind=" + (e->kind >= 0 && e->kind <= 4 ? TK[e->kind] : "?")
        + " age=" + std::to_string((GetTickCount64() - e->tick) / 1000) + "s bub=" + std::to_string(e->bub)
        + " xy=" + (e->xy >= 0 ? std::to_string(e->xy >> 24) + ":" + std::to_string(e->xy & 0xFFFFFF) : std::string("-")) + " uuid=" + (e->uuid.empty() ? std::string("-") : e->uuid);
    const char* why = "no bubble target (logging off / no row, xy, uuid)";
    bool act = false;
    if (e->bub) {
        why = "bubble target evicted (more than 16 newer finds)";
        for (const auto& bt : g_glowBubbleTargets) if (bt.id == e->bub) {
            LONG st = -1;
            const bool row = g_hRichEdit && bt.t.set && LogGlowTargetValid(g_hRichEdit, bt.t, st);
            act = g_hRichEdit && (row || bt.xy >= 0 || !bt.t.pendingUuid.empty());
            why = act ? (row ? "log row" : bt.xy >= 0 ? "bubble xy" : "bubble uuid") : "bubble target empty (row gone, no xy/uuid)";
            break;
        }
    }
    if (act) { AllyLog299(pre + " path=CnBubble (same function as the bubble click) via " + why + " -> result: dispatched"); CnBubble(e->bub); return; }
    // fallback with the target captured at notification time (same functions the bubble path ends in)
    if (e->xy >= 0) { AllyLog299(pre + " path=fallback (" + why + ") -> result: CnJump"); CnJump((int)(e->xy >> 24), (int)(e->xy & 0xFFFFFF)); return; }
    if (!e->uuid.empty()) { AllyLog299(pre + " path=fallback (" + why + ") -> result: CnChat293"); CnChat293(e->chatKind, -1, std::wstring(), e->uuid); return; }
    AllyLog299(pre + " path=fallback (" + why + ") -> result: main window to front (no target)");
    BringMainWindowToFront(hwnd); KeepMainWindowOnScreen(hwnd);
}
