    if (msg == WM_SETCURSOR) {   // Fix 176: Pfeil oben/unten am Rand
        POINT s; GetCursorPos(&s);
        if (g_mainSizing && !kFix467NoManual /* FIX467 */) { SetCursor(LoadCursorW(nullptr, MainEdgeCursor(g_mainSizeEdge))); return TRUE; }   // Fix 243
        if (const int e = MainEdgeAt(s)) { SetCursor(LoadCursorW(nullptr, MainEdgeCursor(e))); return TRUE; }
        // Fix 212: außerhalb des Logs sofort der normale Pfeil (das I des Logs blieb sonst kurz stehen); im Log setzt das RichEdit sein I selbst
        if (LOWORD(lParam) == HTCLIENT && (HWND)wParam == hwnd && hwnd == g_hWnd && (F380Hit(hwnd) || Chat395Hit(hwnd) /* FIX395 */ || Help396Hit(hwnd) /* FIX396C */)) { SetCursor(LoadCursorW(nullptr, IDC_HAND)); return TRUE; }   // FIX380: own profile row = clickable
        if (LOWORD(lParam) == HTCLIENT && (HWND)wParam != g_hRichEdit) { SetCursor(LoadCursorW(nullptr, IDC_ARROW)); return TRUE; }
    }
