static void CnJump(int X, int Y) {   // UI thread: game to the front, then the worker moves the camera
    { SYSTEMTIME st363; GetLocalTime(&st363); ClkMark363(GetTickCount64(), st363); }   // FIX363: click time (log only)
    const DWORD pid = GetPIDByName(L"LastWar.exe");
    if (!pid) { CdTip(0); return; }
    if (X < 0 || Y < 0 || X > 0xFFFFFF || Y > 0xFFFFFF) return;
    F364OnJump(X, Y);   // FIX364: queue only (worker thread), jump not delayed
    if (g_camBusy.exchange(true)) {   // Fix 268: queue instead of a second parallel worker
        CnFront(pid);   // Fix 320: queued clicks also bring the game to the front (before only the first click did)
        g_camPend = (1ull << 63) | ((unsigned long long)X << 24) | (unsigned long long)Y;
        return;
    }
    CnFront(pid);
    // Fix 286: Lua ChangeToWorld (if Basis) + JumpToWorldPoint from log/bubble click coords
    try { std::thread([pid, X, Y] {
        try { GwInj286(pid, X, Y); } catch (...) {}
        for (;;) { try { CamDrain294(pid); } catch (...) {} g_camBusy = false; if (!CamWorkPend325() || g_camBusy.exchange(true)) break; }   // Fix 325: re-drain a job queued in the busy->idle race
    }).detach(); }
    catch (...) { g_camBusy = false; }
}
static std::string CnU8(const std::wstring& w) {
    if (w.empty()) return std::string();
    const int n = WideCharToMultiByte(CP_UTF8, 0, w.c_str(), (int)w.size(), nullptr, 0, nullptr, nullptr);
    std::string s((size_t)(n > 0 ? n : 0), '\0');
    if (n > 0) WideCharToMultiByte(CP_UTF8, 0, w.c_str(), (int)w.size(), &s[0], n, nullptr, nullptr);
    return s;
}
static bool CnCharAt(HWND hwnd, POINT pt, LONG& ch) {
    return CnHitChar(hwnd, pt, ch);   // Fix 265
}
// gift word / egg name / firework word of a log row ("[hh:mm:ss]: label[: sender] [N]") under a client point
static bool CnLabelAt(HWND hwnd, POINT pt, int& kind, LONG& rowStart, std::wstring& row) {
    LONG ch = 0;
    if (!CnCharAt(hwnd, pt, ch)) return false;
    const LONG from = std::max<LONG>(0, ch - 200);
    wchar_t buf[480] = {};
    TEXTRANGEW tr = {};
    tr.chrg.cpMin = from; tr.chrg.cpMax = ch + 200; tr.lpstrText = buf;
    const LONG n = (LONG)SendMessageW(hwnd, EM_GETTEXTRANGE, 0, (LPARAM)&tr);
    if (n <= 0 || n >= 480 || ch - from >= n) return false;
    const std::wstring s(buf, (size_t)n);
    const size_t rel = (size_t)(ch - from);
    if (s[rel] == L'\r' || s[rel] == L'\n') return false;
    size_t ps = s.find_last_of(L"\r\n", rel);
    if (ps == std::wstring::npos) { if (from > 0) return false; ps = 0; }
    else ++ps;
    size_t pe = s.find_first_of(L"\r\n", rel);
    if (pe == std::wstring::npos) pe = s.size();
    if (ps >= pe || s[ps] != L'[') return false;
    const size_t k = s.find(L"]: ", ps);
    if (k == std::wstring::npos || k > ps + 16 || k >= pe) return false;
    const size_t l0 = k + 3;
    size_t l1 = l0;
    while (l1 < pe && s[l1] != L':' && s[l1] != L'\uFF1A' && !(s[l1] == L' ' && l1 + 1 < pe && s[l1 + 1] >= L'0' && s[l1 + 1] <= L'9')) ++l1;
    while (l1 > l0 && (s[l1 - 1] == L' ' || CdBidiMark(s[l1 - 1]))) --l1;
    if (rel < l0 || rel >= l1) return false;
    const LONG rs = from + (LONG)ps;
    GETTEXTLENGTHEX gtl = { GTL_NUMCHARS | GTL_PRECISE, 1200 };
    const LONG total = (LONG)SendMessageW(hwnd, EM_GETTEXTLENGTHEX, (WPARAM)&gtl, 0);
    const int kd = IsLuckyLogLine(hwnd, rs, total) ? 1 : IsFireworkLogLine(hwnd, rs, total) ? 2 : IsEggLogLine(hwnd, rs, total) ? 3 : 0;
    if (!kd) return false;
    kind = kd; rowStart = rs; row = s.substr(ps, pe - ps);
    return true;
}
static std::wstring CnRowText(LONG start) {
    if (!g_hRichEdit || start < 0) return std::wstring();
    wchar_t buf[420] = {};
    TEXTRANGEW tr = {};
    tr.chrg.cpMin = start; tr.chrg.cpMax = start + 400; tr.lpstrText = buf;
    const LONG n = (LONG)SendMessageW(g_hRichEdit, EM_GETTEXTRANGE, 0, (LPARAM)&tr);
    if (n <= 0 || n > 400) return std::wstring();
    std::wstring s(buf, (size_t)n);
    const size_t e = s.find_first_of(L"\r\n");
    if (e != std::wstring::npos) s.resize(e);
    return s;
}
static bool CnRowXY(const std::wstring& s, int& X, int& Y) {
    for (size_t j = 0; j + 1 < s.size(); ++j) {
        if (s[j] != L'X' || s[j + 1] != L':') continue;
        int x = 0, y = 0;
        size_t k = CdNumW(s, j + 2, s.size(), x);
        if (k == std::wstring::npos) continue;
        while (k < s.size() && (CdBidiMark(s[k]) || s[k] == L' ')) ++k;
        if (k + 1 >= s.size() || s[k] != L'Y' || s[k + 1] != L':') continue;
        if (CdNumW(s, k + 2, s.size(), y) == std::wstring::npos) continue;
        if (x > 2000 || y > 2000) continue;
        X = x; Y = y;
        return true;
    }
    return false;
}
// ---- chat message remembered by a gift / egg / firework link (debug only for now) ----
struct CnMsgSel { int kind = 0; LONG rowStart = -1; std::wstring row; std::string uuid; unsigned seq = 0; };
static CnMsgSel g_cnSel;   // UI thread
static std::vector<ULONG_PTR> g_cnTargets;   // string objects / slots of the remembered message (guarded by g_cdBusy)
static unsigned g_cnTargetsSeq = 0;
static std::vector<ULONG_PTR> g_cnTrack;     // slots pointing at the remembered message in every C press
static bool g_cnTrackInit = false;
static void CnUuidSearch(DWORD pid, const std::string& uuid, unsigned seq) {   // worker, g_cdBusy is set; read-only
    FILE* f = nullptr;
    f = _wfsopen(CdLogPath().c_str(), L"a", _SH_DENYNO); if (!f) return;   // Fix 299: shared
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { fprintf(f, "uuid search: no access\n"); fclose(f); return; }
    const ULONGLONG t0 = GetTickCount64();
    std::vector<BYTE> pa(uuid.begin(), uuid.end()), pw;
    for (char c : uuid) { pw.push_back((BYTE)c); pw.push_back(0); }
    std::vector<ULONG_PTR> sa, sw, objs;
    const size_t CH = (size_t)1 << 20;
    std::vector<BYTE> buf(CH + 0x100);
    for (int pass = 0; pass < 2; ++pass) {
        std::vector<ULONG_PTR> tg = objs;
        tg.insert(tg.end(), sa.begin(), sa.end());
        std::sort(tg.begin(), tg.end());
        std::vector<ULONG_PTR> slots;
        MEMORY_BASIC_INFORMATION m = {};
        ULONG_PTR a = 0x10000;
        while (VirtualQueryEx(h, (LPCVOID)a, &m, sizeof(m)) == sizeof(m)) {
            const ULONG_PTR rb = (ULONG_PTR)m.BaseAddress, rs = m.RegionSize;
            if (DsRegionOk(m)) for (ULONG_PTR o = 0; o < rs; o += CH) {
                const size_t want = (size_t)std::min<ULONG_PTR>(rs - o, CH + 0x100);
                SIZE_T got = 0;
                if (!ReadProcessMemory(h, (LPCVOID)(rb + o), buf.data(), want, &got) || got < 8) continue;
                const size_t lim = std::min<size_t>(got, CH);
                if (pass == 0) {
                    for (size_t i = 0; i < lim; ++i) {
                        if (buf[i] != pa[0]) continue;
                        if (i + pa.size() <= got && sa.size() < 32 && memcmp(&buf[i], pa.data(), pa.size()) == 0) sa.push_back(rb + o + i);
                        if (i + pw.size() <= got && sw.size() < 32 && memcmp(&buf[i], pw.data(), pw.size()) == 0) {
                            sw.push_back(rb + o + i);
                            int len = -1;
                            if (i >= 4) memcpy(&len, &buf[i - 4], 4);
                            if (len == (int)uuid.size() && rb + o + i >= 0x14) objs.push_back(rb + o + i - 0x14);
                        }
                    }
                }
                else if (!tg.empty()) {
                    for (size_t i = 0; i + 8 <= got && i < lim && slots.size() < 64; i += 8) {
                        ULONG_PTR q; memcpy(&q, &buf[i], 8);
                        if (std::binary_search(tg.begin(), tg.end(), q)) slots.push_back(rb + o + i);
                    }
                }
            }
            const ULONG_PTR nx = rb + rs;
            if (nx <= a) break;
            a = nx;
        }
        if (pass == 1) {
            fprintf(f, "uuid '%s': %zu ASCII copies, %zu UTF-16 copies, %zu string objects, %zu pointers to them (%llu ms)\n", uuid.c_str(), sa.size(), sw.size(), objs.size(), slots.size(), GetTickCount64() - t0);
            for (ULONG_PTR x : sa) fprintf(f, "  ascii  0x%016llX  %s\n", (unsigned long long)x, CdRegion(h, x).c_str());
            for (ULONG_PTR x : sw) fprintf(f, "  utf16  0x%016llX  %s\n", (unsigned long long)x, CdRegion(h, x).c_str());
            for (ULONG_PTR x : objs) fprintf(f, "  string object 0x%016llX\n", (unsigned long long)x);
            for (ULONG_PTR x : slots) fprintf(f, "  pointer at 0x%016llX  %s (message object field)\n", (unsigned long long)x, CdRegion(h, x).c_str());
            std::vector<ULONG_PTR> t2 = objs;
            t2.insert(t2.end(), slots.begin(), slots.end());
            std::sort(t2.begin(), t2.end());
            t2.erase(std::unique(t2.begin(), t2.end()), t2.end());
            g_cnTargets = t2; g_cnTargetsSeq = seq;
        }
    }
    CloseHandle(h);
    fclose(f);
}
static void CnRemember(int kind, LONG rowStart, const std::wstring& row, const std::string& uuidIn) {   // UI thread
    if (!g_cdOn) return;   // jumping the game chat is not built yet; debug only remembers the message
    g_cnSel.kind = kind; g_cnSel.rowStart = rowStart; g_cnSel.row = row; g_cnSel.uuid = uuidIn;
    if (g_cnSel.uuid.empty() && rowStart >= 0) for (const auto& c : g_luckyCountLines) if (c.lineStart == rowStart) { g_cnSel.uuid = c.uuid; break; }
    if (g_cnSel.uuid.empty() && rowStart >= 0) for (const auto& c : g_eggLabelLines) if (c.lineStart == rowStart) { g_cnSel.uuid = c.uuid; break; }
    ++g_cnSel.seq;
    static const char* const KN[4] = { "?", "lucky gift", "firework", "egg" };
    const std::string txt = "\n=== Chat message remembered (#" + std::to_string(g_cnSel.seq) + "): " + KN[kind >= 0 && kind <= 3 ? kind : 0]
        + "  uuid=" + (g_cnSel.uuid.empty() ? std::string("-") : g_cnSel.uuid) + "  row@" + std::to_string(rowStart) + "  '" + CnU8(row) + "'";
    CdLogLine(txt.c_str());
    if (g_cnSel.uuid.empty()) return;
    const DWORD pid = GetPIDByName(L"LastWar.exe");
    if (!pid) { CdLogLine("game not running: no memory search"); return; }
    if (g_cdBusy.exchange(true)) { CdLogLine("busy: uuid search skipped (click the link again later)"); return; }
    const std::string u = g_cnSel.uuid; const unsigned seq = g_cnSel.seq;
    std::thread([pid, u, seq] { CnUuidSearch(pid, u, seq); g_cdBusy = false; }).detach();
}
