    if (g_fwSeen371.size() > 3000) g_fwSeen371.clear();
    g_fwSeen371.insert(uuid);
    if (UiGiftFlags(uuid) & 4) { Fw371Log("AUTO firework uuid=" + uuid + ": already collected (own uid in the claim list) -> skipped"); return; }
    g_fwQ371.push_back({ uuid, GetTickCount64() });
    Fw371Log("AUTO firework queued uuid=" + uuid + " (queue=" + std::to_string(g_fwQ371.size()) + ")");
