static void Fw371Tick() {
    const ULONGLONG now = GetTickCount64();
    if (!g_fwCur371.empty()) {
        if (g_camBusy.load() || CamWorkPend325()) return;
        Fw371Log("AUTO firework done uuid=" + g_fwCur371 + " after " + std::to_string(now - g_fwCurMs371) + " ms (" + ((UiGiftFlags(g_fwCur371) & 4) ? "own uid in the claim list" : "result: see the FIX352 lines") + ")");
        g_fwCur371.clear();
    }
    if (g_fwQ371.empty()) return;
    if (!g_auto371.load()) { Fw371Log("MANUELL: " + std::to_string(g_fwQ371.size()) + " queued firework(s) dropped"); g_fwQ371.clear(); return; }
    if (g_autoDigBusy371.load() || g_camBusy.load() || CamWorkPend325()) return;
    const Fw371Item f = g_fwQ371.front();
    if (now - f.addMs > 180000ull) { g_fwQ371.pop_front(); Fw371Log("AUTO firework uuid=" + f.uuid + ": queued > 180 s -> dropped"); return; }
    if (UiGiftFlags(f.uuid) & 4) { g_fwQ371.pop_front(); Fw371Log("AUTO firework uuid=" + f.uuid + ": already collected -> skipped"); return; }
    ChatSrc293 cs;
    const bool src = ChatSrc293Get(f.uuid, cs) && cs.room.compare(0, 9, "alliance_") == 0 && !cs.seq.empty();
    if (!src) {
        if (now - f.addMs > 5000ull) { g_fwQ371.pop_front(); Fw371Log("AUTO firework uuid=" + f.uuid + ": no alliance chat source (room / seqId) after 5 s -> the click action cannot run -> dropped"); }
        return;
    }
    g_fwQ371.pop_front();
    g_fwCur371 = f.uuid; g_fwCurMs371 = now;
    Fw371Log("AUTO firework start uuid=" + f.uuid + " room=" + cs.room + " seqId=" + cs.seq + " -> same action as a firework click (CnChat293 -> CamDrain294 -> Fw352Run), " + std::to_string(g_fwQ371.size()) + " left");
    CnChat293(2, -1, std::wstring(), f.uuid);
    if (!g_camBusy.load() && !CamWorkPend325()) { Fw371Log("AUTO firework uuid=" + f.uuid + ": no job started (game not running / not an alliance find)"); g_fwCur371.clear(); }
}
