// ---- read-only discovery: Ctrl+Alt+B / M (base / map), Ctrl+Alt+C / X (chat open with the remembered message on top / chat closed) ----
struct DsCand { ULONG_PTR a; float v[2]; unsigned char t; };   // t 0 = u8, 1 = f32; v[state]
struct DsExp { int dumpState = -1; bool diffed = false; bool capped = false; DWORD pid = 0; int presses[2] = { 0, 0 }; std::vector<DsCand> c; };
static DsExp g_ds[2];
static const char* const DS_NAME[2] = { "base/map", "chat open/closed" };
static const char* const DS_STATE[2][2] = { { "BASE", "MAP" }, { "CHAT-OPEN", "CHAT-CLOSED" } };
static std::wstring DsPath(int x) { wchar_t t[MAX_PATH] = {}; GetTempPathW(MAX_PATH, t); return std::wstring(t) + (x ? L"lwf_cd_chat.bin" : L"lwf_cd_bm.bin"); }
static unsigned long long DsDump(HANDLE h, const std::wstring& path) {
    FILE* o = nullptr;
    if (_wfopen_s(&o, path.c_str(), L"wb") != 0 || !o) return 0;
    const size_t CH = (size_t)1 << 20;
    std::vector<BYTE> buf(CH);
    unsigned long long tot = 0;
    MEMORY_BASIC_INFORMATION m = {};
    ULONG_PTR a = 0x10000;
    bool bad = false;
    while (!bad && tot < (3ull << 30) && VirtualQueryEx(h, (LPCVOID)a, &m, sizeof(m)) == sizeof(m)) {
        const ULONG_PTR rb = (ULONG_PTR)m.BaseAddress, rs = m.RegionSize;
        if (DsRegionOk(m) || DsModRw(h, m)) for (ULONG_PTR off = 0; off < rs && !bad; off += CH) {   // Fix 269: + GameAssembly/UnityPlayer data
            const size_t want = (size_t)std::min<ULONG_PTR>(rs - off, CH);
            SIZE_T got = 0;
            if (!ReadProcessMemory(h, (LPCVOID)(rb + off), buf.data(), want, &got) || !got) continue;
            const unsigned long long ad = rb + off; const unsigned int n = (unsigned int)got;
            if (fwrite(&ad, 8, 1, o) != 1 || fwrite(&n, 4, 1, o) != 1 || fwrite(buf.data(), 1, got, o) != got) bad = true;
            tot += got;
        }
        const ULONG_PTR nx = rb + rs;
        if (nx <= a) break;
        a = nx;
    }
    fclose(o);
    return bad ? 0 : tot;
}
static bool DsSmallF(float v) { return v >= 0.0f && v <= 16.0f && (v == 0.0f || v >= 0.001f); }
static void DsDiff(HANDLE h, DsExp& e, int s, const std::wstring& path) {
    FILE* in = nullptr;
    if (_wfopen_s(&in, path.c_str(), L"rb") != 0 || !in) return;
    const int d = e.dumpState;
    std::vector<BYTE> A((size_t)1 << 20), B((size_t)1 << 20);
    e.c.clear();
    const size_t CAP = 1500000;
    unsigned long long ad = 0; unsigned int n = 0;
    while (fread(&ad, 8, 1, in) == 1 && fread(&n, 4, 1, in) == 1) {
        if (n > A.size() || fread(A.data(), 1, n, in) != n) break;
        if (e.c.size() >= CAP) { e.capped = true; continue; }
        SIZE_T got = 0;
        if (!ReadProcessMemory(h, (LPCVOID)ad, B.data(), n, &got) || got != n) continue;
        for (unsigned int i = 0; i < n && e.c.size() < CAP; ++i) {
            const BYTE x = A[i], y = B[i];
            if (x != y && x <= 16 && y <= 16) { DsCand c = {}; c.a = (ULONG_PTR)(ad + i); c.v[d] = x; c.v[s] = y; c.t = 0; e.c.push_back(c); }
            if ((i & 3) == 0 && i + 4 <= n && memcmp(&A[i], &B[i], 4) != 0) {
                float fa, fb; memcpy(&fa, &A[i], 4); memcpy(&fb, &B[i], 4);
                if (DsSmallF(fa) && DsSmallF(fb) && fa != fb) { DsCand c = {}; c.a = (ULONG_PTR)(ad + i); c.v[d] = fa; c.v[s] = fb; c.t = 1; e.c.push_back(c); }
            }
        }
    }
    fclose(in);
}
static void DsRefine(HANDLE h, DsExp& e, int s) {
    std::vector<BYTE> w(65536);
    ULONG_PTR wb = 0; SIZE_T wl = 0;
    size_t keep = 0;
    for (size_t k = 0; k < e.c.size(); ++k) {
        const DsCand c = e.c[k];
        const ULONG_PTR sz = c.t ? 4 : 1;
        if (c.a < wb || c.a + sz > wb + wl) {
            wb = c.a & ~(ULONG_PTR)0xFFF; wl = 0;
            if (!ReadProcessMemory(h, (LPCVOID)wb, w.data(), w.size(), &wl)) { wl = 0; if (!ReadProcessMemory(h, (LPCVOID)wb, w.data(), 4096, &wl)) wl = 0; }
        }
        if (c.a < wb || c.a + sz > wb + wl) continue;
        const BYTE* p = w.data() + (c.a - wb);
        bool same;
        if (c.t == 0) same = (float)*p == c.v[s];
        else { float fv; memcpy(&fv, p, 4); same = fv == c.v[s]; }
        if (same) e.c[keep++] = c;
    }
    e.c.resize(keep);
}
static void CnPtrHints(HANDLE h, FILE* f, std::vector<ULONG_PTR> ad) {   // module data pointing at (or up to 0x2000 before) an address
    if (ad.empty()) return;
    std::sort(ad.begin(), ad.end());
    size_t hits = 0;
    const size_t CH = (size_t)1 << 20;
    std::vector<BYTE> buf(CH);
    MEMORY_BASIC_INFORMATION m = {};
    ULONG_PTR a = 0x10000;
    while (hits < 60 && VirtualQueryEx(h, (LPCVOID)a, &m, sizeof(m)) == sizeof(m)) {
        const ULONG_PTR rb = (ULONG_PTR)m.BaseAddress, rs = m.RegionSize;
        const DWORD pr = m.Protect & 0xFF;
        if (m.State == MEM_COMMIT && m.Type == MEM_IMAGE && (pr == PAGE_READWRITE || pr == PAGE_WRITECOPY) && !(m.Protect & PAGE_GUARD)) {
            for (ULONG_PTR o = 0; o < rs && hits < 60; o += CH) {
                SIZE_T got = 0;
                if (!ReadProcessMemory(h, (LPCVOID)(rb + o), buf.data(), (size_t)std::min<ULONG_PTR>(rs - o, CH), &got)) continue;
                for (size_t i = 0; i + 8 <= got && hits < 60; i += 8) {
                    ULONG_PTR q; memcpy(&q, &buf[i], 8);
                    auto it = std::lower_bound(ad.begin(), ad.end(), q);
                    if (it == ad.end() || *it - q > 0x2000) continue;
                    ++hits;
                    fprintf(f, "  pointer hint: %s holds 0x%016llX -> 0x%016llX (+0x%llX)\n", CdRegion(h, rb + o + i).c_str(), (unsigned long long)q, (unsigned long long)*it, (unsigned long long)(*it - q));
                }
            }
        }
        const ULONG_PTR nx = rb + rs;
        if (nx <= a) break;
        a = nx;
    }
    if (!hits) fprintf(f, "  pointer hints: none in module data\n");
}
// Fix 269: base/map flag chains from GameAssembly.dll / UnityPlayer.dll static data; checked on every B/M press, also after a game restart
static int g_dsLastState = 0;   // 0 = base, 1 = world map (last B/M press)
struct MfCnt { int ok[2] = { 0, 0 }; int bad = 0; };
static std::map<std::string, MfCnt> g_mfCnt;   // per game session
static unsigned long long g_mfSess = 0;
static void DsFlagCheck(HANDLE h, FILE* f, int s) {   // Fix 271: saved chains read now, +3 s, +8 s; right value at all three = ok for this state, else a contradiction; 2x base + 2x map ok without contradiction = st=1 (n+1 in a NEW game session); 2 contradictions = removed
    unsigned long long os = 0;
    std::vector<PcChain> v;
    if (!PcLoad(L"mapflags.txt", os, v) || v.empty()) { fprintf(f, "Fix 269 mapflags.txt: no flag chains saved yet (keep alternating B/M until 2000 or fewer survivors remain)\n"); return; }
    const unsigned long long cs = PcSession(h);
    if (cs != g_mfSess) { g_mfCnt.clear(); g_mfSess = cs; }
    std::vector<PcChain> keep;
    std::vector<MfInfo> inf;
    for (const PcChain& c : v) { MfInfo mi; if (MfParse(c.extra, mi)) { keep.push_back(c); inf.push_back(mi); } }
    const size_t old = v.size() - keep.size();
    std::vector<int> val(keep.size() * 3, -1);   // -1 = not readable
    static const ULONGLONG AT[3] = { 0, 3000, 8000 };
    fprintf(f, "Fix 271 saved flag chains (%s, state %s): read now, +3 s and +8 s - stay in this screen until the beep\n", os == cs ? "same game session" : "game was restarted", s ? "MAP" : "BASE");
    fflush(f);
    const ULONGLONG t0 = GetTickCount64();
    for (int k = 0; k < 3; ++k) {
        while (GetTickCount64() - t0 < AT[k]) Sleep(50);
        std::map<std::string, ULONG_PTR> mb;
        for (size_t i = 0; i < keep.size(); ++i) { BYTE b = 0; if (MfByteOk(h, PcResolve(h, keep[i], mb), b)) val[i * 3 + k] = b; }
    }
    auto vs = [](int x) { return x < 0 ? std::string("-") : std::to_string(x); };
    std::vector<PcChain> out;
    size_t match = 0, conf = 0, drop = 0, lines = 0;
    bool chg = old > 0;
    for (size_t i = 0; i < keep.size(); ++i) {
        PcChain c = keep[i];
        MfInfo mi = inf[i];
        MfCnt& ct = g_mfCnt[PcText(c)];
        const int want = (int)(s ? mi.m : mi.b);
        const int* r = &val[i * 3];
        const bool stable = r[0] == want && r[1] == want && r[2] == want;
        const char* vd = stable ? "stable" : (r[0] == want ? "REVERTS" : "WRONG");
        if (stable) { ++ct.ok[s]; ++match; }
        else ++ct.bad;
        if (ct.bad >= 2) {
            ++drop; chg = true;
            if (lines++ < 60) fprintf(f, "  removed n=%d %s  now %s / +3s %s / +8s %s  want %d -> %s (2nd contradiction)\n", c.n, PcText(c).c_str(), vs(r[0]).c_str(), vs(r[1]).c_str(), vs(r[2]).c_str(), want, vd);
            continue;
        }
        if (!stable && mi.st) { mi.st = 0; c.extra = MfText(mi); chg = true; }   // a contradiction withdraws the stable mark
        if (ct.ok[0] >= 2 && ct.ok[1] >= 2 && ct.bad == 0 && (mi.s != cs || !mi.st)) { if (mi.s != cs) ++c.n; mi.s = cs; mi.st = 1; c.extra = MfText(mi); chg = true; }
        if (c.n >= 2 && mi.st) ++conf;
        if (lines++ < 60) fprintf(f, "  n=%d st=%u %s  now %s / +3s %s / +8s %s  want %d -> %s  ok base %d map %d contradictions %d\n", c.n, mi.st, PcText(c).c_str(),
            vs(r[0]).c_str(), vs(r[1]).c_str(), vs(r[2]).c_str(), want, vd, ct.ok[0], ct.ok[1], ct.bad);
        out.push_back(c);
    }
    if (chg) { PcSortTrim(out, 1000); PcSave(L"mapflags.txt", cs, out); }
    fprintf(f, "Fix 271 summary: %zu chains, %zu stable right now, %zu removed, %zu old-format lines dropped, %zu stable confirmed (n>=2 and st=1 -> used for the 1-click switch)\n", out.size(), match, drop, old, conf);
}
static bool DsFlagSearch(HANDLE h, FILE* f, const DsExp& e, size_t& rot, size_t& cov) {   // read-only: survivors (u8) -> exact chains from the two game modules -> mapflags.txt; Fix 270: max 600 flags per run, in turns; true = more to do
    std::vector<const DsCand*> all8;
    for (int pass = 0; pass < 2; ++pass)
        for (const DsCand& c : e.c) {
            if (c.t != 0) continue;
            const bool b01 = (c.v[0] == 0.0f || c.v[0] == 1.0f) && (c.v[1] == 0.0f || c.v[1] == 1.0f);
            if ((pass == 0) == b01) all8.push_back(&c);
        }
    if (all8.empty()) { fprintf(f, "Fix 270 chain search: no byte/int flags among the survivors\n"); return false; }
    const size_t T = all8.size(), W = std::min<size_t>(T, 600), from = rot % T;
    std::map<ULONG_PTR, std::pair<unsigned, unsigned>> tv;
    for (size_t i = 0; i < W; ++i) { const DsCand& c = *all8[(from + i) % T]; tv[c.a] = std::make_pair((unsigned)c.v[0], (unsigned)c.v[1]); }
    rot = (from + W) % T;
    cov += W;
    fprintf(f, "Fix 270 chain search: %zu byte/int flags in total, this run %zu (index %zu..%zu, in turns), %zu of %zu covered for this survivor set\n", T, W, from, (from + W - 1) % T, std::min(cov, T), T);
    std::vector<ULONG_PTR> tg;
    for (const auto& kv : tv) tg.push_back(kv.first);
    const ULONGLONG t0 = GetTickCount64();
    const unsigned long long cs = PcSession(h);
    std::vector<PcChain> found;
    std::string log;
    MEMORY_BASIC_INFORMATION m = {};
    for (ULONG_PTR a : tg)   // flag directly inside module data: chain without pointers
        if (VirtualQueryEx(h, (LPCVOID)a, &m, sizeof(m)) == sizeof(m) && DsModRw(h, m)) {
            PcChain c;
            c.mod = PcModName(h, (ULONG_PTR)m.AllocationBase);
            c.rva = a - (ULONG_PTR)m.AllocationBase;
            found.push_back(c);
        }
    static const char* const MODS[2] = { "GameAssembly.dll", "UnityPlayer.dll" };
    for (const char* md : MODS) {
        const ULONG_PTR base = PcModBase(h, md);
        MODULEINFO mi = {};
        if (!base || !K32GetModuleInformation(h, (HMODULE)base, &mi, sizeof(mi))) { log += std::string("  ") + md + " not found\n"; continue; }
        std::vector<PcChain> o;
        UpScan(h, base, (ULONG_PTR)mi.SizeOfImage, tg, 4, 0x800, 0x800, GetTickCount64() + 20000, 20000, o, log, md);
        found.insert(found.end(), o.begin(), o.end());
    }
    std::map<std::string, ULONG_PTR> mb;
    std::vector<PcChain> add;
    for (PcChain& c : found) {   // exact end only, value must match the current state
        if (add.size() >= 1000) break;
        const ULONG_PTR a = PcResolve(h, c, mb);
        const auto it = tv.find(a);
        if (it == tv.end()) continue;
        BYTE b = 0;
        const unsigned want = g_dsLastState ? it->second.second : it->second.first;
        if (!MfByteOk(h, a, b) || b != want) continue;
        MfInfo fi;
        fi.b = it->second.first; fi.m = it->second.second; fi.s = cs;
        if (fi.b == fi.m || fi.b > 255 || fi.m > 255) continue;
        c.n = 1; c.extra = MfText(fi);
        add.push_back(c);
    }
    unsigned long long os = 0;
    std::vector<PcChain> all, sv;
    PcLoad(L"mapflags.txt", os, sv);
    for (const PcChain& c : sv) { MfInfo x; if (MfParse(c.extra, x)) all.push_back(c); }
    all.insert(all.end(), add.begin(), add.end());
    PcSortTrim(all, 1000);
    fprintf(f, "Fix 269 chain search for %zu flags (%llu ms):\n%s", tg.size(), GetTickCount64() - t0, log.c_str());
    for (size_t i = 0; i < add.size() && i < 60; ++i) fprintf(f, "  new %s  [%s]\n", PcText(add[i]).c_str(), add[i].extra.c_str());
    if (!all.empty()) PcSave(L"mapflags.txt", cs, all);
    size_t conf = 0;
    for (const PcChain& c : all) if (c.n >= 2) ++conf;
    fprintf(f, "Fix 270 mapflags.txt %s: %zu chains (%zu new in this run, %zu confirmed n>=2)%s\n", all.empty() ? "NOT written (nothing found)" : "saved", all.size(), add.size(), conf,
        all.empty() ? "" : " - restart the game, then 2x B in the base and 2x M on the map to confirm");
    for (size_t i = 0; i < all.size() && i < 40; ++i) fprintf(f, "  saved n=%d %s  [%s]\n", all[i].n, PcText(all[i]).c_str(), all[i].extra.c_str());
    return cov < T;
}
static void DsReport(HANDLE h, FILE* f, const DsExp& e, int x) {   // Fix 262: list up to 2000, clean flips first
    fprintf(f, "survivors: %zu%s\n", e.c.size(), e.capped ? " (first compare capped at 1.5M)" : "");
    if (e.c.size() > 2000) { fprintf(f, "  (listed once 2000 or fewer remain - keep alternating)\n"); return; }
    std::vector<std::pair<int, size_t>> ord;
    for (size_t k = 0; k < e.c.size(); ++k) {
        const DsCand& c = e.c[k];
        const bool iv = c.v[0] == std::floor(c.v[0]) && c.v[1] == std::floor(c.v[1]);
        const bool b01 = iv && (c.v[0] == 0.0f || c.v[0] == 1.0f) && (c.v[1] == 0.0f || c.v[1] == 1.0f);
        ord.push_back(std::make_pair(c.t == 0 ? (b01 ? 0 : 1) : (b01 ? 2 : iv ? 3 : 4), k));
    }
    std::stable_sort(ord.begin(), ord.end(), [](const std::pair<int, size_t>& p, const std::pair<int, size_t>& q) { return p.first < q.first; });
    static const char* const RK[5] = { "BOOL 0/1", "small int", "f32 0/1", "f32 int", "f32" };
    std::vector<ULONG_PTR> ad;
    for (const auto& o : ord) {
        const DsCand& c = e.c[o.second];
        BYTE raw[4] = {}; SIZE_T got = 0;
        const ULONG_PTR al = c.a & ~(ULONG_PTR)3;
        const bool rd = ReadProcessMemory(h, (LPCVOID)al, raw, 4, &got) && got == 4;
        const unsigned off = (unsigned)(c.a - al);
        const char* sz = "f32";
        if (c.t == 0) {
            bool hiZero = off == 0 && rd && raw[1] == 0 && raw[2] == 0 && raw[3] == 0;
            sz = hiZero ? "i32?" : "u8";
        }
        int i32 = 0; float f32 = 0.0f;
        memcpy(&i32, raw, 4); memcpy(&f32, raw, 4);
        fprintf(f, "  [%-9s] 0x%016llX %-4s %s=%g %s=%g  now(dword@-%u): u8=%u i32=%d f32=%g  %s\n", RK[o.first], (unsigned long long)c.a, sz,
            DS_STATE[x][0], (double)c.v[0], DS_STATE[x][1], (double)c.v[1], off, rd ? (unsigned)raw[off] : 0u, i32, (double)f32, CdRegion(h, c.a).c_str());
        ad.push_back(c.a);
    }
    if (ad.size() <= 40) CnPtrHints(h, f, ad);
    if (x != 0) return;
    // Fix 270 (was Fix 269 <= 600): exact flag chains from GameAssembly.dll / UnityPlayer.dll once 2000 or fewer remain, max 600 flags per run in turns; saved chains are checked in DsPress
    static size_t s_mfCnt = 0, s_mfCov = 0, s_mfRot = 0;
    static bool s_mfMore = false;
    if (e.c.empty() || e.c.size() > 2000) return;
    if (e.c.size() != s_mfCnt) { s_mfCnt = e.c.size(); s_mfCov = 0; s_mfMore = true; }
    if (!s_mfMore) { fprintf(f, "Fix 270: chain search already done for these %zu survivors (switch B/M again to narrow further)\n", e.c.size()); return; }
    fprintf(f, "Fix 270: threshold reached (%zu survivors <= 2000) -> chain search started (limits: 20 s and 20000 nodes per module)\n", e.c.size());
    s_mfMore = DsFlagSearch(h, f, e, s_mfRot, s_mfCov);
}
static void CnTrackMsg(HANDLE h, FILE* f, unsigned seq) {   // C press: which slots point at (or just before) the remembered message?
    if (g_cnTargets.empty() || g_cnTargetsSeq != seq || !seq) { fprintf(f, "message pointer tracking: no memory address for the remembered message (click a gift/egg/firework link first and wait for the 2nd beep)\n"); return; }
    std::vector<ULONG_PTR> now;
    const size_t CH = (size_t)1 << 20;
    std::vector<BYTE> buf(CH);
    MEMORY_BASIC_INFORMATION m = {};
    ULONG_PTR a = 0x10000;
    while (now.size() < 200000 && VirtualQueryEx(h, (LPCVOID)a, &m, sizeof(m)) == sizeof(m)) {
        const ULONG_PTR rb = (ULONG_PTR)m.BaseAddress, rs = m.RegionSize;
        if (DsRegionOk(m)) for (ULONG_PTR o = 0; o < rs; o += CH) {
            SIZE_T got = 0;
            if (!ReadProcessMemory(h, (LPCVOID)(rb + o), buf.data(), (size_t)std::min<ULONG_PTR>(rs - o, CH), &got)) continue;
            for (size_t i = 0; i + 8 <= got; i += 8) {
                ULONG_PTR q; memcpy(&q, &buf[i], 8);
                auto it = std::lower_bound(g_cnTargets.begin(), g_cnTargets.end(), q);
                if (it != g_cnTargets.end() && *it - q <= 0x100) now.push_back(rb + o + i);
            }
        }
        const ULONG_PTR nx = rb + rs;
        if (nx <= a) break;
        a = nx;
    }
    if (!g_cnTrackInit) { g_cnTrack = now; g_cnTrackInit = true; }
    else {
        std::vector<ULONG_PTR> r;
        std::set_intersection(g_cnTrack.begin(), g_cnTrack.end(), now.begin(), now.end(), std::back_inserter(r));
        g_cnTrack.swap(r);
    }
    fprintf(f, "message pointer tracking (message #%u): %zu slots point at it now, %zu survive all C presses\n", seq, now.size(), g_cnTrack.size());
    for (size_t k = 0; k < g_cnTrack.size() && k < 40; ++k) fprintf(f, "  0x%016llX  %s\n", (unsigned long long)g_cnTrack[k], CdRegion(h, g_cnTrack[k]).c_str());
    if (!g_cnTrack.empty() && g_cnTrack.size() <= 40) CnPtrHints(h, f, g_cnTrack);
}
static void DsPress(int x, int s, unsigned seq) {   // worker, g_cdBusy is set; read-only
    FILE* f = nullptr;
    f = _wfsopen(CdLogPath().c_str(), L"a", _SH_DENYNO); if (!f) return;   // Fix 299: shared
    DsExp& e = g_ds[x];
    const DWORD pid = GetPIDByName(L"LastWar.exe");
    if (pid != e.pid) { _wremove(DsPath(x).c_str()); e = DsExp(); e.pid = pid; if (x == 1) { g_cnTrack.clear(); g_cnTrackInit = false; } }
    ++e.presses[s];
    if (x == 0) g_dsLastState = s;   // Fix 269
    SYSTEMTIME st; GetLocalTime(&st);
    fprintf(f, "\n=== Discovery %s: %s  %02d:%02d:%02d  pid=%lu  presses %s=%d %s=%d%s\n", DS_NAME[x], DS_STATE[x][s], st.wHour, st.wMinute, st.wSecond, pid,
        DS_STATE[x][0], e.presses[0], DS_STATE[x][1], e.presses[1], x == 1 && s == 0 ? (" message #" + std::to_string(seq)).c_str() : "");
    HANDLE h = pid ? OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid) : nullptr;
    if (!h) { fprintf(f, "game not running / no access\n"); fclose(f); return; }
    const ULONGLONG t0 = GetTickCount64();
    if (!e.diffed) {
        if (e.dumpState < 0 || e.dumpState == s) {
            const unsigned long long n = DsDump(h, DsPath(x));
            e.dumpState = n ? s : -1;
            if (!n) _wremove(DsPath(x).c_str());
            fprintf(f, "baseline stored: %llu MB in %%TEMP%% (%llu ms) - now switch and press the other key\n", n >> 20, GetTickCount64() - t0);
        }
        else {
            DsDiff(h, e, s, DsPath(x));
            _wremove(DsPath(x).c_str());
            e.diffed = true; e.dumpState = -1;
            fprintf(f, "first compare done (%llu ms), temp file deleted\n", GetTickCount64() - t0);
            DsReport(h, f, e, x);
        }
    }
    else {
        DsRefine(h, e, s);
        if (x == 0) { Sleep(300); DsRefine(h, e, s); }   // Fix 269: 2nd read in the same state drops values that keep moving
        fprintf(f, "filtered (%llu ms)\n", GetTickCount64() - t0);
        DsReport(h, f, e, x);
    }
    if (x == 0) DsFlagCheck(h, f, s);   // Fix 269: saved flag chains, also after a game restart
    if (x == 1 && s == 0) CnTrackMsg(h, f, seq);
    CloseHandle(h);
    fclose(f);
}
// Fix 288: Ctrl+Alt+T/N/L/J/W trace / scan / one-shot debug code (Fix 272-285) removed; GwR/GwQ stay for the jump (GwInj286)
static bool GwR(HANDLE h, ULONG_PTR a, void* b, size_t n) { SIZE_T r = 0; return a >= 0x10000 && ReadProcessMemory(h, (LPCVOID)a, b, n, &r) && r == n; }
static ULONG_PTR GwQ(HANDLE h, ULONG_PTR a) { ULONG_PTR v = 0; return GwR(h, a, &v, 8) ? v : 0; }
// Fix 285: read Lua short/long string from remote TString*
static bool GwTStr(HANDLE h, ULONG_PTR p, char* dst, size_t dstn) {
    unsigned char ts[0x40] = {}; if (!p || !GwR(h, p, ts, sizeof(ts))) return false;
    if ((ts[8] & 0x0f) != 4) return false;
    unsigned n = (ts[8] == 0x14) ? 0u : ts[0x0B];   // Fix 317: long string (tt 0x14) -> lnglen only (same bug as Fix 316)
    if (ts[8] == 0x14 || !n) { ULONG_PTR lng = 0; memcpy(&lng, ts + 0x10, 8); if (!lng || lng >= dstn) return false; n = (unsigned)lng; }
    if (!n || n >= dstn) return false;
    return GwR(h, p + 0x18, dst, n) && ((dst[n] = 0), true);
}
// Fix 285: hash-scan one Lua table (layout B: lsizenode@0x0B node@0x18, 32-byte nodes) for string key -> TValue
static bool GwTabGet(HANDLE h, ULONG_PTR tab, const char* key, ULONG_PTR* oval, unsigned* ott) {
    unsigned char tb[0x40] = {}; if (!tab || !GwR(h, tab, tb, sizeof(tb))) return false;
    const unsigned ls = tb[0x0B]; if (ls > 14) return false;
    ULONG_PTR node = 0; memcpy(&node, tb + 0x18, 8); if (!node) return false;
    const size_t nsize = (size_t)1u << ls;
    for (size_t i = 0; i < nsize; ++i) {
        unsigned char nb[32] = {}; if (!GwR(h, node + i * 32, nb, 32)) continue;
        if ((nb[24] & 0x0f) != 4) continue;
        ULONG_PTR kptr = 0; memcpy(&kptr, nb + 16, 8);
        char ks[128] = {}; if (!GwTStr(h, kptr, ks, sizeof(ks))) continue;
        if (strcmp(ks, key) != 0) continue;
        ULONG_PTR v = 0; memcpy(&v, nb, 8);
        if (oval) *oval = v; if (ott) *ott = nb[8];
        return true;
    }
    return false;
}
static bool GwTabGetI64(HANDLE h, ULONG_PTR tab, const char* key, long long* oval) {
    ULONG_PTR v = 0; unsigned tt = 0;
    if (!oval || !GwTabGet(h, tab, key, &v, &tt) || (tt & 0x0f) != 3) return false;
    if (tt == 0x13) { *oval = (long long)v; return true; }   // LUA_TNUMINT
    double d = 0; memcpy(&d, &v, 8); *oval = (long long)d; return true;
}
// Fix 311: short ChatMessage field dump (string + number keys only)
static void MsgDumpFields311(HANDLE h, ULONG_PTR tab, const char* tag, unsigned idx, std::string& out) {
    char t[600];
    if (!tab) { snprintf(t, sizeof(t), "MSGDUMP %s[%u]: (nil)\r\n", tag, idx); out += t; return; }
    unsigned char tb[0x40] = {}; if (!GwR(h, tab, tb, sizeof(tb))) { snprintf(t, sizeof(t), "MSGDUMP %s[%u]: unread\r\n", tag, idx); out += t; return; }
    snprintf(t, sizeof(t), "MSGDUMP %s[%u] @0x%llX", tag, idx, (unsigned long long)tab); out += t;
    ULONG_PTR node = 0; memcpy(&node, tb + 0x18, 8); const unsigned ls = tb[0x0B];
    int n = 0;
    if (node && ls <= 14) {
        const size_t nsize = (size_t)1u << ls;
        for (size_t i = 0; i < nsize && n < 20; ++i) {
            unsigned char nb[32] = {}; if (!GwR(h, node + i * 32, nb, 32) || (nb[24] & 0x0f) != 4) continue;
            ULONG_PTR kptr = 0; memcpy(&kptr, nb + 16, 8);
            char ks[48] = {}; if (!GwTStr(h, kptr, ks, sizeof(ks))) continue;
            const unsigned vt = nb[8] & 0x0f; ULONG_PTR v = 0; memcpy(&v, nb, 8);
            if (vt == 4) {
                char vs[64] = {}; GwTStr(h, v, vs, sizeof(vs));
                snprintf(t, sizeof(t), " %s=\"%.40s\"", ks, vs); out += t; ++n;
            } else if (vt == 3) {
                long long iv = 0; if (nb[8] == 0x13) iv = (long long)v; else { double d = 0; memcpy(&d, &v, 8); iv = (long long)d; }
                snprintf(t, sizeof(t), " %s=%lld", ks, iv); out += t; ++n;
            } else if (vt == 1) {
                snprintf(t, sizeof(t), " %s=bool:%u", ks, (unsigned)(v & 1)); out += t; ++n;
            } else if (vt == 5) {
                snprintf(t, sizeof(t), " %s=tab", ks); out += t; ++n;
            }
        }
    }
    out += "\r\n";
}
// Fix 311: recursive search for wantSeq (number) or needle (uuid/decimal) in ChatMessage table tree
static bool MsgScanWant311(HANDLE h, ULONG_PTR tab, long long want, const char* needle, int depth, char* hitKey, size_t hitKeyN) {
    if (!tab || depth > 3) return false;
    unsigned char tb[0x40] = {}; if (!GwR(h, tab, tb, sizeof(tb))) return false;
    auto take = [&](const char* ks) { if (hitKey && hitKeyN) { snprintf(hitKey, hitKeyN, "%s", ks); } };
    ULONG_PTR node = 0; memcpy(&node, tb + 0x18, 8); const unsigned ls = tb[0x0B];
    if (node && ls <= 14) {
        const size_t nsize = (size_t)1u << ls;
        for (size_t i = 0; i < nsize; ++i) {
            unsigned char nb[32] = {}; if (!GwR(h, node + i * 32, nb, 32) || (nb[24] & 0x0f) != 4) continue;
            ULONG_PTR kptr = 0; memcpy(&kptr, nb + 16, 8);
            char ks[48] = {}; if (!GwTStr(h, kptr, ks, sizeof(ks))) continue;
            const unsigned vt = nb[8] & 0x0f; ULONG_PTR v = 0; memcpy(&v, nb, 8);
            if (vt == 3) {
                long long iv = 0; if (nb[8] == 0x13) iv = (long long)v; else { double d = 0; memcpy(&d, &v, 8); iv = (long long)d; }
                if (iv == want) { take(ks); return true; }
            } else if (vt == 4 && needle && needle[0]) {
                char vs[96] = {}; if (GwTStr(h, v, vs, sizeof(vs)) && strstr(vs, needle)) { take(ks); return true; }
            } else if (vt == 5 && MsgScanWant311(h, v, want, needle, depth + 1, hitKey, hitKeyN)) {
                return true;
            }
        }
    }
    unsigned sa = 0; ULONG_PTR arr = 0; memcpy(&arr, tb + 0x10, 8); memcpy(&sa, tb + 0x0C, 4);
    if (arr && sa && sa < 256) {
        for (unsigned k = 0; k < sa; ++k) {
            unsigned char s[16] = {}; if (!GwR(h, arr + (ULONG_PTR)k * 16, s, 16)) continue;
            const unsigned vt = s[8] & 0x0f; ULONG_PTR v = 0; memcpy(&v, s, 8);
            if (vt == 5 && MsgScanWant311(h, v, want, needle, depth + 1, hitKey, hitKeyN)) return true;
            if (vt == 3) {
                long long iv = 0; if (s[8] == 0x13) iv = (long long)v; else { double d = 0; memcpy(&d, &v, 8); iv = (long long)d; }
                if (iv == want) { take("[arr]"); return true; }
            }
        }
    }
    return false;
}
// Fix 313: long Lua string read (GwTStr refuses len >= dst size -> customJsonParam showed "" / "{" in Fix 312)
static bool GwTStrBig313(HANDLE h, ULONG_PTR p, std::string& s, size_t maxn) {
    s.clear(); unsigned char ts[0x20] = {}; if (!p || !GwR(h, p, ts, sizeof(ts))) return false;
    if ((ts[8] & 0x0f) != 4) return false;
    // Fix 316: Lua 5.3 long string (tt 0x14): shrlen @0x0B is NOT set (stale byte) -> length only from lnglen @0x10.
    // BELEGT allychat 16:51: 611 gift msgs k=39/k=56 showed cjp "{.pa" / 53 chars -> uuid not found -> no jump.
    size_t n = (ts[8] == 0x14) ? 0 : ts[0x0B];
    if (ts[8] == 0x14 || !n) { ULONG_PTR lng = 0; memcpy(&lng, ts + 0x10, 8); if (lng > 0x100000) return false; n = (size_t)lng; }
    if (!n) return true;
    if (n > maxn) n = maxn;
    s.resize(n); if (!GwR(h, p + 0x18, &s[0], n)) { s.clear(); return false; }
    return true;
}
static std::string San313(const std::string& s, size_t maxShow) {
    std::string r; r.reserve(maxShow + 2);
    for (size_t i = 0; i < s.size() && r.size() < maxShow; ++i) { unsigned char c = (unsigned char)s[i]; r += (c < 0x20 || c == '"') ? '.' : (char)c; }
    return r;
}
// one field of a msg table -> short text (number / "string" cut / tab / bool / -)
static std::string MsgFld313(HANDLE h, ULONG_PTR tab, const char* key, size_t maxShow) {
    ULONG_PTR v = 0; unsigned tt = 0; char t[64];
    if (!tab || !GwTabGet(h, tab, key, &v, &tt)) return "-";
    const unsigned vt = tt & 0x0f;
    if (vt == 3) { long long iv = 0; if (tt == 0x13) iv = (long long)v; else { double d = 0; memcpy(&d, &v, 8); iv = (long long)d; } snprintf(t, sizeof(t), "%lld", iv); return t; }
    if (vt == 4) { std::string s; GwTStrBig313(h, v, s, 4096); return "\"" + San313(s, maxShow) + "\""; }
    if (vt == 1) { snprintf(t, sizeof(t), "bool:%u", (unsigned)(v & 1)); return t; }
    if (vt == 5) return "tab";
    if (vt == 0) return "nil";
    snprintf(t, sizeof(t), "tt%02X", tt); return t;
}
// Fix 313: collect ALL paths (depth<=3) where a number == want or a string (read up to 8 KB) contains one of the needles
static void MsgScan313(HANDLE h, ULONG_PTR tab, long long want, const std::vector<std::string>& needles, int depth,
    const std::string& prefix, std::vector<std::string>& hits) {
    if (!tab || depth > 3 || hits.size() >= 16) return;
    unsigned char tb[0x40] = {}; if (!GwR(h, tab, tb, sizeof(tb))) return;
    auto test = [&](const std::string& p, unsigned char ttb, ULONG_PTR v) {
        const unsigned vt = ttb & 0x0f;
        if (vt == 3 && want) {
            long long iv = 0; if (ttb == 0x13) iv = (long long)v; else { double d = 0; memcpy(&d, &v, 8); iv = (long long)d; }
            if (iv == want) hits.push_back(p + "=" + std::to_string(iv));
        } else if (vt == 4) {
            std::string s; if (!GwTStrBig313(h, v, s, 8192)) return;
            for (const auto& nd : needles) if (!nd.empty()) {
                const size_t at = s.find(nd); if (at == std::string::npos) continue;
                const size_t b = at > 30 ? at - 30 : 0;
                hits.push_back(p + " has \"" + nd + "\" @" + std::to_string(at) + " ctx=\"" + San313(s.substr(b, 90), 90) + "\"");
            }
        } else if (vt == 5) MsgScan313(h, v, want, needles, depth + 1, p, hits);
    };
    ULONG_PTR node = 0; memcpy(&node, tb + 0x18, 8); const unsigned ls = tb[0x0B];
    if (node && ls <= 14) {
        const size_t nsize = (size_t)1u << ls;
        for (size_t i = 0; i < nsize && hits.size() < 16; ++i) {
            unsigned char nb[32] = {}; if (!GwR(h, node + i * 32, nb, 32) || (nb[24] & 0x0f) != 4) continue;
            ULONG_PTR kptr = 0; memcpy(&kptr, nb + 16, 8);
            char ks[48] = {}; if (!GwTStr(h, kptr, ks, sizeof(ks))) continue;
            ULONG_PTR v = 0; memcpy(&v, nb, 8);
            test(prefix + "." + ks, nb[8], v);
        }
    }
    unsigned sa = 0; ULONG_PTR arr = 0; memcpy(&arr, tb + 0x10, 8); memcpy(&sa, tb + 0x0C, 4);
    if (arr && sa && sa < 256) {
        for (unsigned k = 0; k < sa && hits.size() < 16; ++k) {
            unsigned char s[16] = {}; if (!GwR(h, arr + (ULONG_PTR)k * 16, s, 16)) continue;
            ULONG_PTR v = 0; memcpy(&v, s, 8);
            test(prefix + "[" + std::to_string(k + 1) + "]", s[8], v);
        }
    }
}
// Fix 313: per-hijack state counters (L->top at L+0x10, registry = G+0x40 TValue; array part non-nil count)
static void GwLuaStat313(HANDLE h, ULONG_PTR L, ULONG_PTR* otop, unsigned* oregSa, unsigned* oregUsed, unsigned* oregLs) {
    *otop = 0; *oregSa = 0; *oregUsed = 0; *oregLs = 0;
    unsigned char lh[0x20] = {}; if (!L || !GwR(h, L, lh, sizeof(lh))) return;
    memcpy(otop, lh + 0x10, 8); ULONG_PTR G = 0; memcpy(&G, lh + 0x18, 8);
    unsigned char reg[16] = {}; if (!G || !GwR(h, G + 0x40, reg, 16) || (reg[8] & 0x0f) != 5) return;
    ULONG_PTR rtab = 0; memcpy(&rtab, reg, 8);
    unsigned char rtb[0x40] = {}; if (!GwR(h, rtab, rtb, sizeof(rtb))) return;
    ULONG_PTR arr = 0; unsigned sa = 0; memcpy(&arr, rtb + 0x10, 8); memcpy(&sa, rtb + 0x0C, 4);
    *oregSa = sa; *oregLs = rtb[0x0B];
    if (!arr || !sa || sa > 1000000) return;
    std::vector<unsigned char> buf; unsigned used = 0;
    for (unsigned k0 = 0; k0 < sa; k0 += 4096) {
        const unsigned cnt = (sa - k0) < 4096 ? (sa - k0) : 4096;
        buf.assign((size_t)cnt * 16, 0); if (!GwR(h, arr + (ULONG_PTR)k0 * 16, buf.data(), buf.size())) break;
        for (unsigned i = 0; i < cnt; ++i) if ((buf[(size_t)i * 16 + 8] & 0x0f) != 0) ++used;
    }
    *oregUsed = used;
}
static const ULONG_PTR kRaxSent313 = 0x5A5A5A5A5A5A5A5Aull;
// Fix 314: DEBUG which code waits in NtWaitForSingleObject when we hijack (stack words inside remote modules,
// heuristic: data pointers into modules can appear too). Module list cached per process.
static std::string GwCallers314(HANDLE h, DWORD64 rsp) {
    struct M314 { ULONG_PTR b, e; std::string n; };
    static std::vector<M314> mods; static DWORD modPid = 0;
    const DWORD pid = GetProcessId(h);
    if (pid != modPid || mods.empty()) {
        mods.clear(); modPid = pid;
        HMODULE hm[1024]; DWORD need = 0;
        if (EnumProcessModulesEx(h, hm, sizeof(hm), &need, LIST_MODULES_64BIT))
            for (DWORD i = 0; i < need / sizeof(HMODULE) && i < 1024; ++i) {
                MODULEINFO mi = {}; char nm[64] = {};
                if (!GetModuleInformation(h, hm[i], &mi, sizeof(mi))) continue;
                GetModuleBaseNameA(h, hm[i], nm, sizeof(nm));
                mods.push_back({ (ULONG_PTR)mi.lpBaseOfDll, (ULONG_PTR)mi.lpBaseOfDll + mi.SizeOfImage, nm });
            }
    }
    ULONG_PTR st[160] = {}; SIZE_T rd = 0;
    if (!ReadProcessMemory(h, (LPCVOID)rsp, st, sizeof(st), &rd)) return "callers=? (stack read failed)";
    std::string r = "callers="; int n = 0;
    for (size_t i = 0; i < rd / 8 && n < 10; ++i) {
        const ULONG_PTR v = st[i];
        for (const auto& m : mods) if (v >= m.b + 0x1000 && v < m.e) {
            char t[112]; snprintf(t, sizeof(t), "[rsp+0x%zX]%s+0x%llX ", i * 8, m.n.c_str(), (unsigned long long)(v - m.b)); r += t; ++n; break;
        }
    }
    return r;
}
static std::string GwRipName313(DWORD64 rip) {
    const char* fn[] = { "NtWaitForSingleObject", "NtDelayExecution" };
    HMODULE hm = GetModuleHandleW(L"ntdll.dll"); char t[96];
    for (const char* f : fn) { FARPROC p = hm ? GetProcAddress(hm, f) : nullptr; if (p && rip >= (DWORD64)p && rip < (DWORD64)p + 0x20) { snprintf(t, sizeof(t), "%s+0x%llX", f, (unsigned long long)(rip - (DWORD64)p)); return t; } }
    snprintf(t, sizeof(t), "0x%llX", (unsigned long long)rip); return t;
}
// ===== Fix 315: hijack ONLY at the main-loop frame wait (freeze/crash fix) =====
// BELEGT (allychat Fix 314): every surviving hijack suspended with the return address at [rsp+0x10] ==
// UnityPlayer.dll+0x849533 (the frame loop NtWaitForSingleObject). The two Fix-314 hijacks that did NOT
// have 0x849533 there (click 10 GotoJumpMessage, click 16) were each immediately followed by the freeze /
// the AV at UnityPlayer+0x812EBB. NtWaitForSingleObject is therefore also hit inside Unity-internal
// synchronous waits; running Lua/UI from there corrupts the VM. We require the frame-loop return address.
// Fix 315b: fail-closed (no UnityPlayer base / unreadable stack -> no hijack) + stub wait min 30 s before restore.
static bool GwStackSafe315(HANDLE h, DWORD64 rsp, std::string& why) {
    static ULONG_PTR upBase = 0; static DWORD upPid = 0;
    const DWORD pid = GetProcessId(h);
    if (pid != upPid || !upBase) {
        upBase = 0; upPid = pid;
        HMODULE hm[1024]; DWORD need = 0;
        if (EnumProcessModulesEx(h, hm, sizeof(hm), &need, LIST_MODULES_64BIT))
            for (DWORD i = 0; i < need / sizeof(HMODULE) && i < 1024; ++i) {
                MODULEINFO mi = {}; char nm[64] = {};
                if (!GetModuleInformation(h, hm[i], &mi, sizeof(mi))) continue;
                GetModuleBaseNameA(h, hm[i], nm, sizeof(nm));
                if (_stricmp(nm, "UnityPlayer.dll") == 0) { upBase = (ULONG_PTR)mi.lpBaseOfDll; break; }
            }
    }
    if (!upBase) { why = "UnityPlayer base unknown -> REFUSED (Fix 315b fail-closed)"; return false; }
    ULONG_PTR w = 0;
    if (!GwR(h, (ULONG_PTR)rsp + 0x10, &w, 8)) { why = "stack read failed -> REFUSED (Fix 315b fail-closed)"; return false; }
    const ULONG_PTR want = upBase + 0x849533;
    if (w == want) return true;
    char b[128]; snprintf(b, sizeof(b), "[rsp+0x10]=0x%llX != UnityPlayer+0x849533=0x%llX (not frame-loop wait)",
        (unsigned long long)w, (unsigned long long)want);
    why = b; return false;
}
static void HijackFlush315(const char* tag, HANDLE h, DWORD64 rip, DWORD64 rsp, const char* phase, int ripOnly) {
    SYSTEMTIME st; GetLocalTime(&st);
    std::string callers = GwCallers314(h, rsp);
    char t[700];
    snprintf(t, sizeof(t), "PHASE315 click=%u tag=%s %s %02d:%02d:%02d.%03d tid=%lu ripOnly=%d rip=%s %s\r\n",
        g_clickCur313, tag ? tag : "-", phase ? phase : "-",
        st.wHour, st.wMinute, st.wSecond, st.wMilliseconds, (unsigned long)GetCurrentThreadId(),
        ripOnly, GwRipName313(rip).c_str(), callers.c_str());
    AllyLog299(std::string(t));
}
// Fix 312: recursive dump of a Lua table (extra) with key paths, depth<=3, max 40 lines
static void MsgDumpExtra312(HANDLE h, ULONG_PTR tab, const char* path, int depth, int& lines, std::string& out) {
    char t[360];
    if (!tab || depth > 3 || lines >= 40) return;
    unsigned char tb[0x40] = {}; if (!GwR(h, tab, tb, sizeof(tb))) return;
    ULONG_PTR node = 0; memcpy(&node, tb + 0x18, 8); const unsigned ls = tb[0x0B];
    if (node && ls <= 14) {
        const size_t nsize = (size_t)1u << ls;
        for (size_t i = 0; i < nsize && lines < 40; ++i) {
            unsigned char nb[32] = {}; if (!GwR(h, node + i * 32, nb, 32) || (nb[24] & 0x0f) != 4) continue;
            ULONG_PTR kptr = 0; memcpy(&kptr, nb + 16, 8);
            char ks[48] = {}; if (!GwTStr(h, kptr, ks, sizeof(ks))) continue;
            char p2[160]; snprintf(p2, sizeof(p2), "%s.%s", path, ks);
            const unsigned vt = nb[8] & 0x0f; ULONG_PTR v = 0; memcpy(&v, nb, 8);
            if (vt == 4) {
                char vs[120] = {}; GwTStr(h, v, vs, sizeof(vs));
                snprintf(t, sizeof(t), "EXTRA %s=\"%.90s\"\r\n", p2, vs); out += t; ++lines;
            } else if (vt == 3) {
                long long iv = 0; if (nb[8] == 0x13) iv = (long long)v; else { double d = 0; memcpy(&d, &v, 8); iv = (long long)d; }
                snprintf(t, sizeof(t), "EXTRA %s=%lld\r\n", p2, iv); out += t; ++lines;
            } else if (vt == 1) {
                snprintf(t, sizeof(t), "EXTRA %s=bool:%u\r\n", p2, (unsigned)(v & 1)); out += t; ++lines;
            } else if (vt == 5) {
                snprintf(t, sizeof(t), "EXTRA %s=tab\r\n", p2); out += t; ++lines;
                MsgDumpExtra312(h, v, p2, depth + 1, lines, out);
            }
        }
    }
    unsigned sa = 0; ULONG_PTR arr = 0; memcpy(&arr, tb + 0x10, 8); memcpy(&sa, tb + 0x0C, 4);
    if (arr && sa && sa < 64) {
        for (unsigned k = 0; k < sa && lines < 40; ++k) {
            unsigned char s[16] = {}; if (!GwR(h, arr + (ULONG_PTR)k * 16, s, 16)) continue;
            char p2[160]; snprintf(p2, sizeof(p2), "%s[%u]", path, k);
            const unsigned vt = s[8] & 0x0f; ULONG_PTR v = 0; memcpy(&v, s, 8);
            if (vt == 5) MsgDumpExtra312(h, v, p2, depth + 1, lines, out);
            else if (vt == 3) {
                long long iv = 0; if (s[8] == 0x13) iv = (long long)v; else { double d = 0; memcpy(&d, &v, 8); iv = (long long)d; }
                snprintf(t, sizeof(t), "EXTRA %s=%lld\r\n", p2, iv); out += t; ++lines;
            } else if (vt == 4) {
                char vs[80] = {}; GwTStr(h, v, vs, sizeof(vs));
                snprintf(t, sizeof(t), "EXTRA %s=\"%.60s\"\r\n", p2, vs); out += t; ++lines;
            }
        }
    }
}
// Fix 312: search want number/string under tab; write dotted path
static bool MsgScanPath312(HANDLE h, ULONG_PTR tab, long long want, const char* needle, int depth, char* path, size_t pathN, const char* prefix) {
    if (!tab || depth > 3) return false;
    unsigned char tb[0x40] = {}; if (!GwR(h, tab, tb, sizeof(tb))) return false;
    auto setpath = [&](const char* leaf) {
        if (!path || !pathN) return;
        if (prefix && prefix[0]) snprintf(path, pathN, "%s.%s", prefix, leaf);
        else snprintf(path, pathN, "%s", leaf);
    };
    ULONG_PTR node = 0; memcpy(&node, tb + 0x18, 8); const unsigned ls = tb[0x0B];
    if (node && ls <= 14) {
        const size_t nsize = (size_t)1u << ls;
        for (size_t i = 0; i < nsize; ++i) {
            unsigned char nb[32] = {}; if (!GwR(h, node + i * 32, nb, 32) || (nb[24] & 0x0f) != 4) continue;
            ULONG_PTR kptr = 0; memcpy(&kptr, nb + 16, 8);
            char ks[48] = {}; if (!GwTStr(h, kptr, ks, sizeof(ks))) continue;
            const unsigned vt = nb[8] & 0x0f; ULONG_PTR v = 0; memcpy(&v, nb, 8);
            if (vt == 3) {
                long long iv = 0; if (nb[8] == 0x13) iv = (long long)v; else { double d = 0; memcpy(&d, &v, 8); iv = (long long)d; }
                if (want != 0 && iv == want) { setpath(ks); return true; }
            } else if (vt == 4 && needle && needle[0]) {
                char vs[120] = {}; if (GwTStr(h, v, vs, sizeof(vs)) && strstr(vs, needle)) { setpath(ks); return true; }
            } else if (vt == 5) {
                char pref[160];
                if (prefix && prefix[0]) snprintf(pref, sizeof(pref), "%s.%s", prefix, ks);
                else snprintf(pref, sizeof(pref), "%s", ks);
                if (MsgScanPath312(h, v, want, needle, depth + 1, path, pathN, pref)) return true;
            }
        }
    }
    return false;
}

// Fix 285: resolve ChangeToWorld LClosure from registry[2]=_G -> SceneUtils -> ChangeToWorld
static bool GwResolveCtw(HANDLE h, ULONG_PTR G, ULONG_PTR* ocl, ULONG_PTR* oproto, std::string& note) {
    char t[240];
    unsigned char reg[16] = {}; if (!GwR(h, G + 0x40, reg, 16) || (reg[8] & 0x0f) != 5) { note = "registry not table"; return false; }
    ULONG_PTR rtab = 0; memcpy(&rtab, reg, 8);
    unsigned char rtb[0x40] = {}; if (!GwR(h, rtab, rtb, sizeof(rtb))) { note = "registry table unread"; return false; }
    ULONG_PTR arr = 0; memcpy(&arr, rtb + 0x10, 8);  // array ptr (packed layout)
    unsigned sa = 0; memcpy(&sa, rtb + 0x0C, 4);
    if (!arr || sa < 2) { memcpy(&arr, rtb + 0x18, 8); memcpy(&sa, rtb + 0x14, 4); }
    if (!arr || sa < 2) { note = "registry array missing"; return false; }
    unsigned char slot[16] = {}; if (!GwR(h, arr + 16, slot, 16) || (slot[8] & 0x0f) != 5) { note = "_G slot bad"; return false; }
    ULONG_PTR _G = 0; memcpy(&_G, slot, 8);
    ULONG_PTR su = 0; unsigned su_tt = 0;
    if (!GwTabGet(h, _G, "SceneUtils", &su, &su_tt) || (su_tt & 0x0f) != 5) { note = "SceneUtils missing"; return false; }
    ULONG_PTR cl = 0; unsigned cl_tt = 0;
    if (!GwTabGet(h, su, "ChangeToWorld", &cl, &cl_tt)) { note = "ChangeToWorld missing"; return false; }
    unsigned char cb[0x20] = {}; if (!GwR(h, cl, cb, sizeof(cb)) || cb[8] != 6) { note = "closure tt!=6"; return false; }
    ULONG_PTR proto = 0; memcpy(&proto, cb + 0x18, 8);
    if (!proto) { note = "proto null"; return false; }
    snprintf(t, sizeof(t), "_G=0x%llX SceneUtils=0x%llX cl=0x%llX tt=%u proto=0x%llX", (unsigned long long)_G, (unsigned long long)su, (unsigned long long)cl, (unsigned)cb[8], (unsigned long long)proto); note = t;
    if (ocl) *ocl = cl; if (oproto) *oproto = proto;
    return true;
}
// Fix 286: resolve JumpToWorldPoint from package.loaded["Util.GoToUtil"] (fallback _G.GoToUtil)
static bool GwResolveJtw(HANDLE h, ULONG_PTR G, ULONG_PTR* ocl, ULONG_PTR* oproto, std::string& note) {
    char t[280];
    unsigned char reg[16] = {}; if (!GwR(h, G + 0x40, reg, 16) || (reg[8] & 0x0f) != 5) { note = "registry not table"; return false; }
    ULONG_PTR rtab = 0; memcpy(&rtab, reg, 8);
    unsigned char rtb[0x40] = {}; if (!GwR(h, rtab, rtb, sizeof(rtb))) { note = "registry table unread"; return false; }
    ULONG_PTR arr = 0; memcpy(&arr, rtb + 0x10, 8);
    unsigned sa = 0; memcpy(&sa, rtb + 0x0C, 4);
    if (!arr || sa < 2) { memcpy(&arr, rtb + 0x18, 8); memcpy(&sa, rtb + 0x14, 4); }
    if (!arr || sa < 2) { note = "registry array missing"; return false; }
    unsigned char slot[16] = {}; if (!GwR(h, arr + 16, slot, 16) || (slot[8] & 0x0f) != 5) { note = "_G slot bad"; return false; }
    ULONG_PTR _G = 0; memcpy(&_G, slot, 8);
    ULONG_PTR go = 0; unsigned go_tt = 0;
    const char* how = "package.loaded";
    ULONG_PTR pkg = 0; unsigned pkg_tt = 0;
    if (GwTabGet(h, _G, "package", &pkg, &pkg_tt) && (pkg_tt & 0x0f) == 5) {
        ULONG_PTR loaded = 0; unsigned ld_tt = 0;
        if (GwTabGet(h, pkg, "loaded", &loaded, &ld_tt) && (ld_tt & 0x0f) == 5)
            GwTabGet(h, loaded, "Util.GoToUtil", &go, &go_tt);
    }
    if (!go || (go_tt & 0x0f) != 5) {
        how = "_G.GoToUtil";
        if (!GwTabGet(h, _G, "GoToUtil", &go, &go_tt) || (go_tt & 0x0f) != 5) { note = "GoToUtil missing"; return false; }
    }
    ULONG_PTR cl = 0; unsigned cl_tt = 0;
    if (!GwTabGet(h, go, "JumpToWorldPoint", &cl, &cl_tt)) { note = "JumpToWorldPoint missing"; return false; }
    unsigned char cb[0x20] = {}; if (!GwR(h, cl, cb, sizeof(cb)) || cb[8] != 6) { note = "JTW closure tt!=6"; return false; }
    ULONG_PTR proto = 0; memcpy(&proto, cb + 0x18, 8);
    if (!proto) { note = "JTW proto null"; return false; }
    unsigned char pb[0x20] = {}; if (!GwR(h, proto, pb, sizeof(pb)) || pb[0x18] != 5) {
        snprintf(t, sizeof(t), "JTW numparams!=5 (got %u)", (unsigned)pb[0x18]); note = t; return false;
    }
    snprintf(t, sizeof(t), "_G=0x%llX via %s go=0x%llX cl=0x%llX proto=0x%llX np=5",
        (unsigned long long)_G, how, (unsigned long long)go, (unsigned long long)cl, (unsigned long long)proto);
    note = t;
    if (ocl) *ocl = cl; if (oproto) *oproto = proto;
    return true;
}
// Fix 286: WorldTileCount from _G for pointId = y*WTC + x + 1
static bool GwWorldTileCount(HANDLE h, ULONG_PTR G, long long* out) {
    unsigned char reg[16] = {}; if (!GwR(h, G + 0x40, reg, 16) || (reg[8] & 0x0f) != 5) return false;
    ULONG_PTR rtab = 0; memcpy(&rtab, reg, 8);
    unsigned char rtb[0x40] = {}; if (!GwR(h, rtab, rtb, sizeof(rtb))) return false;
    ULONG_PTR arr = 0; memcpy(&arr, rtb + 0x10, 8);
    unsigned sa = 0; memcpy(&sa, rtb + 0x0C, 4);
    if (!arr || sa < 2) { memcpy(&arr, rtb + 0x18, 8); memcpy(&sa, rtb + 0x14, 4); }
    if (!arr || sa < 2) return false;
    unsigned char slot[16] = {}; if (!GwR(h, arr + 16, slot, 16) || (slot[8] & 0x0f) != 5) return false;
    ULONG_PTR _G = 0; memcpy(&_G, slot, 8);
    ULONG_PTR v = 0; unsigned tt = 0;
    if (!GwTabGet(h, _G, "WorldTileCount", &v, &tt)) return false;
    if ((tt & 0x0f) != 3) return false;
    if (out) *out = (long long)v;
    return out && *out > 0 && *out < 100000;
}
