// Resolve GoToUtil.OpenChatView (same package.loaded path as JumpToWorldPoint)
static bool GwResolveOcv294(HANDLE h, ULONG_PTR G, ULONG_PTR* ocl, ULONG_PTR* oproto, std::string& note) {
    char t[280];
    unsigned char reg[16] = {}; if (!GwR(h, G + 0x40, reg, 16) || (reg[8] & 0x0f) != 5) { note = "registry not table"; return false; }
    ULONG_PTR rtab = 0; memcpy(&rtab, reg, 8);
    unsigned char rtb[0x40] = {}; if (!GwR(h, rtab, rtb, sizeof(rtb))) { note = "registry table unread"; return false; }
    ULONG_PTR arr = 0; unsigned sa = 0; memcpy(&arr, rtb + 0x10, 8); memcpy(&sa, rtb + 0x0C, 4);
    if (!arr || sa < 2) { memcpy(&arr, rtb + 0x18, 8); memcpy(&sa, rtb + 0x14, 4); }
    if (!arr || sa < 2) { note = "registry array missing"; return false; }
    unsigned char slot[16] = {}; if (!GwR(h, arr + 16, slot, 16) || (slot[8] & 0x0f) != 5) { note = "_G slot bad"; return false; }
    ULONG_PTR _G = 0; memcpy(&_G, slot, 8);
    ULONG_PTR go = 0; unsigned go_tt = 0; const char* how = "package.loaded";
    ULONG_PTR pkg = 0, loaded = 0; unsigned pkg_tt = 0, ld_tt = 0;
    if (GwTabGet(h, _G, "package", &pkg, &pkg_tt) && (pkg_tt & 0x0f) == 5 && GwTabGet(h, pkg, "loaded", &loaded, &ld_tt) && (ld_tt & 0x0f) == 5)
        GwTabGet(h, loaded, "Util.GoToUtil", &go, &go_tt);
    if (!go || (go_tt & 0x0f) != 5) {
        how = "_G.GoToUtil";
        if (!GwTabGet(h, _G, "GoToUtil", &go, &go_tt) || (go_tt & 0x0f) != 5) { note = "GoToUtil missing"; return false; }
    }
    ULONG_PTR cl = 0; unsigned cl_tt = 0;
    if (!GwTabGet(h, go, "OpenChatView", &cl, &cl_tt) || cl_tt != 0x46) { note = "OpenChatView missing"; return false; }
    unsigned char cb[0x20] = {}; if (!GwR(h, cl, cb, sizeof(cb)) || cb[8] != 6) { note = "OCV closure tt!=6"; return false; }
    ULONG_PTR proto = 0; memcpy(&proto, cb + 0x18, 8);
    if (!proto) { note = "OCV proto null"; return false; }
    snprintf(t, sizeof(t), "_G=0x%llX via %s go=0x%llX ocv=0x%llX proto=0x%llX",
        (unsigned long long)_G, how, (unsigned long long)go, (unsigned long long)cl, (unsigned long long)proto);
    note = t; if (ocl) *ocl = cl; if (oproto) *oproto = proto; return true;
}
// Resolve ChatManager2.Instance.Room.GotoJumpMessage + Room table pointer (self for the method call)
static bool GwResolveGjm294(HANDLE h, ULONG_PTR G, ULONG_PTR* ocl, ULONG_PTR* oproto, ULONG_PTR* oroom, std::string& note) {
    char t[320];
    unsigned char reg[16] = {}; if (!GwR(h, G + 0x40, reg, 16) || (reg[8] & 0x0f) != 5) { note = "registry not table"; return false; }
    ULONG_PTR rtab = 0; memcpy(&rtab, reg, 8);
    unsigned char rtb[0x40] = {}; if (!GwR(h, rtab, rtb, sizeof(rtb))) { note = "registry table unread"; return false; }
    ULONG_PTR arr = 0; unsigned sa = 0; memcpy(&arr, rtb + 0x10, 8); memcpy(&sa, rtb + 0x0C, 4);
    if (!arr || sa < 2) { memcpy(&arr, rtb + 0x18, 8); memcpy(&sa, rtb + 0x14, 4); }
    if (!arr || sa < 2) { note = "registry array missing"; return false; }
    unsigned char slot[16] = {}; if (!GwR(h, arr + 16, slot, 16) || (slot[8] & 0x0f) != 5) { note = "_G slot bad"; return false; }
    ULONG_PTR _G = 0; memcpy(&_G, slot, 8);
    ULONG_PTR cm = 0; unsigned cm_tt = 0;
    if (!GwTabGet(h, _G, "ChatManager2", &cm, &cm_tt) || (cm_tt & 0x0f) != 5) {
        ULONG_PTR pkg = 0, loaded = 0; unsigned pt = 0, lt = 0;
        if (!(GwTabGet(h, _G, "package", &pkg, &pt) && (pt & 0x0f) == 5 && GwTabGet(h, pkg, "loaded", &loaded, &lt) && (lt & 0x0f) == 5
            && GwTabGet(h, loaded, "Chat.ChatManager2", &cm, &cm_tt) && (cm_tt & 0x0f) == 5)) {
            note = "ChatManager2 missing"; return false;
        }
    }
    ULONG_PTR inst = 0; unsigned inst_tt = 0;
    if (!GwTabGet(h, cm, "Instance", &inst, &inst_tt) || (inst_tt & 0x0f) != 5) { note = "ChatManager2.Instance missing"; return false; }
    ULONG_PTR room = 0; unsigned room_tt = 0;
    if (!GwTabGet(h, inst, "Room", &room, &room_tt) || (room_tt & 0x0f) != 5) { note = "Instance.Room missing"; return false; }
    ULONG_PTR cl = 0; unsigned cl_tt = 0;
    if (!GwTabGet(h, room, "GotoJumpMessage", &cl, &cl_tt) || cl_tt != 0x46) { note = "GotoJumpMessage missing"; return false; }
    unsigned char cb[0x20] = {}; if (!GwR(h, cl, cb, sizeof(cb)) || cb[8] != 6) { note = "GJM closure tt!=6"; return false; }
    ULONG_PTR proto = 0; memcpy(&proto, cb + 0x18, 8);
    if (!proto) { note = "GJM proto null"; return false; }
    snprintf(t, sizeof(t), "CM=0x%llX Inst=0x%llX Room=0x%llX gjm=0x%llX proto=0x%llX",
        (unsigned long long)cm, (unsigned long long)inst, (unsigned long long)room, (unsigned long long)cl, (unsigned long long)proto);
    note = t; if (ocl) *ocl = cl; if (oproto) *oproto = proto; if (oroom) *oroom = room; return true;
}
// Plant a long Lua TString (tt=4, shrlen=0, marked FIXED) for roomId into page+0x800; returns remote TString*
static ULONG_PTR GwPlantRoomStr294(unsigned char* page, ULONG_PTR remBase, const std::string& room) {
    if (room.empty() || room.size() >= 90) return 0;
    unsigned char* ts = page + 0x800;
    memset(ts, 0, 0x80);
    ts[8] = 4;            // LUA_TSTRING
    ts[9] = 0x20;         // marked FIXEDBIT (do not collect)
    ts[0x0B] = 0;         // shrlen=0 => long string
    size_t n = room.size();
    memcpy(ts + 0x10, &n, 8);   // lnglen
    memcpy(ts + 0x18, room.data(), n);
    ts[0x18 + n] = 0;
    return remBase + 0x800;
}
static void ChatInj294(DWORD pid, const std::string& room, long long seq, bool doJump) {
    SYSTEMTIME st; GetLocalTime(&st);
    char t[900]; std::string out;
    snprintf(t, sizeof(t), "=== Fix 296 ChatOpen (world only, no jump) doJump=%d room=%s seq=%lld  %04d-%02d-%02d %02d:%02d:%02d.%03d pid=%lu ===\r\n",
        (int)doJump, room.empty() ? "-" : room.c_str(), (long long)seq,
        st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute, st.wSecond, st.wMilliseconds, (unsigned long)pid);
    out += t;
    (void)kChatSelRoom294;   // reserved OFF
    static ULONGLONG g_lastChat294 = 0;
    const ULONGLONG nowg = GetTickCount64();
    if (g_lastChat294 && nowg - g_lastChat294 < 1200) {
        const DWORD waitMs = (DWORD)(1200 - (nowg - g_lastChat294));
        for (DWORD waited = 0; waited < waitMs; waited += 50) { if (g_chatJobPend294.load() || (g_camPend.load() & (1ull << 63))) break; Sleep(50); }
        out += "rate-limit gap applied\r\n";
    }
    g_lastChat294 = GetTickCount64();
    HANDLE h = pid ? OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid) : nullptr;
    if (!h) { out += "ABORT: OpenProcess failed\r\n"; CdLogLine(out.c_str()); return; }
    // Resolve xlua/G/L + reusable page (same cache as coord jump)
    bool needResolve = (g_gw286.pid != pid) || !g_gw286.L || !g_gw286.page;
    if (!needResolve) {
        unsigned char lv[0x20];
        if (!(GwR(h, g_gw286.L, lv, sizeof(lv)) && lv[8] == 8 && *(ULONG_PTR*)(lv + 0x18) == g_gw286.G && LiveOk363(pid, h, g_gw286.G))) {   // FIX363
            needResolve = true; out += "cache invalid -> re-resolve\r\n";
        } else out += "cache hit\r\n";
    }
    if (needResolve) {
        ULONG_PTR xb = 0;
        { HMODULE mods[1024]; DWORD need = 0; if (EnumProcessModulesEx(h, mods, sizeof(mods), &need, LIST_MODULES_64BIT)) for (DWORD i = 0; i < need / sizeof(HMODULE) && i < 1024; ++i) { wchar_t nm[MAX_PATH]; if (GetModuleBaseNameW(h, mods[i], nm, MAX_PATH) && _wcsicmp(nm, L"xlua.dll") == 0) xb = (ULONG_PTR)mods[i]; } }
        ULONG_PTR G = 0, L = 0;
        if (xb) Pick363(pid, h, xb, G, L, out);   // FIX363: live state (skips stale states after account switch)
        if (xb && kOldScan363) {
            const ULONG_PTR fr = xb + 0x3298;
            MEMORY_BASIC_INFORMATION mb; std::vector<unsigned char> buf;
            for (ULONG_PTR a = 0x10000; !L && VirtualQueryEx(h, (LPCVOID)a, &mb, sizeof(mb)) == sizeof(mb); ) {
                const ULONG_PTR base = (ULONG_PTR)mb.BaseAddress, sz = mb.RegionSize;
                if (mb.State == MEM_COMMIT && mb.Type == MEM_PRIVATE && (mb.Protect & PAGE_READWRITE) && sz < 0x10000000) {
                    for (ULONG_PTR off = 0; off < sz && !L; off += 0x100000) {
                        const size_t n = (size_t)std::min<ULONG_PTR>(0x100000, sz - off);
                        buf.resize(n);
                        if (!GwR(h, base + off, buf.data(), n)) continue;
                        for (size_t i = 0; i + 8 <= n; i += 8) {
                            if (*(ULONG_PTR*)&buf[i] != fr) continue;
                            const ULONG_PTR g = base + off + i, l = GwQ(h, g + 0x100);
                            unsigned char lh[0x20];
                            if (GwR(h, l, lh, sizeof(lh)) && lh[8] == 8 && *(ULONG_PTR*)(lh + 0x18) == g) { G = g; L = l; break; }
                        }
                    }
                }
                const ULONG_PTR nx = base + sz; if (nx <= a || nx > 0x7FFFFFFFFFFFull) break; a = nx;
            }
        }
        snprintf(t, sizeof(t), "xlua=0x%llX G=0x%llX L=0x%llX\r\n", (unsigned long long)xb, (unsigned long long)G, (unsigned long long)L); out += t;
        if (!xb || !L) { out += "ABORT: xlua/L not found\r\n"; CloseHandle(h); CdLogLine(out.c_str()); return; }
        ULONG_PTR rpage = (g_gw286.pid == pid) ? g_gw286.page : 0;
        if (!rpage) {
            LPVOID remoteNew = VirtualAllocEx(h, nullptr, 0x2000, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
            if (!remoteNew) { out += "ABORT: VirtualAllocEx failed\r\n"; CloseHandle(h); CdLogLine(out.c_str()); return; }
            rpage = (ULONG_PTR)remoteNew;
        }
        // Keep CTW/JTW fields if same pid; otherwise clear (coord jump will re-resolve)
        if (g_gw286.pid != pid) memset(&g_gw286, 0, sizeof(g_gw286));
        g_gw286.pid = pid; g_gw286.xb = xb; g_gw286.G = G; g_gw286.L = L; g_gw286.page = rpage;
        out += "resolved + reusable page cached\r\n";
    }
    const ULONG_PTR xb = g_gw286.xb, G = g_gw286.G, L = g_gw286.L, remBase = g_gw286.page;
    if (!LiveOk363(pid, h, G)) {   // FIX363 hard guard: never write into a dead Lua state
        snprintf(t, sizeof(t), "FIX363 abort: Lua state not live (G=0x%llX)\r\n", (unsigned long long)G); out += t; AllyLog299(Clk339() + " " + t);
        CloseHandle(h); CdLogLine(out.c_str()); return;
    }
    const ULONG_PTR a_pcallk = xb + 0x28BC, a_settop = xb + 0x1BB0, a_gettop = xb + 0x2BF4, a_type = xb + 0x2CD0;
    HWND gw = FindLastWarWindow();
    DWORD wp = 0; DWORD mainTid = gw ? GetWindowThreadProcessId(gw, &wp) : 0;
    if (!mainTid || wp != pid) { out += "ABORT: main thread\r\n"; CloseHandle(h); CdLogLine(out.c_str()); return; }

    auto runChatStub = [&](ULONG_PTR cl, ULONG_PTR proto, unsigned nargs, const ULONG_PTR* av, const unsigned* att, ULONGLONG maxMs, const char* tag) -> bool {
        unsigned char page[0x2000]; memset(page, 0xCC, sizeof(page));
        GwInjSh294* sh = (GwInjSh294*)(page + 0x400);
        memset(sh, 0, sizeof(*sh));
        sh->L = L; sh->fn_pcallk = a_pcallk; sh->fn_settop = a_settop; sh->fn_gettop = a_gettop; sh->fn_type = a_type;
        sh->cl_addr = cl; sh->cl_proto = proto; sh->nargs = nargs; sh->skip_chk = 0;
        sh->done = 0; sh->pcall_rc = -999; sh->err_type = -1; sh->stage = 0;
        for (unsigned i = 0; i < nargs && i < 4; ++i) { sh->args[i].v = av[i]; sh->args[i].tt = att[i]; }
        GwEmitStub294(page, remBase + 0x400);
        // roomId long string lives at page+0x800 when av points there; already written by caller into page before emit? 
        // Caller plants into a side buffer; we accept planted bytes via extra memcpy below if remBase+0x800 was prepared in `page`.
        SIZE_T w2 = 0;
        if (!WriteProcessMemory(h, (LPVOID)remBase, page, 0x2000, &w2) || w2 != 0x2000) { snprintf(t, sizeof(t), "%s: ABORT WPM failed\r\n", tag); out += t; return false; }
        HANDLE th = OpenThread(THREAD_SUSPEND_RESUME | THREAD_GET_CONTEXT | THREAD_SET_CONTEXT | THREAD_QUERY_INFORMATION, FALSE, mainTid);
        if (!th) { snprintf(t, sizeof(t), "%s: ABORT OpenThread failed\r\n", tag); out += t; return false; }
        CONTEXT ctx = {}, ctxOrig = {};
        bool safe = false; int tries = 0; int ripOnly315 = 0; const ULONGLONG ts0 = GetTickCount64(); Tp323 tp323;   // Fix 323
                SafeHijackLock328 _hijackLock328;  // Fix 328: serialize vs poller install
for (;;) {
            ctx.ContextFlags = CONTEXT_FULL;
            if (SuspendThread(th) == (DWORD)-1) { CloseHandle(th); snprintf(t, sizeof(t), "%s: ABORT SuspendThread failed\r\n", tag); out += t; return false; }
            if (!GetThreadContext(th, &ctx)) { ResumeThread(th); CloseHandle(th); snprintf(t, sizeof(t), "%s: ABORT GetThreadContext failed\r\n", tag); out += t; return false; }
            ++tries;
            if (GwRipSafe(ctx.Rip)) { std::string w315; if (GwStackSafe315(h, ctx.Rsp, w315)) { safe = true; break; } if (!ripOnly315) HijackFlush315("hijack", h, ctx.Rip, ctx.Rsp, (std::string("UNSAFE315 ") + w315).c_str(), ripOnly315); ++ripOnly315; }
            ResumeThread(th);
            if (GetTickCount64() - ts0 > 30000) break;   // Fix 325: chat SAFE search up to 30 s (newer click breaks it), same SAFE rule
            if (g_chatJobPend294.load() || (g_camPend.load() & (1ull << 63))) break;   // Fix 325: newest click wins
            GwSpinUs325(250);   // Fix 325: 0.25 ms sampling (was Sleep(1))
        }
        snprintf(t, sizeof(t), "FIX323 %s: SAFE %s after %llu ms, tries=%d (Fix 325: 0.25 ms sampling, max 30 s)\r\n", tag, safe ? "found" : "NOT found", (unsigned long long)(GetTickCount64() - ts0), tries); out += t;
        if (!safe) { CloseHandle(th); snprintf(t, sizeof(t), "%s: ABORT no safe hijack point in 30s or newer click (tries=%d lastRIP=0x%llX)\r\n", tag, tries, (unsigned long long)ctx.Rip); out += t; return false; }
        ctxOrig = ctx;
        snprintf(t, sizeof(t), "%s: suspended at SAFE RIP=0x%llX (tries=%d) nargs=%u\r\n", tag, (unsigned long long)ctx.Rip, tries, nargs); out += t;
        ctx.Rip = (DWORD64)remBase;
        if (!SetThreadContext(th, &ctx)) { SetThreadContext(th, &ctxOrig); ResumeThread(th); CloseHandle(th); snprintf(t, sizeof(t), "%s: ABORT SetThreadContext failed\r\n", tag); out += t; return false; }
        ResumeThread(th);
        unsigned done = 0; int prc = -999, et = -1; bool crashed = false, timedOut = false;
        const ULONGLONG t0 = GetTickCount64();
        for (;;) {
            if (GetTickCount64() - t0 > (maxMs > 30000ull ? maxMs : 30000ull)) { timedOut = true; break; }   // Fix 315b: min 30 s, restore only after done
            DWORD ec = 0;
            if (!GetExitCodeProcess(h, &ec) || ec != STILL_ACTIVE) { crashed = true; break; }
            unsigned char hb[0x20];
            if (GwR(h, remBase + 0x400 + 0x40, hb, 0x10)) { done = *(unsigned*)hb; prc = *(int*)(hb + 4); et = *(int*)(hb + 8); }
            if (done) break;
            Sleep(5);
        }
        if (!crashed) { ctxOrig.Rax = 0; SuspendThread(th); SetThreadContext(th, &ctxOrig); ResumeThread(th); }
        CloseHandle(th);
        { unsigned char hb[0x10]; if (GwR(h, remBase + 0x400 + 0x40, hb, 0x10)) { done = *(unsigned*)hb; prc = *(int*)(hb + 4); et = *(int*)(hb + 8); } }
        snprintf(t, sizeof(t), "%s: done=%u pcall_rc=%d err_type=%d timedOut=%d crashed=%d waitMs=%llu\r\n",
            tag, done, prc, et, (int)timedOut, (int)crashed, (unsigned long long)(GetTickCount64() - t0)); out += t;
        char ebuf[256] = {}; GwR(h, remBase + 0x400 + 0x90, ebuf, 255);
        if (ebuf[0]) { snprintf(t, sizeof(t), "%s: err_buf=\"%.200s\"\r\n", tag, ebuf); out += t; }
        return done && !crashed && !timedOut && prc == 0;
    };

    // Step 1: OpenChatView(false)
    ULONG_PTR ocv = 0, ocvP = 0; std::string note;
    if (!GwResolveOcv294(h, G, &ocv, &ocvP, note)) {
        snprintf(t, sizeof(t), "ABORT: resolve OpenChatView failed (%s)\r\n", note.c_str()); out += t;
        CloseHandle(h); CdLogLine(out.c_str()); return;
    }
    snprintf(t, sizeof(t), "OCV %s\r\n", note.c_str()); out += t;
    ULONG_PTR av1[1] = { 0 }; unsigned at1[1] = { 0x01 };   // boolean false
    const bool okOpen = runChatStub(ocv, ocvP, 1, av1, at1, 3000, "openchat");
    if (!okOpen) { out += "RESULT: OpenChatView failed\r\n"; CloseHandle(h); CdLogLine(out.c_str()); return; }
    // Fix 296: stop here. Fix 294 GJM resolve failed; Fix 295 options-table stub crashed (wrong xlua offs / Panic).
    // OpenChatView(false) alone is the only proven stable chat call (opens WORLD chat).
    (void)doJump; (void)room; (void)seq; (void)kChatSelRoom296;
    out += "RESULT: OpenChatView(false) OK - WORLD chat only (Fix 296; alliance/msg jump deferred)\r\n";
    CloseHandle(h);
    CdLogLine(out.c_str());
}


// ===== Fix 298 (based on Fix 295 stub): ALLIANCE chat OpenChatView(false, {roomId,seqId,jumpSeqId,immediately,anim}) =====
// Fix 295 panic cause (exact): xb+0x2244 is lua_GETfield (index2value -> jmp auxgetstr 0x10A0, pushes a value), NOT
// lua_setfield. The stub therefore pushed nils instead of storing fields and the next call indexed a nil OUTSIDE pcall
// -> "unprotected error in call to Lua API (attempt to index a nil value)". Real lua_setfield = xb+0x25F8
