        sh->doJump = 4; sh->fn_val = fn; sh->fn_tt = fn_tt; sh->nargs = nargs;
        for (unsigned i = 0; i < nargs; ++i) { sh->args[i].v = args[i].v; sh->args[i].tt = args[i].tt; }
        sh->done = 0; sh->pcall_rc = -999; sh->err_type = -1; sh->stage = 0; sh->res_val = 0; sh->res_tt = 0;
