    if (!chunkRem) chunkRem = (ULONG_PTR)VirtualAllocEx(h, nullptr, 0x10000, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (!rem || !chunkRem) { F364Log("install: VirtualAllocEx failed"); return false; }
