// FIX374: periodic READ ONLY got-table check of reported, not yet collected fireworks (dig/drone worker thread, every 2 s).
// Uses try_lock on the firework worker mutex: while a Finder firework collect runs, its own Fix 372 check decides.
static void F374FwTick(HANDLE h, ULONG_PTR gT) {
    static ULONGLONG s_next = 0; static std::string s_lastWhy; const ULONGLONG now = GetTickCount64();
    if (now < s_next) return; s_next = now + 2000ull;
    std::unordered_set<std::string> c;
    {
        std::lock_guard<std::mutex> lk(g_fwCandMx374);
        for (auto it = g_fwCand374.begin(); it != g_fwCand374.end();) { if (now - it->second > 3ull * 3600000ull) it = g_fwCand374.erase(it); else { c.insert(it->first); ++it; } }
    }
    if (c.empty()) return;
    std::unique_lock<std::mutex> lk(g_mx345, std::try_to_lock);
    if (!lk.owns_lock()) return;
    std::string how; const ULONG_PTR mgr = Mgr347(h, gT, how);
    ULONG_PTR t = 0; unsigned tt = 0; std::vector<TE344> es;
    std::string why;
    if (!mgr) why = "LWFireworkGiftManager not found (" + how + ")";
    else if (!GwTabGet(h, mgr, "giftUuid2TimeTable", &t, &tt) || (tt & 0x0f) != 5 || !TRead344(h, t, es, 0, nullptr)) why = "giftUuid2TimeTable unreadable";
    else if (es.size() > 4000) why = "giftUuid2TimeTable too big (" + std::to_string(es.size()) + ")";
    if (!why.empty()) { if (why != s_lastWhy) { s_lastWhy = why; AllyLog299(Clk339() + " FIX374 firework got-table check skipped: " + why + " (" + std::to_string(c.size()) + " candidates)\r\n"); } return; }
    if (!s_lastWhy.empty() || F365RL("f374fw", 300000)) { s_lastWhy.clear(); AllyLog299(Clk339() + " FIX374 firework got-table check running: " + std::to_string(c.size()) + " reported, not collected firework(s), got table has " + std::to_string(es.size()) + " entries (every 2 s, READ ONLY)\r\n"); }
    KC344 kc; std::vector<std::string> hit;
    for (const auto& e : es) {
        if ((e.kt & 0x0f) != 4 || (e.vt & 0x0f) == 0) continue;
        const std::string k = KStr344(h, e.k, kc);
        if (c.count(k)) hit.push_back(k);
    }
    lk.unlock();
    for (const auto& u : hit) {
        AllyLog299(Clk339() + " FIX374 firework uuid=" + u + " is in the game's got table (giftUuid2TimeTable) without a Finder collect -> collected by you in the game\r\n");
        Fw372Mark(u, "FIX374 self-collected: uuid in the game's got table");
    }
}
