static std::string Md5Hex359(const std::string& s) {
    std::string out; HCRYPTPROV pv = 0; HCRYPTHASH hh = 0;
    if (!CryptAcquireContextW(&pv, nullptr, nullptr, PROV_RSA_FULL, CRYPT_VERIFYCONTEXT)) return out;
    if (CryptCreateHash(pv, CALG_MD5, 0, 0, &hh)) {
        BYTE d[16] = {}; DWORD n = 16;
        if (CryptHashData(hh, (const BYTE*)s.data(), (DWORD)s.size(), 0) && CryptGetHashParam(hh, HP_HASHVAL, d, &n, 0) && n == 16) {
            char b[33] = {}; for (int i = 0; i < 16; ++i) snprintf(b + i * 2, 3, "%02x", (unsigned)d[i]); out = b;
        }
        CryptDestroyHash(hh);
    }
    CryptReleaseContext(pv, 0); return out;
}
