// FIX362: read-only Lua state search that skips stale states (account switch leaves the old lua_State in memory with a valid header):
// collects ALL frealloc matches (like Poll326ResolveBase) and picks the one whose _G has LuaEntry.Player with a uid (best), else _G readable.
static ULONG_PTR Resolve362(HANDLE h, ULONG_PTR avoid, std::string& info) {
    ULONG_PTR xb = 0;
    { HMODULE mods[1024]; DWORD need = 0; if (EnumProcessModulesEx(h, mods, sizeof(mods), &need, LIST_MODULES_64BIT)) for (DWORD i = 0; i < need / sizeof(HMODULE) && i < 1024; ++i) { wchar_t nm[MAX_PATH]; if (GetModuleBaseNameW(h, mods[i], nm, MAX_PATH) && _wcsicmp(nm, L"xlua.dll") == 0) xb = (ULONG_PTR)mods[i]; } }
    if (!xb) { info = "xlua.dll not loaded"; return 0; }
    const ULONG_PTR fr = xb + 0x3298;
    std::vector<ULONG_PTR> cands; MEMORY_BASIC_INFORMATION mbi; std::vector<unsigned char> buf;
    for (ULONG_PTR a = 0x10000; cands.size() < 16 && VirtualQueryEx(h, (LPCVOID)a, &mbi, sizeof(mbi)) == sizeof(mbi); ) {
        const ULONG_PTR base = (ULONG_PTR)mbi.BaseAddress, sz = mbi.RegionSize;
        if (mbi.State == MEM_COMMIT && mbi.Type == MEM_PRIVATE && (mbi.Protect & PAGE_READWRITE) && sz < 0x10000000) {
            for (ULONG_PTR off = 0; off < sz && cands.size() < 16; off += 0x100000) {
                const size_t n = (size_t)std::min<ULONG_PTR>(0x100000, sz - off);
                buf.resize(n); if (!GwR(h, base + off, buf.data(), n)) continue;
                for (size_t i = 0; i + 8 <= n && cands.size() < 16; i += 8) {
                    if (*(ULONG_PTR*)&buf[i] != fr) continue;
                    const ULONG_PTR g = base + off + i, l = GwQ(h, g + 0x100);
                    unsigned char lh[0x20];
                    if (l && GwR(h, l, lh, sizeof(lh)) && lh[8] == 8 && *(ULONG_PTR*)(lh + 0x18) == g) cands.push_back(g);
                }
            }
        }
        const ULONG_PTR nx = base + sz; if (nx <= a || nx > 0x7FFFFFFFFFFFull) break; a = nx;
    }
    ULONG_PTR best = 0; int bestSc = 0; char t[96];
    info = std::to_string(cands.size()) + " cand:";
    for (const ULONG_PTR g : cands) {
        int sc = 0; ULONG_PTR gT = 0; std::string u;
        if (GwGetG303(h, g, &gT) && gT) {
            sc = 1;
            const ULONG_PTR dc = Tab359(h, gT, "DataCenter");
            ULONG_PTR le = Tab359(h, gT, "LuaEntry"); if (!le) le = Tab359(h, Tab359(h, dc, "Global"), "LuaEntry");
            const ULONG_PTR pl = Tab359(h, le, "Player");
            if (pl) { sc = 2; if (Str359(h, pl, "uid", u) && !u.empty()) sc = 3; }
        }
        if (sc > 0 && g != avoid) sc += 0;   // same score: a non-stale address wins below
        snprintf(t, sizeof(t), " 0x%llX=%d%s", (unsigned long long)g, sc, u.empty() ? "" : ("/" + u).c_str()); info += t;
        if (sc > bestSc || (sc == bestSc && sc > 0 && best == avoid)) { best = g; bestSc = sc; }
    }
    return bestSc > 0 ? best : 0;
}
