static ULONG_PTR OtherPd380(HANDLE h, ULONG_PTR dc, const std::string& uid) { return uid.empty() ? 0 : Tab359(h, Tab359(h, Tab359(h, dc, "PlayerInfoDataManager"), "otherPlayerData"), uid.c_str()); }
static unsigned long long Hash380(HANDLE h, ULONG_PTR t, unsigned long long x) {   // depth-1 scalars without time-like keys
    std::vector<TE344> es; KC344 kc; if (!t || !TRead344(h, t, es, 64, nullptr)) return x;
    std::vector<std::string> v;
    for (const auto& e : es) {
        const unsigned vt = e.vt & 0x0f; if (vt == 5 || vt == 6 || vt == 0) continue;
        const std::string k = Key344(h, e, kc); const std::string lk = Lc380(k);
        if (Has380(lk, { "time", "tick", "stamp", "online", "_et", "endt" })) continue;
        v.push_back(k + "=" + (vt == 4 ? SVal380(h, e, 200) : Val359(h, e)));
    }
    std::sort(v.begin(), v.end());
    for (const auto& s : v) for (unsigned char ch : s) { x ^= ch; x *= 1099511628211ull; }
    return x;
}
