    auto N = [&](const char* k, long long v) { S(k, std::to_string(v)); };
    S("uid", p.uid); S("name", p.name); S("tag", p.tag); S("nation", p.nation); S("countryFlag", p.flag);
    N("lv", p.lv); N("gender", p.gender); N("serverId", p.server); N("svip", p.svip); N("showVip", p.showVip); N("vip", p.vip);
    N("power", p.power); S("powerKey", p.kPower); N("heroPower", p.heroP); N("armyPower", p.armyP); N("buildingPower", p.buildP); N("sciencePower", p.sciP); N("squadEquipPower", p.squadP);
    N("armyKill", p.kills); N("careerLv", p.careerLv); N("careerType", p.careerType); S("careerKey", p.kCareer); N("giftLevel", p.giftLv);
    N("thumbsUpCount", p.likes); N("thumbsUpCountOld", p.likesOld);
    S("allianceName", p.alName); S("allianceId", p.alId); S("birthday", p.birthday); N("title", p.titleId); S("titleName", p.titleName); N("srvUpdate", p.srvUpd);
    N("vipLevel382", p.vipLv382); S("allianceIcon", p.alIcon382); N("serverBadge", p.sbId382); S("serverBadgeIcon", p.sbIcon382); S("titleIcon", p.titleIcon382);   // FIX382
    S("album", p.album382); S("gifts", p.gifts382); S("giftIcons", p.giftIc382);
    N("momentCount", (long long)p.moments382.size()); for (size_t i = 0; i < p.moments382.size() && i < 200; ++i) S(("moment" + std::to_string(i)).c_str(), p.moments382[i]);
    if (withMeta) N("updated", p.updated);
    return o;
