    N("lv", p.lv); N("gender", p.gender); N("serverId", p.server); N("svip", p.svip); N("showVip", p.showVip); N("vip", p.vip);
    N("power", p.power); S("powerKey", p.kPower); N("heroPower", p.heroP); N("armyPower", p.armyP); N("buildingPower", p.buildP); N("sciencePower", p.sciP); N("squadEquipPower", p.squadP);
