    for (const auto& r : rooms) body += "ROOM " + r.first + " msgs=" + std::to_string(cnt[r.first]) + "\n  " + r.second + "\n" + msgs[r.first] + "\n";
    for (const auto& m : msgs) if (!rooms.count(m.first)) body += "ROOM(no table) " + m.first + " msgs=" + std::to_string(cnt[m.first]) + "\n" + m.second + "\n";
