// ===== FIX396B: lucky gift / egg collected state from RAM (every 3 s, all chat rooms, also while the chat window is closed) =====
// A message whose extra.customJsonParam has a uuid and hasRob == true -> PostLuckyMine(uuid) once (same UI path as Fix 114: green check + counter).
// UNPROVEN: hasRob is read as "collected by this account" (field seen on lucky gift post 611 customJsonParam).
static void Lucky396(HANDLE h, ULONG_PTR gT, const std::string& uid) {
    static ULONGLONG s_next = 0, s_log = 0; const ULONGLONG now = GetTickCount64(); if (now < s_next) return; s_next = now + 3000ull;
    static std::string s_uid; static std::unordered_set<unsigned long long> s_skip; static std::unordered_map<unsigned long long, std::string> s_cand; static std::unordered_set<std::string> s_done; static bool s_first = true;
    if (uid != s_uid) { s_uid = uid; s_skip.clear(); s_cand.clear(); s_done.clear(); s_first = true; }
    if (s_skip.size() > 60000) s_skip.clear(); if (s_cand.size() > 5000) s_cand.clear();
    const ULONG_PTR cm = Tab359(h, gT, "ChatManager2"), inst = Tab359(h, cm, "Instance"), rm = Tab359(h, inst, "Room"), rd = Tab359(h, rm, "roomDatas");
    if (!rd) return;
    std::vector<TE344> res; if (!TRead344(h, rd, res, 0, nullptr)) return;
    int nNew = 0, nCand = 0, nMark = 0, nRooms = 0; const ULONGLONG t0 = GetTickCount64();
    for (const auto& e : res) {
        if ((e.vt & 0x0f) != 5) continue; std::string id;
        if (!Str359(h, e.v, "roomId", id) || id.find("moment") != std::string::npos || Pre395(id, "battlefield_") || Pre395(id, "friends_circle")) continue;
        const ULONG_PTR mm = Tab359(h, e.v, "_msgMap"); if (!mm) continue;
        std::vector<TE344> ms; if (!TRead344(h, mm, ms, 4096, nullptr)) continue; ++nRooms;
        for (const auto& m : ms) {
            if ((m.vt & 0x0f) != 5) continue;
            const unsigned long long key = (unsigned long long)m.v * 31ull + (unsigned long long)m.ik;
            if (s_skip.count(key)) continue;
            auto ci = s_cand.find(key); std::string uu;
            const ULONG_PTR cj = Tab359(h, Tab359(h, m.v, "extra"), "customJsonParam");
            ULONG_PTR v = 0; unsigned tt = 0;
            if (ci == s_cand.end()) {
                ++nNew;
                if (!cj || !GwTabGet(h, cj, "uuid", &v, &tt) || (tt & 0x0f) != 4 || !GwTStrBig313(h, v, uu, 80) || uu.empty() || s_done.count(uu)) { s_skip.insert(key); continue; }
                ci = s_cand.emplace(key, uu).first;
            } else uu = ci->second;
            ++nCand;
            const bool rob = cj && GwTabGet(h, cj, "hasRob", &v, &tt) && (tt == 0x11 || (tt == 0x01 && (v & 0xFFFFFFFFull)));
            if (!rob) continue;
            const long long post = Num359(h, m.v, { "post" }, nullptr);
            s_done.insert(uu); s_cand.erase(ci); s_skip.insert(key); ++nMark;
            AllyLog299(Clk339() + " FIX396B collected (RAM): uuid=" + uu + " room=" + id + " post=" + std::to_string(post) + " extra.customJsonParam.hasRob=true -> PostLuckyMine (green check + counter, also when the Finder was closed at collection time) (UNPROVEN: hasRob = own collect)\r\n");
            PostLuckyMine(uu);
        }
    }
    if (s_first || nMark || now - s_log > 300000ull) {
        s_first = false; s_log = now;
        AllyLog299(Clk339() + " FIX396B scan: rooms=" + std::to_string(nRooms) + " newMsgs=" + std::to_string(nNew) + " uuidCandidates=" + std::to_string(nCand) + " markedNow=" + std::to_string(nMark) + " markedTotal=" + std::to_string(s_done.size()) + " ms=" + std::to_string(GetTickCount64() - t0) + "\r\n");
    }
}
