static ULONG_PTR MsgIdStr396(HANDLE h, ULONG_PTR G, ULONG_PTR gT, const char* want, std::string& how) {   // live TString (like MsgId347, any name)
    const size_t wl = strlen(want);
    ULONG_PTR md = 0; unsigned mt = 0;
    if (GwTabGet(h, gT, "MsgDefines", &md, &mt) && (mt & 0x0f) == 5) {
        std::vector<TE344> es; if (TRead344(h, md, es, 4096, nullptr)) for (const auto& e : es) if ((e.vt & 0x0f) == 4 && StrIs347(h, e.v, want)) { how = "MsgDefines"; return e.v; }
    }
    const ULONG_PTR hash = GwQ(h, G + 0x30); unsigned size = 0, seed = 0;
    if (!hash || !GwR(h, G + 0x3C, &size, 4) || !size || (size & (size - 1)) || size > (1u << 24) || !GwR(h, G + 0x50, &seed, 4)) { how = "strt unreadable"; return 0; }
    const unsigned hv = Hash347(want, wl, seed);
    ULONG_PTR ts = GwQ(h, hash + (ULONG_PTR)(hv & (size - 1)) * 8);
    for (int n = 0; ts && n < 64; ts = GwQ(h, ts + 0x10), ++n) if (StrIs347(h, ts, want)) { how = "strt"; return ts; }
    std::vector<ULONG_PTR> bk; const unsigned CH = 65536;
    for (unsigned i = 0; i < size; i += CH) {
        const unsigned m = std::min(CH, size - i); bk.resize(m);
        if (!GwR(h, hash + (ULONG_PTR)i * 8, bk.data(), (size_t)m * 8)) continue;
        for (unsigned j = 0; j < m; ++j) for (ULONG_PTR s = bk[j]; s; ) {
            unsigned char hd[0x18]; if (!GwR(h, s, hd, sizeof(hd))) break;
            if (hd[8] == 0x04 && hd[0x0B] == wl && StrIs347(h, s, want)) { how = "strt scan"; return s; }
            memcpy(&s, hd + 0x10, 8);
        }
    }
    how = "not found"; return 0;
}
struct HelpCnt396 { int all = -1, others = 0; std::string field, sig; };
static HelpCnt396 HelpCount396(HANDLE h, ULONG_PTR mgr, const std::string& uid, KC344& kc, std::string* probe) {   // entries with helpId (deduped); others = uid != own uid
    HelpCnt396 r; if (!mgr) return r; r.all = 0;
    std::vector<TE344> es; if (!TRead344(h, mgr, es, 64, nullptr)) return r;
    if (probe) *probe = Scal394(h, mgr, es, kc, 60);
    std::set<std::string> ids;
    for (const auto& e : es) {
        if ((e.vt & 0x0f) != 5) continue;
        const std::string k = (e.kt & 0x0f) == 4 ? KStr344(h, e.k, kc) : "[" + std::to_string(e.ik) + "]";
        if (k.compare(0, 6, "_class") == 0 || k == "super" || k == "__index") continue;
        std::vector<TE344> ls; if (!TRead344(h, e.v, ls, 256, nullptr) || ls.empty() || ls.size() > 400) continue;
        int got = 0;
        for (const auto& l : ls) {
            if ((l.vt & 0x0f) != 5) continue; std::string hid, u;
            if (!Str359(h, l.v, "helpId", hid) || hid.empty()) continue;
            ++got; if (!ids.insert(hid).second) continue;
            ++r.all; if (!Str359(h, l.v, "uid", u)) { const long long n = Num359(h, l.v, { "uid" }, nullptr); if (n > 0) u = std::to_string(n); }
            if (u != uid) { ++r.others; if (r.sig.size() < 400) r.sig += hid.substr(0, 10) + ","; }
        }
        if (got && r.field.size() < 200) r.field += (r.field.empty() ? "" : "+") + k + "(" + std::to_string(got) + ")";
    }
    return r;
}
