static long long NoticeGameRead468(const std::string& uid) {   // FIX468: game AL_Notice_Read_time = "{allianceUuid}|{timeMs}" under HKCU FunFly prefs
    if (!kFix468NoticeBadge || uid.empty()) return -1;
    HKEY hk = nullptr;
    if (RegOpenKeyExW(HKEY_CURRENT_USER, L"Software\\FunFly\\Last War-Survival Game", 0, KEY_READ, &hk) != ERROR_SUCCESS) return -1;
    const std::string pref = uid + "AL_Notice_Read_time";
    long long best = -1;
    for (DWORD idx = 0;; ++idx) {
        char nameA[512]; BYTE data[512]; DWORD nlen = (DWORD)sizeof(nameA), dlen = (DWORD)sizeof(data), type = 0;
        const LONG rc = RegEnumValueA(hk, idx, nameA, &nlen, nullptr, &type, data, &dlen);
        if (rc == ERROR_NO_MORE_ITEMS) break;
        if (rc != ERROR_SUCCESS) { if (rc == ERROR_MORE_DATA) continue; break; }
        if (strncmp(nameA, pref.c_str(), pref.size()) != 0) continue;
        if (type != REG_BINARY && type != REG_SZ) continue;
        size_t n = (size_t)dlen; while (n && data[n - 1] == 0) --n;
        std::string v((const char*)data, (const char*)data + n);
        const size_t bar = v.find('|'); if (bar == std::string::npos || bar + 1 >= v.size()) continue;
        const long long t = _strtoi64(v.c_str() + bar + 1, nullptr, 10);
        if (t > best) best = t;
    }
    RegCloseKey(hk);
    return best;
}
static bool NoticeGameWrite470(const std::string& uid, long long timeMs) {   // FIX470: write game AL_Notice_Read_time so Ankuendigung red dot clears
    if (!kFix470ReadSync || !kFix468NoticeBadge || uid.empty() || timeMs <= 0) return false;
    HKEY hk = nullptr;
    if (RegOpenKeyExW(HKEY_CURRENT_USER, L"Software\\FunFly\\Last War-Survival Game", 0, KEY_READ | KEY_SET_VALUE, &hk) != ERROR_SUCCESS) return false;
    const std::string pref = uid + "AL_Notice_Read_time";
    char nameA[512]; BYTE data[512]; DWORD nlen = 0, dlen = 0, type = 0;
    std::string bestName; std::string bestUuid; long long bestT = -1;
    for (DWORD idx = 0;; ++idx) {
        nlen = (DWORD)sizeof(nameA); dlen = (DWORD)sizeof(data); type = 0;
        const LONG rc = RegEnumValueA(hk, idx, nameA, &nlen, nullptr, &type, data, &dlen);
        if (rc == ERROR_NO_MORE_ITEMS) break;
        if (rc != ERROR_SUCCESS) { if (rc == ERROR_MORE_DATA) continue; break; }
        if (strncmp(nameA, pref.c_str(), pref.size()) != 0) continue;
        if (type != REG_BINARY && type != REG_SZ) continue;
        size_t n = (size_t)dlen; while (n && data[n - 1] == 0) --n;
        std::string v((const char*)data, (const char*)data + n);
        const size_t bar = v.find('|'); if (bar == std::string::npos || bar + 1 >= v.size()) continue;
        const long long t = _strtoi64(v.c_str() + bar + 1, nullptr, 10);
        if (t >= bestT) { bestT = t; bestName.assign(nameA); bestUuid = v.substr(0, bar); }
    }
    if (bestName.empty() || bestUuid.empty()) { RegCloseKey(hk); Log395("FIX470 notice write SKIP no existing AL_Notice_Read_time for uid"); return false; }
    if (timeMs <= bestT) { RegCloseKey(hk); Log395("FIX470 notice write skip already gameRead=" + std::to_string(bestT) + " >= " + std::to_string(timeMs)); return false; }
    const std::string body = bestUuid + "|" + std::to_string(timeMs);
    const LONG wr = RegSetValueExA(hk, bestName.c_str(), 0, REG_BINARY, (const BYTE*)body.data(), (DWORD)body.size());
    RegCloseKey(hk);
    Log395(std::string("FIX470 notice write ") + (wr == ERROR_SUCCESS ? "OK" : "FAIL") + " name=" + bestName + " " + body + " old=" + std::to_string(bestT));
    return wr == ERROR_SUCCESS;
}
