static void Lines520(HDC dc, const Tr520& t, std::vector<int>& starts) {   // FIX521: GDI word-wrap line starts (profile fonts are private GDI faces)
    starts.clear(); starts.push_back(0);
    const int n = (int)t.s.size(); if (n <= 0) return;
    if (!t.wrap) { starts.push_back(n); return; }
    const int maxW = ((int)(t.r.right - t.r.left) > 1) ? (int)(t.r.right - t.r.left) : 1;
    int i = 0;
    while (i < n) {
        int fit = 0; SIZE s2 = {};
        GetTextExtentExPointW(dc, t.s.c_str() + i, n - i, maxW, &fit, nullptr, &s2);
        if (fit <= 0) fit = 1;
        int br = fit;
        if (i + fit < n) { for (int k = fit; k >= 1; --k) { const wchar_t c = t.s[(size_t)(i + k - 1)]; if (c == L' ' || c == L'\t' || c == L'\n' || c == L'-') { br = k; break; } } }
        i += br; if (i > n) i = n; starts.push_back(i);
        if (br <= 0) break;
    }
    if (starts.back() != n) starts.push_back(n);
}
static int Pos520(const Tr520& t, POINT pt) {   // FIX521: GDI hit-test (Dw396Lay returns null for Gemunu/Saira -> FIX520 never selected)
    if (!kFix521ProfSelGdi) return 0;
    HDC dc = GetDC(nullptr); if (!dc) return 0;
    HFONT f = CreateFontIndirectW(&t.lf); if (!f) { ReleaseDC(nullptr, dc); return 0; }
    HGDIOBJ o = SelectObject(dc, f);
    int x0 = 0, y0 = 0, lineH = 1; SIZE full = {}; Origin520(dc, t, x0, y0, lineH, full);
    int out = 0;
    if (!t.wrap) {
        int fit = 0; SIZE sz = {};
        const int maxExt = (pt.x > x0) ? (pt.x - x0) : 0;
        GetTextExtentExPointW(dc, t.s.c_str(), (int)t.s.size(), maxExt, &fit, nullptr, &sz);
        out = std::max(0, std::min((int)t.s.size(), fit));
    } else {
        std::vector<int> starts; Lines520(dc, t, starts);
        int line = (pt.y < y0) ? 0 : (pt.y - y0) / lineH;
        if (starts.size() < 2) out = 0;
        else {
            if (line < 0) line = 0;
            if (line >= (int)starts.size() - 1) out = (int)t.s.size();
            else {
                const int a = starts[(size_t)line], b = starts[(size_t)line + 1];
                int fit = 0; SIZE sz = {};
                const int maxExt2 = (pt.x > t.r.left) ? (pt.x - t.r.left) : 0;
                GetTextExtentExPointW(dc, t.s.c_str() + a, b - a, maxExt2, &fit, nullptr, &sz);
                out = std::max(a, std::min(b, a + fit));
            }
        }
    }
    SelectObject(dc, o); DeleteObject(f); ReleaseDC(nullptr, dc);
    return out;
}
static void DrawSel520(HDC dc, const Tr520& t) {   // FIX521: GDI selection highlight
    if (!kFix521ProfSelGdi || t.key != g_selKey520 || g_selA520 == g_selB520 || t.s.empty()) return;
    HFONT f = CreateFontIndirectW(&t.lf); if (!f) return;
    HGDIOBJ o = SelectObject(dc, f);
    const int a0 = std::min(g_selA520, g_selB520), b0 = std::max(g_selA520, g_selB520);
    int x0 = 0, y0 = 0, lineH = 1; SIZE full = {}; Origin520(dc, t, x0, y0, lineH, full);
    HBRUSH sb = CreateSolidBrush(RGB(38, 86, 160));
    if (!t.wrap) {
        SIZE sa = {}, sbx = {};
        GetTextExtentPoint32W(dc, t.s.c_str(), a0, &sa);
        GetTextExtentPoint32W(dc, t.s.c_str(), b0, &sbx);
        RECT q = { x0 + sa.cx, y0, x0 + sbx.cx, y0 + lineH };
        if (q.right > q.left) FillRect(dc, &q, sb);
    } else {
        std::vector<int> starts; Lines520(dc, t, starts);
        for (size_t li = 0; li + 1 < starts.size(); ++li) {
            const int ls = starts[li], le = starts[li + 1];
            const int a = std::max(a0, ls), b = std::min(b0, le);
            if (b <= a) continue;
            SIZE sa = {}, sbx = {};
            GetTextExtentPoint32W(dc, t.s.c_str() + ls, a - ls, &sa);
            GetTextExtentPoint32W(dc, t.s.c_str() + ls, b - ls, &sbx);
            RECT q = { t.r.left + sa.cx, y0 + (int)li * lineH, t.r.left + sbx.cx, y0 + (int)li * lineH + lineH };
            if (q.right > q.left) FillRect(dc, &q, sb);
        }
    }
    DeleteObject(sb); SelectObject(dc, o); DeleteObject(f);
}
