    {
        std::lock_guard<std::mutex> lk(g_mxCdn505);
        if (g_cdnBusy505.count(key)) return false;
        for (const auto& q : g_cdnQ506) if (q.key == key) return false;
        const auto it = g_cdnRetry505.find(key);
        if (it != g_cdnRetry505.end() && now < it->second) return false;
        if (g_cdnRetry505.size() >= 4096) {
            for (auto i = g_cdnRetry505.begin(); i != g_cdnRetry505.end();) {
                if (now >= i->second) i = g_cdnRetry505.erase(i); else ++i;
            }
            if (g_cdnRetry505.size() >= 4096) return false;
        }
        if (!kFix506Photo) {
            if (g_cdnBusy505.size() >= 4) return false;
            g_cdnBusy505.insert(key);
            g_cdnRetry505[key] = now + 60000ull;
            direct = CdnJob506{ key, url, dst, big };
            startDirect = true;
        } else {
            g_cdnQ506.push_back(CdnJob506{ key, url, dst, big });
            if (g_cdnQ506.size() > 512) g_cdnQ506.pop_front();
        }
    }
    if (startDirect) CdnStartJob506(direct);
