static void FinderCascade510(HWND main, bool show) {   // FIX510: minimize / restore all related Finder windows together
    if (!kFix510Photo) return;
    auto addUniq = [](std::vector<HWND>& v, HWND w) {
        if (!w || !IsWindow(w)) return;
        for (HWND x : v) if (x == w) return;
        v.push_back(w);
    };
    if (!show) {
        if (!main || !IsWindow(main)) return;
        std::vector<HWND> cand;
        const HWND cw = g_chat395.load();
        if (cw && IsWindow(cw) && IsWindowVisible(cw)) addUniq(cand, cw);
        if (g_pop380 && IsWindow(g_pop380) && IsWindowVisible(g_pop380)) addUniq(cand, g_pop380);
        if (g_pvWnd507 && IsWindow(g_pvWnd507) && IsWindowVisible(g_pvWnd507)) addUniq(cand, g_pvWnd507);
        if (g_pvHwnd506 && IsWindow(g_pvHwnd506) && IsWindowVisible(g_pvHwnd506)) addUniq(cand, g_pvHwnd506);
        EnumMin510 ctx = { main, &cand };
        EnumThreadWindows(GetCurrentThreadId(), EnumOwned510Proc, (LPARAM)&ctx);
        for (HWND w : cand) { addUniq(g_minPop510, w); ShowWindow(w, SW_HIDE); }
        g_minHid510 = true;
        if (!cand.empty()) AllyLog299(Clk339() + " FIX510 minimize cascade: hid " + std::to_string(cand.size()) + " related window(s)\r\n");
    } else {
        std::vector<HWND> list; list.swap(g_minPop510); g_minHid510 = false;
        const HWND cw = g_chat395.load();
        if (cw && IsWindow(cw) && !IsWindowVisible(cw)) addUniq(list, cw);
        if (g_pop380 && IsWindow(g_pop380) && !IsWindowVisible(g_pop380)) addUniq(list, g_pop380);
        if (g_pvWnd507 && IsWindow(g_pvWnd507) && !IsWindowVisible(g_pvWnd507)) addUniq(list, g_pvWnd507);
        int n = 0;
        for (HWND w : list) if (w && IsWindow(w)) { ShowWindow(w, SW_SHOWNOACTIVATE); ++n; }
        if (n > 0) {
            Dock406("finder restored", true, true);
            ChromeFocus494();
            AllyLog299(Clk339() + " FIX510 restore cascade: shown " + std::to_string(n) + " related window(s)\r\n");
        }
    }
}
