static void PhotoBlit420(HDC dc, const std::wstring& path, int x, int y, int s) {   // FIX420: drop near-black letterbox, then cover-fill the bubble
    if (path.empty() || s <= 0) return;
    const std::wstring key = path + L"@" + std::to_wstring(s) + L"c";
    auto it = g_bm395.find(key);
    Gdiplus::Bitmap* cached = (it != g_bm395.end()) ? it->second : nullptr;
    if (!cached) {
        if (!FileOk359(path)) return;
        Gdiplus::Bitmap* src = Gdiplus::Bitmap::FromFile(path.c_str());
        if (!src || src->GetLastStatus() != Gdiplus::Ok) { delete src; return; }
        const int w = (int)src->GetWidth(), h = (int)src->GetHeight();
        int x0 = 0, y0 = 0, cw = w, ch = h;
        Gdiplus::BitmapData bd; Gdiplus::Rect rr(0, 0, w, h);
        if (w > 8 && h > 8 && src->LockBits(&rr, Gdiplus::ImageLockModeRead, PixelFormat32bppARGB, &bd) == Gdiplus::Ok) {
            auto darkRow = [&](int yy) -> bool {
                const BYTE* p = (const BYTE*)bd.Scan0 + yy * bd.Stride; int n = 0, dk = 0;
                for (int xx = 0; xx < w; xx += (w > 40 ? w / 40 : 1)) { ++n; const BYTE* q = p + xx * 4; if (q[0] < 18 && q[1] < 18 && q[2] < 18) ++dk; }
                return n > 0 && dk * 10 >= n * 8;
            };
            auto darkCol = [&](int xx) -> bool {
                int n = 0, dk = 0;
                for (int yy = 0; yy < h; yy += (h > 40 ? h / 40 : 1)) { ++n; const BYTE* q = (const BYTE*)bd.Scan0 + yy * bd.Stride + xx * 4; if (q[0] < 18 && q[1] < 18 && q[2] < 18) ++dk; }
                return n > 0 && dk * 10 >= n * 8;
            };
            int t = 0, btm = h, l = 0, rgt = w;
            while (t < h / 3 && darkRow(t)) ++t;
            while (btm > (h * 2) / 3 && darkRow(btm - 1)) --btm;
            while (l < w / 3 && darkCol(l)) ++l;
            while (rgt > (w * 2) / 3 && darkCol(rgt - 1)) --rgt;
            if (btm - t >= h / 5 && rgt - l >= w / 5) { x0 = l; y0 = t; cw = rgt - l; ch = btm - t; }
            src->UnlockBits(&bd);
        }
        cached = new Gdiplus::Bitmap(s, s, PixelFormat32bppPARGB);
        { Gdiplus::Graphics g(cached); g.Clear(Gdiplus::Color(255, 12, 12, 14));
          g.SetInterpolationMode(Gdiplus::InterpolationModeHighQualityBicubic); g.SetPixelOffsetMode(Gdiplus::PixelOffsetModeHalf);
          const float sc = (std::max)((float)s / (float)cw, (float)s / (float)ch);
          const int dw = (int)(cw * sc + 0.5f), dh = (int)(ch * sc + 0.5f);
          g.DrawImage(src, Gdiplus::Rect((s - dw) / 2, (s - dh) / 2, dw, dh), x0, y0, cw, ch, Gdiplus::UnitPixel); }
        delete src;
        if (!kCacheTrim408 && g_bm395.size() > 600) { for (auto& kv : g_bm395) delete kv.second; g_bm395.clear(); }
        g_bm395[key] = cached;
    }
    if (cached) Blt395(dc, cached, x, y, s);
}
