static void Nine410(HDC dc, Gdiplus::Bitmap* b, int x, int y, int w, int h, int L, int T, int R, int B) {   // Unity-style 9-slice; border 0 = stretch
    if (!b || w <= 0 || h <= 0) return;
    const int sw = (int)b->GetWidth(), sh = (int)b->GetHeight();
    if (L <= 0 && T <= 0 && R <= 0 && B <= 0) { Stretch410(dc, b, x, y, w, h); return; }
    if (L + R >= sw || T + B >= sh || L + R >= w || T + B >= h) { Stretch410(dc, b, x, y, w, h); return; }
    Gdiplus::Graphics g(dc); g.SetPixelOffsetMode(Gdiplus::PixelOffsetModeHalf);
    auto blit = [&](int dx, int dy, int dw, int dh, int sx, int sy, int sww, int shh) {
        if (dw > 0 && dh > 0 && sww > 0 && shh > 0) g.DrawImage(b, Gdiplus::Rect(dx, dy, dw, dh), sx, sy, sww, shh, Gdiplus::UnitPixel);
    };
    const int midW = w - L - R, midH = h - T - B, smW = sw - L - R, smH = sh - T - B;
    blit(x, y, L, T, 0, 0, L, T); blit(x + L, y, midW, T, L, 0, smW, T); blit(x + L + midW, y, R, T, L + smW, 0, R, T);
    blit(x, y + T, L, midH, 0, T, L, smH); blit(x + L, y + T, midW, midH, L, T, smW, smH); blit(x + L + midW, y + T, R, midH, L + smW, T, R, smH);
    blit(x, y + T + midH, L, B, 0, T + smH, L, B); blit(x + L, y + T + midH, midW, B, L, T + smH, smW, B); blit(x + L + midW, y + T + midH, R, B, L + smW, T + smH, R, B);
}
