static bool g_pvMoved507 = false, g_pvHot507 = false, g_pvXDn507 = false, g_pvLive507 = false;   // FIX513: g_pvUserSized507 hoisted early
static double Pv507Ar() { if (g_pv397 && g_pv397->GetWidth() > 0 && g_pv397->GetHeight() > 0) return (double)g_pv397->GetWidth() / (double)g_pv397->GetHeight(); return 4.0 / 3.0; }
static void Pv507Fit(HWND hw, int iw, int ih) {
    if (!hw || !IsWindow(hw)) return;
    if (iw <= 0 || ih <= 0) { iw = 640; ih = 480; }
    const double ar = (double)iw / (double)ih;
    RECT cur = {}; GetWindowRect(hw, &cur);
    if (g_pvUserSized507 && cur.right > cur.left) {   // user already sized it: keep position + width, only follow the image aspect
        const int w = cur.right - cur.left, h = std::max(1, (int)(w / ar + 0.5));
        SetWindowPos(hw, nullptr, cur.left, cur.top, w, h, SWP_NOZORDER | SWP_NOACTIVATE);
        return;
    }
    MONITORINFO mi = { sizeof(mi) }; GetMonitorInfoW(MonitorFromWindow(hw, MONITOR_DEFAULTTONEAREST), &mi);
    const RECT& wa = mi.rcWork;
    const double maxW = (wa.right - wa.left) * 0.8, maxH = (wa.bottom - wa.top) * 0.8, minL = (double)UIS(360), lg = (double)std::max(iw, ih);
    double sc = 1.0;
    if (iw > maxW || ih > maxH) sc = std::min(maxW / iw, maxH / ih);
    else if (lg < minL) sc = std::min(minL / lg, std::min(maxW / iw, maxH / ih));
    const int w = std::max(1, (int)(iw * sc + 0.5)), h = std::max(1, (int)(ih * sc + 0.5));
    int x = wa.left + ((wa.right - wa.left) - w) / 2, y = wa.top + ((wa.bottom - wa.top) - h) / 2;
    if (g_pvMoved507 && cur.right > cur.left) { x = cur.left; y = cur.top; }   // moved by the user: keep the top-left corner
    SetWindowPos(hw, nullptr, x, y, w, h, SWP_NOZORDER | SWP_NOACTIVATE);
}
static void Pv507Aspect(WPARAM edge, RECT* r) {   // WM_SIZING: window == client (no frame) -> keep width/height == image width/height
    const double ar = Pv507Ar(); const int mn = UIS(64);
    int w = r->right - r->left, h = r->bottom - r->top;
    const bool horiz = edge == WMSZ_LEFT || edge == WMSZ_RIGHT, vert = edge == WMSZ_TOP || edge == WMSZ_BOTTOM;
    if (horiz) h = (int)(w / ar + 0.5);
    else if (vert) w = (int)(h * ar + 0.5);
    else { if ((double)w >= h * ar) h = (int)(w / ar + 0.5); else w = (int)(h * ar + 0.5); }
    if (w < mn) { w = mn; h = (int)(w / ar + 0.5); }
    if (h < mn) { h = mn; w = (int)(h * ar + 0.5); }
    const bool left = edge == WMSZ_LEFT || edge == WMSZ_TOPLEFT || edge == WMSZ_BOTTOMLEFT;
    const bool top = edge == WMSZ_TOP || edge == WMSZ_TOPLEFT || edge == WMSZ_TOPRIGHT;
    if (left) r->left = r->right - w; else r->right = r->left + w;
    if (top) r->top = r->bottom - h; else r->bottom = r->top + h;
}
