static bool Pv508BigPending(const std::string& key) { std::lock_guard<std::mutex> lk(g_mxCdn505); if (g_cdnBusy505.count(key)) return true; for (const auto& q : g_cdnQ506) if (q.key == key) return true; return false; }
static void Pv508SaveAs(HWND owner, const std::string& uid, long long pv, const std::wstring& path) {
    const bool hasId = !uid.empty() && pv > 0; std::wstring src;
    if (hasId) {
        src = PhotoCdn506Big(uid, pv, false);
        if (src.empty()) src = Pv508BigOf(ChatPhoto382(uid, pv));
        if (src.empty()) {   // not downloaded yet: fetch _big now (same CDN / cache path) and wait a moment
            PhotoCdn506Big(uid, pv, true); const std::string key = uid + "_" + std::to_string(pv) + "_big"; const ULONGLONG t0 = GetTickCount64();
            HCURSOR oc = SetCursor(LoadCursorW(nullptr, IDC_WAIT));
            while (GetTickCount64() - t0 < 8000ull) { src = PhotoCdn506Big(uid, pv, false); if (!src.empty() || !Pv508BigPending(key)) break; Sleep(100); }
            if (src.empty()) src = PhotoCdn506Big(uid, pv, false);
            SetCursor(oc);
            Log395("FIX508 save: _big " + std::string(src.empty() ? "not available" : "fetched") + " uid=" + uid + " pv=" + std::to_string(pv) + " waited " + std::to_string(GetTickCount64() - t0) + " ms");
        }
    }
    if (src.empty()) src = Pv508BigOf(path);
    if (src.empty() && !path.empty() && FileOk359(path)) src = path;
    if (src.empty() && hasId) { const std::wstring t = ChatPhoto382(uid, pv); if (!t.empty() && FileOk359(t)) src = t; }
    if (src.empty() && hasId) src = PhotoCdn505(uid, pv);
    if (src.empty()) { Log395("FIX508 save: no image file available uid=" + uid + " pv=" + std::to_string(pv)); MessageBeep(MB_ICONWARNING); return; }
    std::wstring def;
    if (hasId) def = U2W380(uid) + L"_" + std::to_wstring(pv) + L".jpg";
    else { const size_t sl = src.find_last_of(L"\\/"); def = sl == std::wstring::npos ? src : src.substr(sl + 1); const size_t bg = def.find(L"_big."); if (bg != std::wstring::npos) def.erase(bg, 4); const size_t dt = def.rfind(L'.'); if (dt != std::wstring::npos) def.resize(dt); def += L".jpg"; }
    wchar_t fn[MAX_PATH] = {}; wcsncpy_s(fn, def.c_str(), _TRUNCATE);
    OPENFILENAMEW of = {}; of.lStructSize = sizeof(of); of.hwndOwner = (owner && IsWindow(owner)) ? owner : g_hWnd; of.lpstrFilter = L"JPEG (*.jpg)\0*.jpg;*.jpeg\0"; of.nFilterIndex = 1;
    of.lpstrFile = fn; of.nMaxFile = MAX_PATH; of.lpstrDefExt = L"jpg"; of.Flags = OFN_OVERWRITEPROMPT | OFN_PATHMUSTEXIST | OFN_NOCHANGEDIR | OFN_EXPLORER | OFN_HIDEREADONLY;
    if (!GetSaveFileNameW(&of)) { Log395("FIX508 save: dialog cancelled (err=" + std::to_string(CommDlgExtendedError()) + ")"); return; }
    const std::wstring dst = fn; bool ok = false; const char* how = "copy";
    if (Pv508IsJpg(src)) ok = CopyFileW(src.c_str(), dst.c_str(), FALSE) != 0;
    else {   // not a JPEG on disk (e.g. png cache) -> re-encode as a real .jpg
        how = "re-encode"; CLSID jc; Gdiplus::Bitmap* b = Gdiplus::Bitmap::FromFile(src.c_str());
        if (b && b->GetLastStatus() == Gdiplus::Ok && Pv508JpgClsid(&jc)) ok = b->Save(dst.c_str(), &jc, nullptr) == Gdiplus::Ok; delete b;
    }
    Log395(std::string("FIX508 save image ") + (ok ? "OK " : "FAILED ") + how + " " + W2U359(src) + " -> " + W2U359(dst));
    if (!ok) MessageBeep(MB_ICONWARNING);
}
