        const RECT xr = F380XRect((int)rc.right); if (PtInRect(&xr, pt)) { out = HTCLIENT; return true; }
        const int b = UIS(6); const bool L = pt.x < b, R = pt.x >= rc.right - b, T = pt.y < b, B = pt.y >= rc.bottom - b;
        out = T ? (L ? HTTOPLEFT : R ? HTTOPRIGHT : HTTOP) : B ? (L ? HTBOTTOMLEFT : R ? HTBOTTOMRIGHT : HTBOTTOM) : L ? HTLEFT : R ? HTRIGHT : HTCAPTION;
