static int BtnTxtW495(HDC dc, const std::wstring& s) { if (s.empty()) return 0; SIZE sz = {}; GetTextExtentPoint32W(dc, s.c_str(), (int)s.size(), &sz); return (int)sz.cx; }
static void BtnSplit495(HDC dc, const std::wstring& label, int maxW, std::wstring& a, std::wstring& b) {
    a = label; b.clear(); if (label.empty() || BtnTxtW495(dc, label) <= maxW) return;
    int split = -1;
    for (int i = 0; i < (int)label.size(); ++i) {
        if (label[i] == L' ' || label[i] == L'-') {
            const std::wstring left = label.substr(0, label[i] == L'-' ? (i + 1) : i);
            if (BtnTxtW495(dc, left) <= maxW) split = label[i] == L'-' ? (i + 1) : i;
        }
    }
    if (split > 0) {
        a = label.substr(0, split); while (!a.empty() && a.back() == L' ') a.pop_back();
        b = label.substr(split); while (!b.empty() && b.front() == L' ') b.erase(b.begin());
        return;
    }
    int j = 1; while (j < (int)label.size() && BtnTxtW495(dc, label.substr(0, j + 1)) <= maxW) ++j;
    a = label.substr(0, std::max(1, j)); b = label.substr(a.size());
}
static void BtnDraw495(HDC dc, RECT tr, const std::wstring& label, bool on, bool hot) {   // FIX495: 2 lines first, then shrink UIF11->8 so it fits; no ellipsis
    const int maxW = std::max(0, (int)(tr.right - tr.left)); const int minPx = UIF(8); int fontPx = UIF(11);
    std::wstring a, b; HFONT lf = nullptr;
    auto apply = [&](int fp) {
        if (lf) { SelectObject(dc, GetStockObject(DEFAULT_GUI_FONT)); DeleteObject(lf); lf = nullptr; }
        lf = CreateFontW(-fp, 0, 0, 0, FW_BOLD, FALSE, FALSE, FALSE, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, CLEARTYPE_QUALITY, DEFAULT_PITCH | FF_DONTCARE, UiFace());
        SelectObject(dc, lf); BtnSplit495(dc, label, maxW, a, b);
        return BtnTxtW495(dc, a) <= maxW && (b.empty() || BtnTxtW495(dc, b) <= maxW);
    };
    while (fontPx > minPx && !apply(fontPx)) --fontPx;
    if (!lf) apply(fontPx);
    SetBkMode(dc, TRANSPARENT); SetTextColor(dc, on ? (hot ? RGB(255, 255, 255) : RGB(214, 236, 220)) : RGB(120, 124, 122));
    TEXTMETRIC tm = {}; GetTextMetricsW(dc, &tm); const int lh = std::max(1, (int)tm.tmHeight), nln = b.empty() ? 1 : 2;
    const int y0 = tr.top + std::max(0, ((int)(tr.bottom - tr.top) - nln * lh) / 2);
    RECT r1 = { tr.left, y0, tr.right, y0 + lh }; DrawTextW(dc, a.c_str(), -1, &r1, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX);
    if (!b.empty()) { RECT r2 = { tr.left, y0 + lh, tr.right, y0 + 2 * lh }; DrawTextW(dc, b.c_str(), -1, &r2, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX); }
    SelectObject(dc, GetStockObject(DEFAULT_GUI_FONT)); if (lf) DeleteObject(lf);
}
